-- ===== operator views (versionless; always rewritten to this file's definitions) =====

DROP VIEW IF EXISTS acta.alerts_view;
CREATE VIEW acta.alerts_view AS
SELECT
    a.id AS alert_id,
    a.alert_ref,
    ns.name AS namespace,
    a.job_id,
    a.job_ref,
    j.definition_id,
    d.name AS job_name,
    CASE a.origin_code WHEN 10 THEN 'automatic' WHEN 20 THEN 'manual' END AS origin,
    a.origin_code,
    CASE a.severity_code WHEN 10 THEN 'info' WHEN 20 THEN 'warning' WHEN 30 THEN 'error' WHEN 40 THEN 'critical' END AS severity,
    a.severity_code,
    CASE a.kind_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'first-failure' WHEN 20 THEN 'threshold-reached' WHEN 30 THEN 'final-failure' WHEN 40 THEN 'manual' END AS kind,
    a.kind_code,
    CASE a.delivery_status_code WHEN 10 THEN 'pending' WHEN 20 THEN 'retry-after' WHEN 30 THEN 'suppressed' WHEN 100 THEN 'delivered' WHEN 200 THEN 'failed' END AS delivery_status,
    a.delivery_status_code,
    a.title,
    a.message,
    a.channel_name,
    a.dedupe_key AS deduplication_key,
    a.occurrence_count,
    a.resolved_at_utc,
    a.retry_count,
    a.retry_after_utc,
    a.created_at_utc,
    a.modified_at_utc,
    a.version
FROM acta.alerts AS a
JOIN acta.namespaces AS ns ON ns.id = a.namespace_id
LEFT JOIN acta.jobs AS j ON j.id = a.job_id
LEFT JOIN acta.definitions AS d ON d.id = j.definition_id;

DROP VIEW IF EXISTS acta.checkpoints_view;
CREATE VIEW acta.checkpoints_view AS
SELECT
    c.job_id,
    j.job_ref,
    ns.name AS namespace,
    d.name AS job_name,
    c.name AS checkpoint_name,
    CASE c.kind_code WHEN 10 THEN 'variable' WHEN 20 THEN 'signal' WHEN 30 THEN 'timer' WHEN 40 THEN 'progress' WHEN 50 THEN 'child-latch' END AS kind,
    c.kind_code,
    CASE c.status_code WHEN 10 THEN 'pending' WHEN 20 THEN 'set' WHEN 100 THEN 'consumed' END AS state,
    c.status_code,
    c.due_at_utc,
    CASE c.value_format_id
        WHEN 0 /* JobPayloadFormat.None */ THEN 'none'
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE 'custom-' || c.value_format_id::TEXT
    END AS value_format,
    CASE WHEN c.value_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */) THEN CONVERT_FROM(c.value, 'UTF8') END
        AS value_text,
    c.created_at_utc,
    c.modified_at_utc,
    c.version
FROM acta.checkpoints AS c
JOIN acta.jobs AS j ON j.id = c.job_id
JOIN acta.namespaces AS ns ON ns.id = j.namespace_id
JOIN acta.definitions AS d ON d.id = j.definition_id;

DROP VIEW IF EXISTS acta.definitions_view;
CREATE VIEW acta.definitions_view AS
SELECT
    d.id AS definition_id,
    ns.name AS namespace,
    d.name AS job_name,
    CASE d.status_code WHEN 10 THEN 'active' WHEN 240 THEN 'retired' END AS status,
    d.status_code,
    d.definition_hash,
    d.manifest_generation_at_utc,
    d.input_type_name,
    d.input_format_name,
    d.output_type_name,
    d.output_format_name,
    CASE d.priority_code_effective WHEN 0 THEN 'bulk' WHEN 50 THEN 'normal' WHEN 70 THEN 'high' WHEN 85 THEN 'critical' WHEN 100 THEN 'realtime' END AS priority,
    d.priority_code_effective AS priority_code,
    d.priority_code AS priority_default_code,
    d.priority_code_override AS priority_override_code,
    d.max_attempts_effective AS max_attempts,
    d.max_attempts AS max_attempts_default,
    d.max_attempts_override,
    d.backoff_effective AS backoff,
    d.backoff AS backoff_default,
    d.backoff_override,
    d.execution_timeout_seconds_effective AS execution_timeout_seconds,
    d.execution_timeout_seconds AS execution_timeout_seconds_default,
    d.execution_timeout_seconds_override,
    d.deadline_seconds_effective AS deadline_seconds,
    d.deadline_seconds AS deadline_seconds_default,
    d.deadline_seconds_override,
    CASE d.deadline_behavior_code_effective WHEN 10 THEN 'strict' WHEN 20 THEN 'advisory' END AS deadline_behavior,
    d.deadline_behavior_code_effective AS deadline_behavior_code,
    d.deadline_behavior_code AS deadline_behavior_default_code,
    d.deadline_behavior_code_override AS deadline_behavior_override_code,
    d.retention_seconds_effective AS retention_seconds,
    d.retention_seconds AS retention_seconds_default,
    d.retention_seconds_override,
    CASE d.audit_level_code_effective WHEN 0 THEN 'off' WHEN 10 THEN 'failures' WHEN 20 THEN 'audit' END AS audit_level,
    d.audit_level_code_effective AS audit_level_code,
    d.audit_level_code AS audit_level_default_code,
    d.audit_level_code_override AS audit_level_override_code,
    CASE d.alert_profile_code_effective WHEN 0 THEN 'none' WHEN 10 THEN 'on-failure' WHEN 20 THEN 'info' WHEN 30 THEN 'on-terminal' WHEN 40 THEN 'sys-critical' END AS alert_profile,
    d.alert_profile_code_effective AS alert_profile_code,
    d.alert_profile_code AS alert_profile_default_code,
    d.alert_profile_code_override AS alert_profile_override_code,
    d.alert_channel_name_effective AS alert_channel_name,
    d.alert_channel_name AS alert_channel_name_default,
    d.alert_channel_name_override,
    d.runbook_url_effective AS runbook_url,
    d.runbook_url AS runbook_url_default,
    d.runbook_url_override,
    d.created_at_utc,
    d.modified_at_utc,
    d.version
FROM acta.definitions AS d
JOIN acta.namespaces AS ns ON ns.id = d.namespace_id;

DROP VIEW IF EXISTS acta.jobs_view;
CREATE VIEW acta.jobs_view AS
SELECT
    j.id AS job_id,
    j.job_ref,
    ns.name AS namespace,
    d.name AS job_name,
    CASE r.status_code WHEN 10 THEN 'ready' WHEN 20 THEN 'suspended' WHEN 30 THEN 'paused' WHEN 40 THEN 'dispatched' WHEN 50 THEN 'executing' WHEN 100 THEN 'succeeded' WHEN 200 THEN 'failed' WHEN 220 THEN 'cancelled' END AS status,
    r.status_code,
    j.deduplication_key,
    j.correlation_key,
    j.exclusive_key,
    j.parent_id,
    COALESCE(j.lineage_root_id, j.id) AS lineage_root_job_id,
    root.job_ref AS lineage_root_job_ref,
    j.tenant_id,
    t.tenant_key,
    CASE r.priority_code WHEN 0 THEN 'bulk' WHEN 50 THEN 'normal' WHEN 70 THEN 'high' WHEN 85 THEN 'critical' WHEN 100 THEN 'realtime' END AS priority,
    r.priority_code,
    CASE j.input_format_id
        WHEN 0 /* JobPayloadFormat.None */ THEN 'none'
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE 'custom-' || j.input_format_id::TEXT
    END AS input_format,
    CASE WHEN j.input_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */) THEN CONVERT_FROM(j.input, 'UTF8') END
        AS input_text,
    lr.execution_number AS last_result_execution_number,
    CASE lr.result_format_id
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE CASE WHEN lr.result_format_id IS NULL THEN NULL ELSE 'custom-' || lr.result_format_id::TEXT END
    END AS last_result_format,
    CASE
        WHEN lr.result_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */) THEN CONVERT_FROM(lr.result, 'UTF8')
    END AS last_result_text,
    lr.created_at_utc AS last_result_created_at_utc,
    r.next_run_at_utc,
    r.execution_number,
    r.failure_count,
    r.leased_by_worker_id,
    w.host AS leased_by_worker_host,
    r.lease_expires_at_utc,
    r.retention_until_utc,
    j.created_at_utc,
    r.modified_at_utc,
    r.version
FROM acta.jobs AS j
JOIN acta.runtimes AS r ON r.job_id = j.id
JOIN acta.namespaces AS ns ON ns.id = j.namespace_id
JOIN acta.definitions AS d ON d.id = j.definition_id
LEFT JOIN acta.jobs AS root ON root.id = COALESCE(j.lineage_root_id, j.id)
LEFT JOIN acta.tenants AS t ON t.id = j.tenant_id
LEFT JOIN acta.workers AS w ON w.id = r.leased_by_worker_id
LEFT JOIN acta.results AS lr
    ON
        lr.job_id = j.id
        AND lr.execution_number = (
            SELECT MAX(rr.execution_number) FROM acta.results AS rr
            WHERE rr.job_id = j.id
        );

DROP VIEW IF EXISTS acta.schedules_view;
CREATE VIEW acta.schedules_view AS
SELECT
    s.id AS schedule_id,
    ns.name AS namespace,
    s.job_id,
    j.job_ref,
    s.definition_id,
    d.name AS job_name,
    s.name AS schedule_name,
    CASE s.origin_code WHEN 20 THEN 'operator' WHEN 40 THEN 'definition' END AS origin,
    s.origin_code,
    CASE s.status_code WHEN 10 THEN 'active' WHEN 30 THEN 'paused' WHEN 230 THEN 'orphaned' END AS status,
    s.status_code,
    s.expression_effective,
    s.expression,
    s.expression_override,
    s.time_zone_id_effective,
    s.time_zone_id,
    s.time_zone_id_override,
    CASE s.expression_kind_code WHEN 10 THEN 'cron' WHEN 20 THEN 'interval' END AS expression_kind,
    s.expression_kind_code,
    CASE s.misfire_strategy_code WHEN 10 THEN 'catch-up-once' WHEN 20 THEN 'skip' END AS misfire_strategy,
    s.misfire_strategy_code,
    s.next_run_at_utc,
    s.last_occurrence_at_utc,
    s.paused_until_utc,
    s.description,
    s.reason_message,
    s.created_at_utc,
    s.modified_at_utc,
    s.version
FROM acta.schedules AS s
JOIN acta.namespaces AS ns ON ns.id = s.namespace_id
JOIN acta.jobs AS j ON j.id = s.job_id
JOIN acta.definitions AS d ON d.id = s.definition_id;

DROP VIEW IF EXISTS acta.steps_view;
CREATE VIEW acta.steps_view AS
SELECT
    s.id AS step_id,
    s.job_id,
    j.job_ref,
    ns.name AS namespace,
    d.name AS job_name,
    s.name AS step_name,
    CASE s.status_code WHEN 10 THEN 'pending' WHEN 100 THEN 'succeeded' WHEN 200 THEN 'exhausted' WHEN 230 THEN 'interrupted' END AS state,
    s.status_code,
    s.attempt_number,
    s.next_retry_at_utc,
    CASE s.reason_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'job.unclassified' WHEN 20 THEN 'job.unhandled-exception' WHEN 21 THEN 'job.lease-expired' WHEN 22 THEN 'job.execution-timeout' WHEN 23 THEN 'job.non-retryable-exception' WHEN 24 THEN 'job.deadline-exceeded' WHEN 25 THEN 'job.attempt-aborted' WHEN 30 THEN 'job.schedules-exhausted' WHEN 40 THEN 'job.control-manual' WHEN 41 THEN 'job.parent-cancelled' WHEN 42 THEN 'job.definition-retired' WHEN 50 THEN 'job.handler-rescheduled' WHEN 51 THEN 'job.handler-suspended' WHEN 52 THEN 'job.handler-failed' WHEN 53 THEN 'job.handler-cancelled' WHEN 54 THEN 'job.handler-paused' WHEN 60 THEN 'job.signal-released' WHEN 61 THEN 'job.step-retry-scheduled' WHEN 62 THEN 'job.exclusive-key-held' WHEN 63 THEN 'job.step-interrupted' WHEN 64 THEN 'job.result-oversized' WHEN 100 THEN 'worker.clean-shutdown' WHEN 101 THEN 'worker.heartbeat-stale' END AS reason,
    s.reason_code,
    s.reason_message,
    CASE s.result_format_id
        WHEN 0 /* JobPayloadFormat.None */ THEN 'none'
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE 'custom-' || s.result_format_id::TEXT
    END AS result_format,
    CASE WHEN s.result_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */) THEN CONVERT_FROM(s.result, 'UTF8') END
        AS result_text,
    s.created_at_utc,
    s.modified_at_utc,
    s.version
FROM acta.steps AS s
JOIN acta.jobs AS j ON j.id = s.job_id
JOIN acta.namespaces AS ns ON ns.id = j.namespace_id
JOIN acta.definitions AS d ON d.id = j.definition_id;

DROP VIEW IF EXISTS acta.workers_view;
CREATE VIEW acta.workers_view AS
SELECT
    w.id AS worker_id,
    w.worker_ref,
    ns.name AS namespace,
    CASE w.status_code WHEN 10 THEN 'active' WHEN 80 THEN 'draining' WHEN 100 THEN 'stopped' WHEN 200 THEN 'dead' END AS status,
    w.status_code,
    w.deployment_version,
    w.host,
    w.engine_version,
    w.dotnet_version,
    w.process_id,
    w.max_concurrency,
    w.last_seen_at_utc,
    w.created_at_utc,
    w.modified_at_utc,
    w.version
FROM acta.workers AS w
JOIN acta.namespaces AS ns ON ns.id = w.namespace_id;

DROP VIEW IF EXISTS acta.events_view;
CREATE VIEW acta.events_view AS
SELECT
    e.id AS event_id,
    e.created_at_utc,
    ns.name AS namespace,
    e.job_id,
    e.job_ref,
    e.lineage_root_id AS lineage_root_job_id,
    root.job_ref AS lineage_root_job_ref,
    e.definition_id,
    d.name AS job_name,
    CASE e.event_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'tenant.suspended' WHEN 11 THEN 'tenant.resumed' WHEN 12 THEN 'tenant.updated' WHEN 20 THEN 'namespace.suspended' WHEN 21 THEN 'namespace.resumed' WHEN 22 THEN 'namespace.updated' WHEN 30 THEN 'definition.overrides-updated' WHEN 40 THEN 'job.execution-started' WHEN 41 THEN 'job.execution-finished' WHEN 50 THEN 'job.recurring-rolled-over' WHEN 60 THEN 'job.suspended' WHEN 61 THEN 'job.rescheduled' WHEN 70 THEN 'job.cancelled' WHEN 71 THEN 'job.paused' WHEN 72 THEN 'job.resumed' WHEN 73 THEN 'job.restarted' WHEN 74 THEN 'job.reprioritized' WHEN 75 THEN 'job.purged' WHEN 76 THEN 'job.input-amended' WHEN 80 THEN 'job.signal-raised' WHEN 81 THEN 'job.state-reset' WHEN 90 THEN 'job.note-recorded' WHEN 100 THEN 'schedule.paused' WHEN 101 THEN 'schedule.resumed' WHEN 102 THEN 'schedule.pause-expired' WHEN 103 THEN 'schedule.overrides-updated' WHEN 104 THEN 'schedule.triggered' WHEN 120 THEN 'worker.started' WHEN 121 THEN 'worker.stopped' WHEN 122 THEN 'worker.died' WHEN 140 THEN 'alert.acknowledged' WHEN 141 THEN 'alert.resolved' WHEN 160 THEN 'setting.updated' WHEN 180 THEN 'outbox.requeued' WHEN 181 THEN 'outbox.discarded' END AS event,
    e.event_code,
    CASE e.actor_code WHEN 10 THEN 'sys' WHEN 20 THEN 'operator' WHEN 50 THEN 'job' WHEN 70 THEN 'worker' END AS actor,
    e.actor_code,
    e.actor_key,
    CASE e.from_status_code WHEN 10 THEN 'ready' WHEN 20 THEN 'suspended' WHEN 30 THEN 'paused' WHEN 40 THEN 'dispatched' WHEN 50 THEN 'executing' WHEN 100 THEN 'succeeded' WHEN 200 THEN 'failed' WHEN 220 THEN 'cancelled' END AS from_status,
    e.from_status_code,
    CASE e.to_status_code WHEN 10 THEN 'ready' WHEN 20 THEN 'suspended' WHEN 30 THEN 'paused' WHEN 40 THEN 'dispatched' WHEN 50 THEN 'executing' WHEN 100 THEN 'succeeded' WHEN 200 THEN 'failed' WHEN 220 THEN 'cancelled' END AS to_status,
    e.to_status_code,
    CASE e.execution_status_code WHEN 50 THEN 'executing' WHEN 100 THEN 'succeeded' WHEN 150 THEN 'rescheduled' WHEN 151 THEN 'suspended' WHEN 152 THEN 'paused' WHEN 200 THEN 'failed' WHEN 220 THEN 'cancelled' WHEN 230 THEN 'orphaned' END AS execution_status,
    e.execution_status_code,
    CASE e.reason_code WHEN 0 THEN 'unspecified' WHEN 10 THEN 'job.unclassified' WHEN 20 THEN 'job.unhandled-exception' WHEN 21 THEN 'job.lease-expired' WHEN 22 THEN 'job.execution-timeout' WHEN 23 THEN 'job.non-retryable-exception' WHEN 24 THEN 'job.deadline-exceeded' WHEN 25 THEN 'job.attempt-aborted' WHEN 30 THEN 'job.schedules-exhausted' WHEN 40 THEN 'job.control-manual' WHEN 41 THEN 'job.parent-cancelled' WHEN 42 THEN 'job.definition-retired' WHEN 50 THEN 'job.handler-rescheduled' WHEN 51 THEN 'job.handler-suspended' WHEN 52 THEN 'job.handler-failed' WHEN 53 THEN 'job.handler-cancelled' WHEN 54 THEN 'job.handler-paused' WHEN 60 THEN 'job.signal-released' WHEN 61 THEN 'job.step-retry-scheduled' WHEN 62 THEN 'job.exclusive-key-held' WHEN 63 THEN 'job.step-interrupted' WHEN 64 THEN 'job.result-oversized' WHEN 100 THEN 'worker.clean-shutdown' WHEN 101 THEN 'worker.heartbeat-stale' END AS reason,
    e.reason_code,
    e.reason_message,
    CASE e.detail_format_id
        WHEN 0 /* JobPayloadFormat.None */ THEN 'none'
        WHEN 1 /* JobPayloadFormat.Json */ THEN 'json'
        WHEN 2 /* JobPayloadFormat.Bytes */ THEN 'bytes'
        WHEN 3 /* JobPayloadFormat.Text */ THEN 'text'
        ELSE 'custom-' || e.detail_format_id::TEXT
    END AS detail_format,
    CASE WHEN e.detail_format_id IN (1 /* JobPayloadFormat.Json */, 3 /* JobPayloadFormat.Text */) THEN CONVERT_FROM(e.detail, 'UTF8') END
        AS detail_text,
    e.worker_id,
    wkr.worker_ref,
    e.execution_number,
    e.duration_ms,
    e.tenant_id
FROM acta.events AS e
JOIN acta.namespaces AS ns ON ns.id = e.namespace_id
LEFT JOIN acta.definitions AS d ON d.id = e.definition_id
LEFT JOIN acta.jobs AS root ON root.id = e.lineage_root_id
LEFT JOIN acta.workers AS wkr ON wkr.id = e.worker_id;

DROP VIEW IF EXISTS acta.tags_view;
CREATE VIEW acta.tags_view AS
SELECT
    CASE t.scope_code WHEN 20 THEN 'tenant' WHEN 30 THEN 'namespace' WHEN 40 THEN 'definition' WHEN 50 THEN 'job' WHEN 60 THEN 'schedule' WHEN 70 THEN 'worker' WHEN 80 THEN 'alert' WHEN 90 THEN 'event' END AS scope,
    t.scope_code,
    t.scope_id,
    ns.name AS namespace,
    t.namespace_id,
    t.name AS tag_name,
    t.value AS tag_value,
    t.value_search AS tag_value_search
FROM acta.tags AS t
LEFT JOIN acta.namespaces AS ns ON ns.id = t.namespace_id;

-- ===== routines (versionless; always rewritten to this file's definitions) =====

CREATE OR REPLACE FUNCTION acta.acknowledge_job_alert(
    p_alert_ref UUID,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_message VARCHAR
)
RETURNS TABLE (out_action SMALLINT, out_acknowledged_at_utc TIMESTAMPTZ, out_resolved_at_utc TIMESTAMPTZ)
LANGUAGE plpgsql
AS $$
DECLARE
    v_namespace_id SMALLINT;
    v_job_id BIGINT;
    v_job_ref UUID;
    v_ack TIMESTAMPTZ;
    v_resolved TIMESTAMPTZ;
    v_definition_id INT;
    v_lineage_root_id BIGINT;
    v_execution_number INT;
BEGIN
    SELECT a.namespace_id, a.job_id, a.job_ref, a.acknowledged_at_utc, a.resolved_at_utc
    INTO v_namespace_id, v_job_id, v_job_ref, v_ack, v_resolved
    FROM acta.alerts a
    WHERE a.alert_ref = p_alert_ref
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::TIMESTAMPTZ, NULL::TIMESTAMPTZ;
        RETURN;
    END IF;

    IF v_ack IS NOT NULL THEN
        RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, v_ack, v_resolved;
        RETURN;
    END IF;

    SELECT j.definition_id, j.lineage_root_id INTO v_definition_id, v_lineage_root_id
    FROM acta.jobs j
    WHERE j.id = v_job_id;
    SELECT r.execution_number INTO v_execution_number
    FROM acta.runtimes r
    WHERE r.job_id = v_job_id;

    v_ack := now();

    UPDATE acta.alerts
    SET
        acknowledged_at_utc = v_ack,
        modified_at_utc = now(),
        version = version + 1
    WHERE alert_ref = p_alert_ref;

    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        worker_id,
        from_status_code,
        to_status_code,
        execution_status_code,
        duration_ms,
        reason_code,
        reason_message)
    VALUES (
        140 /* EventCode.AlertAcknowledged */,
        now(),
        v_namespace_id,
        p_actor_code,
        p_actor_key,
        v_job_id,
        v_job_ref,
        v_execution_number,
        COALESCE(v_lineage_root_id, v_job_id),
        v_definition_id,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        p_reason_message);

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, v_ack, v_resolved;
END;
$$;

CREATE OR REPLACE FUNCTION acta.raise_job_alert(
    p_namespace_name VARCHAR,
    p_job_id BIGINT,
    p_origin_code SMALLINT,
    p_severity_code SMALLINT,
    p_kind_code SMALLINT,
    p_title VARCHAR,
    p_message VARCHAR,
    p_channel_name VARCHAR,
    p_delivery_status_code SMALLINT,
    p_dedupe_key VARCHAR,
    p_source_event_id BIGINT,
    p_alert_ref UUID
)
-- out_-prefixed (RegisterScheduledJobs precedent): RETURNS TABLE names become plpgsql variables, and
-- bare column names would make every occurrence_count / last_projected_event_id reference ambiguous.
RETURNS TABLE (out_occurrence_count INT, out_last_projected_event_id BIGINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_occurrence_count INT;
    v_last_projected_event_id BIGINT;
    v_ns SMALLINT;
    v_job_ref UUID;
BEGIN

    SELECT id INTO v_ns FROM acta.namespaces WHERE name = p_namespace_name;
    IF v_ns IS NULL THEN
        RAISE EXCEPTION 'raise_job_alert: unknown namespace ''%''', p_namespace_name;
    END IF;

    SELECT job_ref INTO v_job_ref FROM acta.jobs WHERE id = p_job_id;

    IF p_job_id IS NOT NULL AND v_job_ref IS NULL THEN
        RAISE EXCEPTION 'ACTA:ALERT_UNKNOWN_JOB:raise_job_alert: unknown job id'
            USING ERRCODE = 'P0001';
    END IF;

    IF p_dedupe_key IS NULL THEN
        INSERT INTO acta.alerts (
            namespace_id,
            alert_ref,
            job_id,
            job_ref,
            origin_code,
            severity_code,
            kind_code,
            title,
            message,
            channel_name,
            dedupe_key,
            occurrence_count,
            last_projected_event_id,
            delivery_status_code,
            retry_count,
            created_at_utc,
            modified_at_utc,
            version)
        VALUES (
            v_ns,
            p_alert_ref,
            p_job_id,
            v_job_ref,
            p_origin_code,
            p_severity_code,
            p_kind_code,
            p_title,
            p_message,
            p_channel_name,
            NULL,
            1,
            p_source_event_id,
            p_delivery_status_code,
            0,
            now(),
            now(),
            0);
        RETURN QUERY SELECT 1, p_source_event_id;
        RETURN;
    END IF;

    -- One OPEN row per (namespace_id, dedupe_key) - the incident. INSERT ... SELECT rather than VALUES
    -- so the insert arm can carry the ghost guard below.
    INSERT INTO acta.alerts (
        namespace_id,
        alert_ref,
        job_id,
        job_ref,
        origin_code,
        severity_code,
        kind_code,
        title,
        message,
        channel_name,
        dedupe_key,
        occurrence_count,
        last_projected_event_id,
        delivery_status_code,
        retry_count,
        created_at_utc,
        modified_at_utc,
        version)
    SELECT
        v_ns,
        p_alert_ref,
        p_job_id,
        v_job_ref,
        p_origin_code,
        p_severity_code,
        p_kind_code,
        p_title,
        p_message,
        p_channel_name,
        p_dedupe_key,
        1,
        p_source_event_id,
        p_delivery_status_code,
        0,
        now(),
        now(),
        0
    -- Ghost guard: a failure replayed after its incident closed must not open one behind the events
    -- this identity has already absorbed - which is why it compares against every row of the identity,
    -- not just an open one. NULL, hence never blocking, for a manual raise, which carries no event.
    WHERE NOT EXISTS (
        SELECT 1
        FROM acta.alerts g
        WHERE
            g.namespace_id = v_ns
            AND g.dedupe_key = p_dedupe_key
            AND g.last_projected_event_id >= p_source_event_id
    )
    -- The conflict target is the filtered unique index, so a resolved row is invisible to it and the
    -- next failure opens a fresh incident instead of re-opening the closed one.
    ON CONFLICT (namespace_id, dedupe_key) WHERE dedupe_key IS NOT NULL AND resolved_at_utc IS NULL
    DO UPDATE SET
        job_id = EXCLUDED.job_id,
        job_ref = EXCLUDED.job_ref,
        origin_code = EXCLUDED.origin_code,
        severity_code = EXCLUDED.severity_code,
        kind_code = EXCLUDED.kind_code,
        title = EXCLUDED.title,
        message = EXCLUDED.message,
        channel_name = EXCLUDED.channel_name,
        occurrence_count = acta.alerts.occurrence_count + 1,
        last_projected_event_id = COALESCE(EXCLUDED.last_projected_event_id, acta.alerts.last_projected_event_id),
        modified_at_utc = now(),
        version = acta.alerts.version + 1
    WHERE
        p_source_event_id IS NULL
        OR acta.alerts.last_projected_event_id IS NULL
        OR p_source_event_id > acta.alerts.last_projected_event_id
    RETURNING occurrence_count, last_projected_event_id INTO v_occurrence_count, v_last_projected_event_id;

    -- Nothing written: a replay-held update or a ghost-blocked insert. The identity's newest row has
    -- already absorbed this event or a newer one, so its count and mark let the caller re-assert only
    -- the escalation this very event earned - never one for a neighbour the incident never counted.
    IF v_occurrence_count IS NULL THEN
        SELECT a.occurrence_count, a.last_projected_event_id
        INTO v_occurrence_count, v_last_projected_event_id
        FROM acta.alerts a
        WHERE
            a.namespace_id = v_ns
            AND a.dedupe_key = p_dedupe_key
        ORDER BY a.id DESC
        LIMIT 1;
    END IF;

    RETURN QUERY SELECT v_occurrence_count, v_last_projected_event_id;
END;
$$;

-- CREATE OR REPLACE across arities creates an overload instead of replacing; drop the retired
-- signature (with p_dedupe_window_start_utc) so pre-existing installs cannot resolve the stale form.
DROP FUNCTION IF EXISTS acta.raise_job_alert(
    VARCHAR, BIGINT, SMALLINT, SMALLINT, SMALLINT, VARCHAR, VARCHAR, VARCHAR, SMALLINT, VARCHAR,
    TIMESTAMPTZ, BIGINT, UUID
);

CREATE OR REPLACE FUNCTION acta.resolve_job_alert_manual(
    p_alert_ref UUID,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_message VARCHAR
)
RETURNS TABLE (out_action SMALLINT, out_acknowledged_at_utc TIMESTAMPTZ, out_resolved_at_utc TIMESTAMPTZ)
LANGUAGE plpgsql
AS $$
DECLARE
    v_namespace_id SMALLINT;
    v_job_id BIGINT;
    v_job_ref UUID;
    v_ack TIMESTAMPTZ;
    v_resolved TIMESTAMPTZ;
    v_definition_id INT;
    v_lineage_root_id BIGINT;
    v_execution_number INT;
BEGIN
    SELECT a.namespace_id, a.job_id, a.job_ref, a.acknowledged_at_utc, a.resolved_at_utc
    INTO v_namespace_id, v_job_id, v_job_ref, v_ack, v_resolved
    FROM acta.alerts a
    WHERE a.alert_ref = p_alert_ref
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::TIMESTAMPTZ, NULL::TIMESTAMPTZ;
        RETURN;
    END IF;

    IF v_resolved IS NOT NULL THEN
        RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, v_ack, v_resolved;
        RETURN;
    END IF;

    SELECT j.definition_id, j.lineage_root_id INTO v_definition_id, v_lineage_root_id
    FROM acta.jobs j
    WHERE j.id = v_job_id;
    SELECT r.execution_number INTO v_execution_number
    FROM acta.runtimes r
    WHERE r.job_id = v_job_id;

    v_resolved := now();

    UPDATE acta.alerts
    SET
        resolved_at_utc = v_resolved,
        /* Same settlement as the automatic resolve: a queued notification for a condition an operator has
           declared cleared is cancelled, and an already-settled status stands as the record of what the
           send actually did. */
        delivery_status_code = CASE
            WHEN delivery_status_code IN (10 /* AlertDeliveryStatusCode.Pending */, 20 /* AlertDeliveryStatusCode.RetryAfter */)
                THEN 30 /* AlertDeliveryStatusCode.Suppressed */
            ELSE delivery_status_code
        END,
        retry_after_utc = NULL,
        modified_at_utc = now(),
        version = version + 1
    WHERE alert_ref = p_alert_ref;

    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        worker_id,
        from_status_code,
        to_status_code,
        execution_status_code,
        duration_ms,
        reason_code,
        reason_message)
    VALUES (
        141 /* EventCode.AlertResolved */,
        now(),
        v_namespace_id,
        p_actor_code,
        p_actor_key,
        v_job_id,
        v_job_ref,
        v_execution_number,
        COALESCE(v_lineage_root_id, v_job_id),
        v_definition_id,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        p_reason_message);

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, v_ack, v_resolved;
END;
$$;

CREATE OR REPLACE FUNCTION acta.checkpoint_slot(
    p_action SMALLINT,
    p_job_id BIGINT,
    p_kind_code SMALLINT,
    p_name VARCHAR,
    p_value_format_id SMALLINT,
    p_value BYTEA
)
RETURNS TABLE (found INT, value_format_id SMALLINT, value BYTEA, version INTEGER)
LANGUAGE plpgsql
AS $$
DECLARE
    v_deleted INTEGER;
BEGIN
    IF p_action IN (10 /* CheckpointSlotAction.Set */, 30 /* CheckpointSlotAction.GetOrSet */)
       AND (p_value_format_id = 0 /* JobPayloadFormat.None */ OR p_value IS NULL) THEN
        RAISE EXCEPTION 'Variable payload must use a non-zero format id and non-NULL value.';
    END IF;

    IF p_action = 10 /* CheckpointSlotAction.Set */ THEN
        INSERT INTO acta.checkpoints (
            job_id,
            kind_code,
            name,
            value_format_id,
            value,
            created_at_utc,
            modified_at_utc,
            version)
        VALUES (
            p_job_id,
            p_kind_code,
            p_name,
            p_value_format_id,
            p_value,
            now(),
            now(),
            0)
        ON CONFLICT (job_id, kind_code, name) DO UPDATE SET
            value_format_id = EXCLUDED.value_format_id,
            value = EXCLUDED.value,
            modified_at_utc = now(),
            version = acta.checkpoints.version + 1;

        RETURN QUERY SELECT 1, NULL::SMALLINT, NULL::BYTEA, NULL::INTEGER;
    ELSIF p_action = 20 /* CheckpointSlotAction.Get */ THEN
        RETURN QUERY
        SELECT 1, jv.value_format_id, jv.value, jv.version
        FROM acta.checkpoints AS jv
        WHERE
            jv.job_id = p_job_id
            AND jv.kind_code = p_kind_code
            AND jv.name = p_name;

        IF NOT FOUND THEN
            RETURN QUERY SELECT 0, NULL::SMALLINT, NULL::BYTEA, NULL::INTEGER;
        END IF;
    ELSIF p_action = 30 /* CheckpointSlotAction.GetOrSet */ THEN
        LOOP
            RETURN QUERY
            SELECT 1, jv.value_format_id, jv.value, jv.version
            FROM acta.checkpoints AS jv
            WHERE
                jv.job_id = p_job_id
                AND jv.kind_code = p_kind_code
                AND jv.name = p_name;

            IF FOUND THEN
                RETURN;
            END IF;

            RETURN QUERY
            INSERT INTO acta.checkpoints AS inserted (
                job_id,
                kind_code,
                name,
                value_format_id,
                value,
                created_at_utc,
                modified_at_utc,
                version)
            VALUES (
                p_job_id,
                p_kind_code,
                p_name,
                p_value_format_id,
                p_value,
                now(),
                now(),
                0)
            ON CONFLICT (job_id, kind_code, name) DO NOTHING
            RETURNING 1, inserted.value_format_id, inserted.value, inserted.version;

            IF FOUND THEN
                RETURN;
            END IF;
        END LOOP;
    ELSIF p_action = 40 /* CheckpointSlotAction.Exists */ THEN
        RETURN QUERY
        SELECT CASE WHEN EXISTS (
            SELECT 1
            FROM acta.checkpoints AS jv
            WHERE
                jv.job_id = p_job_id
                AND jv.kind_code = p_kind_code
                AND jv.name = p_name
        ) THEN 1 ELSE 0 END, NULL::SMALLINT, NULL::BYTEA, NULL::INTEGER;
    ELSIF p_action = 50 /* CheckpointSlotAction.Delete */ THEN
        DELETE FROM acta.checkpoints AS jv
        WHERE
            jv.job_id = p_job_id
            AND jv.kind_code = p_kind_code
            AND jv.name = p_name;

        GET DIAGNOSTICS v_deleted = ROW_COUNT;
        RETURN QUERY SELECT CASE WHEN v_deleted > 0 THEN 1 ELSE 0 END, NULL::SMALLINT, NULL::BYTEA, NULL::INTEGER;
    ELSE
        RAISE EXCEPTION 'checkpoint_slot received an unknown action.';
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION acta.get_child_job_ids(
    p_parent_id BIGINT
)
RETURNS TABLE (job_id BIGINT)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    SELECT j.id
    FROM acta.jobs j
    WHERE j.parent_id = p_parent_id;
END;
$$;

CREATE OR REPLACE FUNCTION acta.get_stale_child_latches(
    p_namespace_id SMALLINT
)
RETURNS TABLE (parent_job_id BIGINT, child_job_id BIGINT, child_status SMALLINT)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    SELECT
        js.job_id,
        CASE WHEN js.name ~ '^sys\.child\.[0-9]+$' THEN substring(js.name from 11)::bigint END,
        cr.status_code
    FROM acta.checkpoints js
    INNER JOIN acta.jobs p ON p.id = js.job_id AND p.namespace_id = p_namespace_id
    LEFT JOIN acta.jobs c
        ON c.id = CASE WHEN js.name ~ '^sys\.child\.[0-9]+$' THEN substring(js.name from 11)::bigint END
    LEFT JOIN acta.runtimes cr ON cr.job_id = c.id
    WHERE
        js.kind_code = 50 /* JobCheckpointKindCode.ChildLatch */
        AND js.name ~ '^sys\.child\.[0-9]+$'
        AND js.status_code = 10 /* JobCheckpointStatusCode.Pending */
        AND (c.id IS NULL OR cr.status_code IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */));
END;
$$;

CREATE OR REPLACE FUNCTION acta.claim_batch(
    p_namespace_id SMALLINT,
    p_leased_by_worker_id INT,
    p_claim_limit INT,
    p_lease_ttl_seconds INT,
    p_start_executing BOOLEAN
)
RETURNS TABLE (
    id BIGINT,
    namespace_id SMALLINT,
    definition_id INT,
    execution_number INT,
    deduplication_key VARCHAR,
    correlation_key VARCHAR,
    exclusive_key VARCHAR,
    input_format_id SMALLINT,
    input BYTEA,
    next_run_at_utc TIMESTAMPTZ,
    lease_expires_at_utc TIMESTAMPTZ,
    created_at_utc TIMESTAMPTZ,
    failure_count SMALLINT,
    version INT,
    job_ref UUID,
    tenant_id INT,
    db_now TIMESTAMPTZ,
    next_ready_at_utc TIMESTAMPTZ
)
LANGUAGE sql
AS $$
    WITH candidates AS (
        /* Pure ready-index scan: the hot predicate and ORDER run on ix_runtimes_claim_ready alone
           via the denormalized namespace. Exclusive-key admission is executor-owned (lock store),
           taken after the start CAS, so no jobs join here. */
        SELECT r.job_id AS id
        FROM acta.runtimes r
        WHERE
            r.namespace_id = p_namespace_id
            AND r.status_code = 10 /* JobStatusCode.Ready */
            AND (r.next_run_at_utc IS NULL OR r.next_run_at_utc <= now())
        ORDER BY
            r.priority_code DESC,
            r.next_run_at_utc ASC NULLS FIRST,
            r.job_id ASC
        LIMIT p_claim_limit
        FOR UPDATE OF r SKIP LOCKED
    ),
    updated AS (
        UPDATE acta.runtimes r
        SET
            status_code = CASE WHEN p_start_executing THEN 50 /* JobStatusCode.Executing */ ELSE 40 /* JobStatusCode.Dispatched */ END,
            execution_number = r.execution_number + 1,
            leased_by_worker_id = p_leased_by_worker_id,
            lease_expires_at_utc = now() + (p_lease_ttl_seconds * INTERVAL '1 second'),
            modified_at_utc = now(),
            version = r.version + 1
        FROM candidates c
        JOIN acta.jobs j ON j.id = c.id
        WHERE r.job_id = c.id
        RETURNING
            r.job_id AS id,
            j.namespace_id,
            j.lineage_root_id,
            j.definition_id,
            j.tenant_id,
            r.execution_number,
            j.deduplication_key,
            j.correlation_key,
            j.exclusive_key,
            j.input_format_id,
            j.input,
            r.next_run_at_utc,
            j.created_at_utc,
            j.audit_level_code,
            r.failure_count,
            r.version,
            j.job_ref
    ),
    started_event AS (
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        SELECT
            40 /* EventCode.JobExecutionStarted */,
            now(),
            u.namespace_id,
            70 /* ActorCode.Worker */,
            NULL,
            u.id,
            u.job_ref,
            u.execution_number,
            COALESCE(u.lineage_root_id, u.id),
            u.definition_id,
            u.tenant_id,
            p_leased_by_worker_id,
            10 /* JobStatusCode.Ready */,
            50 /* JobStatusCode.Executing */,
            50 /* ExecutionStatusCode.Executing */,
            NULL,
            NULL,
            NULL
        FROM updated u
        WHERE
            p_start_executing
            AND u.audit_level_code = 20 /* JobAuditLevelCode.Audit */
        RETURNING 1
    ),

    clock AS (
        SELECT now() AS db_now
    )
    SELECT
        u.id,
        u.namespace_id,
        u.definition_id,
        u.execution_number,
        u.deduplication_key,
        u.correlation_key,
        u.exclusive_key,
        u.input_format_id,
        u.input,
        u.next_run_at_utc,
        now() + (p_lease_ttl_seconds * INTERVAL '1 second') AS lease_expires_at_utc,
        u.created_at_utc,
        u.failure_count,
        u.version,
        u.job_ref,
        u.tenant_id,
        NULL::timestamptz AS db_now,
        NULL::timestamptz AS next_ready_at_utc
    FROM updated u
    UNION ALL
    SELECT
        NULL::bigint,
        NULL::smallint,
        NULL::int,
        NULL::int,
        NULL::varchar,
        NULL::varchar,
        NULL::varchar,
        NULL::smallint,
        NULL::bytea,
        NULL::timestamptz,
        NULL::timestamptz,
        NULL::timestamptz,
        NULL::smallint,
        NULL::int,
        NULL::uuid,
        NULL::int,
        c.db_now,
        (SELECT MIN(COALESCE(r.next_run_at_utc, c.db_now))
            FROM acta.runtimes r
            WHERE
                r.namespace_id = p_namespace_id
                AND r.status_code = 10 /* JobStatusCode.Ready */)
    FROM clock c
    WHERE NOT EXISTS (SELECT 1 FROM updated)
    ORDER BY id NULLS LAST;
$$;

CREATE OR REPLACE FUNCTION acta.claim_one(
    p_namespace_id SMALLINT,
    p_leased_by_worker_id INT,
    p_lease_ttl_seconds INT,
    p_id BIGINT,
    p_start_executing BOOLEAN
)
RETURNS TABLE (
    id BIGINT,
    namespace_id SMALLINT,
    definition_id INT,
    execution_number INT,
    deduplication_key VARCHAR,
    correlation_key VARCHAR,
    exclusive_key VARCHAR,
    input_format_id SMALLINT,
    input BYTEA,
    next_run_at_utc TIMESTAMPTZ,
    lease_expires_at_utc TIMESTAMPTZ,
    created_at_utc TIMESTAMPTZ,
    failure_count SMALLINT,
    version INT,
    job_ref UUID,
    tenant_id INT,
    db_now TIMESTAMPTZ,
    next_ready_at_utc TIMESTAMPTZ
)
LANGUAGE sql
AS $$
    WITH candidates AS (
        SELECT r.job_id AS id
        FROM acta.runtimes r
        WHERE
            r.job_id = p_id
            AND r.namespace_id = p_namespace_id
            AND r.status_code = 10 /* JobStatusCode.Ready */
            AND (r.next_run_at_utc IS NULL OR r.next_run_at_utc <= now())
        FOR UPDATE OF r SKIP LOCKED
    ),
    updated AS (
        UPDATE acta.runtimes r
        SET
            status_code = CASE WHEN p_start_executing THEN 50 /* JobStatusCode.Executing */ ELSE 40 /* JobStatusCode.Dispatched */ END,
            execution_number = r.execution_number + 1,
            leased_by_worker_id = p_leased_by_worker_id,
            lease_expires_at_utc = now() + (p_lease_ttl_seconds * INTERVAL '1 second'),
            modified_at_utc = now(),
            version = r.version + 1
        FROM candidates c
        JOIN acta.jobs j ON j.id = c.id
        WHERE r.job_id = c.id
        RETURNING
            r.job_id AS id, j.namespace_id, j.lineage_root_id, j.definition_id, j.tenant_id,
            r.execution_number, j.deduplication_key, j.correlation_key, j.exclusive_key,
            j.input_format_id, j.input, r.next_run_at_utc, j.created_at_utc, j.audit_level_code,
            r.failure_count, r.version, j.job_ref
    ),
    started_event AS (
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        SELECT
            40 /* EventCode.JobExecutionStarted */,
            now(),
            u.namespace_id,
            70 /* ActorCode.Worker */,
            NULL,
            u.id,
            u.job_ref,
            u.execution_number,
            COALESCE(u.lineage_root_id, u.id),
            u.definition_id,
            u.tenant_id,
            p_leased_by_worker_id,
            10 /* JobStatusCode.Ready */,
            50 /* JobStatusCode.Executing */,
            50 /* ExecutionStatusCode.Executing */,
            NULL,
            NULL,
            NULL
        FROM updated u
        WHERE p_start_executing AND u.audit_level_code = 20 /* JobAuditLevelCode.Audit */
        RETURNING 1
    )
    SELECT
        u.id,
        u.namespace_id,
        u.definition_id,
        u.execution_number,
        u.deduplication_key,
        u.correlation_key,
        u.exclusive_key,
        u.input_format_id,
        u.input,
        u.next_run_at_utc,
        now() + (p_lease_ttl_seconds * INTERVAL '1 second') AS lease_expires_at_utc,
        u.created_at_utc,
        u.failure_count,
        u.version,
        u.job_ref,
        u.tenant_id,
        NULL::timestamptz AS db_now,
        NULL::timestamptz AS next_ready_at_utc
    FROM updated u;
$$;

CREATE OR REPLACE FUNCTION acta.complete_execution(
    p_id BIGINT,
    p_leased_by_worker_id INT,
    p_execution_number INT,
    p_reason_code SMALLINT,
    p_reason_message VARCHAR,
    p_result_format_id SMALLINT,
    p_result BYTEA,
    p_execution_succeeded BOOLEAN,
    p_duration_ms INT,
    p_reschedule_status_code SMALLINT DEFAULT NULL,
    p_reschedule_delay_seconds INT DEFAULT NULL,
    p_reschedule_resume_at_utc TIMESTAMPTZ DEFAULT NULL,
    p_wait_signal_name VARCHAR DEFAULT NULL,
    p_handler_status_code SMALLINT DEFAULT NULL,
    p_retention_seconds INT DEFAULT NULL,
    p_final_status SMALLINT DEFAULT NULL,
    p_job_next_run_at_utc TIMESTAMPTZ DEFAULT NULL,
    p_failure_count SMALLINT DEFAULT NULL,
    p_recurring_result_cap INT DEFAULT 0,
    p_advance_schedule_ids BIGINT [] DEFAULT NULL,
    p_advance_next_runs TIMESTAMPTZ [] DEFAULT NULL
)
RETURNS TABLE (
    action SMALLINT,
    final_status_code SMALLINT,
    final_next_run_at_utc TIMESTAMPTZ,
    db_now TIMESTAMPTZ,
    parent_released SMALLINT
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_recurring BOOLEAN := p_final_status IS NOT NULL;

    v_rearm BOOLEAN := p_reschedule_status_code IS NOT NULL;

    v_signal_suspend BOOLEAN := (p_reschedule_status_code IS NOT NULL AND p_wait_signal_name IS NOT NULL);

    v_handler BOOLEAN := p_handler_status_code IS NOT NULL;
    v_sig_state SMALLINT;
    v_to_status SMALLINT;
    v_ns SMALLINT;
    v_lineage BIGINT;
    v_def INT;
    v_tenant INT;
    v_en INT;
    v_audit SMALLINT;
    v_next_run TIMESTAMPTZ;
    v_parent_id BIGINT;
    v_cur_status SMALLINT;
    v_cur_worker INT;
    v_cur_next_run TIMESTAMPTZ;
    v_sig VARCHAR;
    v_psig SMALLINT;
    v_pstatus SMALLINT;
    v_pns SMALLINT;
    v_plineage BIGINT;
    v_pdef INT;
    v_ptenant INT;
    v_pexec INT;
    v_paudit SMALLINT;
    v_parent_released SMALLINT := 0;
    v_job_ref uuid;
    v_parent_ref uuid;
BEGIN

    IF v_signal_suspend THEN
        SELECT status_code INTO v_sig_state
        FROM acta.checkpoints
        WHERE
            job_id = p_id
            AND kind_code IN (20 /* JobCheckpointKindCode.Signal */, 50 /* JobCheckpointKindCode.ChildLatch */)
            AND name = p_wait_signal_name
        FOR UPDATE;
    END IF;

    v_to_status := CASE
        WHEN v_signal_suspend AND v_sig_state = 20 /* JobCheckpointStatusCode.Set */ THEN 10 /* JobStatusCode.Ready */
        WHEN v_signal_suspend THEN 20 /* JobStatusCode.Suspended */
        WHEN p_reschedule_status_code IS NOT NULL THEN 10 /* JobStatusCode.Ready */
        WHEN v_handler THEN p_handler_status_code
        WHEN p_final_status IS NOT NULL THEN p_final_status
        WHEN p_execution_succeeded THEN 100 /* JobStatusCode.Succeeded */
        ELSE 200 /* JobStatusCode.Failed */
    END;

    UPDATE acta.runtimes r
    SET
        status_code = v_to_status,
        next_run_at_utc = CASE
            WHEN v_signal_suspend AND v_sig_state = 20 /* JobCheckpointStatusCode.Set */ THEN now()
            WHEN v_signal_suspend THEN NULL
            WHEN v_rearm THEN COALESCE(p_reschedule_resume_at_utc, now() + make_interval(secs => p_reschedule_delay_seconds))
            WHEN v_handler THEN NULL
            WHEN v_recurring THEN p_job_next_run_at_utc
            ELSE r.next_run_at_utc END,
        failure_count = COALESCE(p_failure_count, r.failure_count),
        leased_by_worker_id = NULL,
        lease_expires_at_utc = NULL,
        retention_until_utc = CASE
            WHEN v_to_status IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
                AND p_retention_seconds IS NOT NULL
            THEN now() + make_interval(secs => p_retention_seconds)
            ELSE r.retention_until_utc END,
        modified_at_utc = now(),
        version = r.version + 1
    FROM acta.jobs j
    WHERE
        r.job_id = p_id
        AND j.id = p_id
        AND r.execution_number = p_execution_number
        AND r.status_code = 50 /* JobStatusCode.Executing */
        AND r.leased_by_worker_id = p_leased_by_worker_id
    RETURNING j.namespace_id, j.lineage_root_id, j.definition_id, j.tenant_id, r.execution_number, j.audit_level_code, r.next_run_at_utc, j.parent_id, j.job_ref
    INTO v_ns, v_lineage, v_def, v_tenant, v_en, v_audit, v_next_run, v_parent_id, v_job_ref;

    IF NOT FOUND THEN
        SELECT r.status_code, r.leased_by_worker_id, r.next_run_at_utc INTO v_cur_status, v_cur_worker, v_cur_next_run
        FROM acta.runtimes r
        WHERE r.job_id = p_id;
        IF v_cur_status IS NULL OR v_cur_status IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */) THEN
            RETURN QUERY SELECT CAST(3 /* CompleteExecutionAction.AlreadyTerminal */ AS SMALLINT), v_cur_status, v_cur_next_run, now(), CAST(0 AS SMALLINT);
        ELSIF v_cur_worker IS DISTINCT FROM p_leased_by_worker_id OR v_cur_worker IS NULL THEN
            RETURN QUERY SELECT CAST(2 /* CompleteExecutionAction.NotOwner */ AS SMALLINT), v_cur_status, v_cur_next_run, now(), CAST(0 AS SMALLINT);
        ELSE
            RETURN QUERY SELECT CAST(3 /* CompleteExecutionAction.AlreadyTerminal */ AS SMALLINT), v_cur_status, v_cur_next_run, now(), CAST(0 AS SMALLINT);
        END IF;
        RETURN;
    END IF;

    IF p_result_format_id <> 0 /* JobPayloadFormat.None */ THEN
        INSERT INTO acta.results (job_id, execution_number, result_format_id, result, created_at_utc)
        VALUES (p_id, v_en, p_result_format_id, p_result, now());
    END IF;

    IF v_recurring THEN

        IF p_advance_schedule_ids IS NOT NULL AND cardinality(p_advance_schedule_ids) > 0 THEN
            IF v_audit = 20 /* JobAuditLevelCode.Audit */ THEN
                INSERT INTO acta.events (
                    event_code,
                    created_at_utc,
                    namespace_id,
                    actor_code,
                    actor_key,
                    job_id,
                    job_ref,
                    execution_number,
                    lineage_root_id,
                    definition_id,
                    tenant_id,
                    worker_id,
                    from_status_code,
                    to_status_code,
                    execution_status_code,
                    duration_ms,
                    reason_code,
                    reason_message)
                SELECT
                    102 /* EventCode.SchedulePauseExpired */,
                    now(),
                    v_ns,
                    10 /* ActorCode.Sys */,
                    NULL,
                    p_id,
                    v_job_ref,
                    v_en,
                    COALESCE(v_lineage, p_id),
                    v_def,
                    v_tenant,
                    NULL,
                    NULL,
                    NULL,
                    NULL,
                    NULL,
                    NULL,
                    js.name
                FROM acta.schedules js
                JOIN unnest(p_advance_schedule_ids) AS a (schedule_id) ON a.schedule_id = js.id
                WHERE js.status_code = 30 /* ScheduleStatusCode.Paused */
                  AND js.paused_until_utc IS NOT NULL
                  AND js.paused_until_utc <= now();
            END IF;

            UPDATE acta.schedules js
            SET
                next_run_at_utc = adv.next_run,
                last_occurrence_at_utc = js.next_run_at_utc,
                status_code = 10 /* ScheduleStatusCode.Active */,
                paused_until_utc = NULL,
                modified_at_utc = now(),
                version = version + 1
            -- An operator pause inside the fire window wins: the advance was planned before the pause
            -- existed. Only an elapsed TIMED pause auto-resumes here, and the audit insert above shares
            -- this predicate so the event and the write cannot disagree.
            FROM unnest(p_advance_schedule_ids, p_advance_next_runs) AS adv (schedule_id, next_run)
            WHERE js.id = adv.schedule_id
              AND (
                  js.status_code <> 30 /* ScheduleStatusCode.Paused */
                  OR (js.paused_until_utc IS NOT NULL AND js.paused_until_utc <= now())
              );
        END IF;

        IF p_recurring_result_cap > 0 THEN
            DELETE FROM acta.results r
            WHERE
                r.job_id = p_id
                AND r.execution_number NOT IN (
                    SELECT execution_number
                    FROM acta.results
                    WHERE job_id = p_id
                    ORDER BY execution_number DESC
                    LIMIT p_recurring_result_cap);
        END IF;
    END IF;

    IF v_audit = 20 /* JobAuditLevelCode.Audit */
        OR (v_audit = 10 /* JobAuditLevelCode.Failures */ AND NOT p_execution_succeeded AND NOT v_rearm
            AND NOT (v_handler AND p_handler_status_code IN (220 /* JobStatusCode.Cancelled */, 30 /* JobStatusCode.Paused */))) THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            41 /* EventCode.JobExecutionFinished */,
            now(),
            v_ns,
            70 /* ActorCode.Worker */,
            NULL,
            p_id,
            v_job_ref,
            v_en,
            COALESCE(v_lineage, p_id),
            v_def,
            v_tenant,
            p_leased_by_worker_id,
            50 /* JobStatusCode.Executing */,
            v_to_status,
            CASE
                WHEN v_rearm THEN p_reschedule_status_code
                WHEN v_handler AND p_handler_status_code = 220 /* JobStatusCode.Cancelled */ THEN 220 /* ExecutionStatusCode.Cancelled */
                WHEN v_handler AND p_handler_status_code = 30 /* JobStatusCode.Paused */ THEN 152 /* ExecutionStatusCode.Paused */
                WHEN p_execution_succeeded THEN 100 /* ExecutionStatusCode.Succeeded */
                ELSE 200 /* ExecutionStatusCode.Failed */
            END,
            p_duration_ms,
            p_reason_code,
            p_reason_message);
    END IF;

    IF v_recurring AND v_audit = 20 /* JobAuditLevelCode.Audit */ AND p_final_status IN (10 /* JobStatusCode.Ready */, 30 /* JobStatusCode.Paused */) THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            CASE
                WHEN p_final_status = 10 /* JobStatusCode.Ready */ THEN 50 /* EventCode.JobRecurringRolledOver */
                ELSE 71 /* EventCode.JobPaused */
            END,
            now(),
            v_ns,
            70 /* ActorCode.Worker */,
            NULL,
            p_id,
            v_job_ref,
            v_en,
            COALESCE(v_lineage, p_id),
            v_def,
            v_tenant,
            p_leased_by_worker_id,
            50 /* JobStatusCode.Executing */,
            v_to_status,
            NULL,
            NULL,
            p_reason_code,
            p_reason_message);
    END IF;

    IF v_rearm AND v_audit = 20 /* JobAuditLevelCode.Audit */ AND NOT (v_signal_suspend AND v_to_status = 10 /* JobStatusCode.Ready */) THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            CASE WHEN p_reschedule_status_code = 151 /* ExecutionStatusCode.Suspended */ THEN 60 /* EventCode.JobSuspended */ ELSE 61 /* EventCode.JobRescheduled */ END,
            now(),
            v_ns,
            70 /* ActorCode.Worker */,
            NULL,
            p_id,
            v_job_ref,
            v_en,
            COALESCE(v_lineage, p_id),
            v_def,
            v_tenant,
            p_leased_by_worker_id,
            50 /* JobStatusCode.Executing */,
            v_to_status,
            NULL,
            NULL,
            p_reason_code,
            p_reason_message);
    END IF;

    IF v_handler AND v_audit = 20 /* JobAuditLevelCode.Audit */ AND p_handler_status_code IN (220 /* JobStatusCode.Cancelled */, 30 /* JobStatusCode.Paused */) THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            CASE WHEN p_handler_status_code = 220 /* JobStatusCode.Cancelled */ THEN 70 /* EventCode.JobCancelled */ ELSE 71 /* EventCode.JobPaused */ END,
            now(),
            v_ns,
            70 /* ActorCode.Worker */,
            NULL,
            p_id,
            v_job_ref,
            v_en,
            COALESCE(v_lineage, p_id),
            v_def,
            v_tenant,
            p_leased_by_worker_id,
            50 /* JobStatusCode.Executing */,
            v_to_status,
            NULL,
            NULL,
            p_reason_code,
            p_reason_message);
    END IF;

    IF v_to_status IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */) AND v_parent_id IS NOT NULL THEN
        v_sig := 'sys.child.' || p_id::text;

        SELECT js.status_code INTO v_psig
        FROM acta.checkpoints js
        WHERE js.job_id = v_parent_id AND js.kind_code = 50 /* JobCheckpointKindCode.ChildLatch */ AND js.name = v_sig
        FOR UPDATE;

        SELECT pr.status_code, j.namespace_id, j.lineage_root_id, j.definition_id, j.tenant_id, pr.execution_number, j.audit_level_code, j.job_ref
        INTO v_pstatus, v_pns, v_plineage, v_pdef, v_ptenant, v_pexec, v_paudit, v_parent_ref
        FROM acta.jobs j
        JOIN acta.runtimes pr ON pr.job_id = j.id
        WHERE j.id = v_parent_id
        FOR UPDATE OF pr;

        IF v_pstatus IS NOT NULL AND v_pstatus NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */) THEN
            INSERT INTO acta.checkpoints (job_id, kind_code, name, status_code, value_format_id, value, created_at_utc, modified_at_utc, version)
            VALUES (
                v_parent_id,
                50 /* JobCheckpointKindCode.ChildLatch */,
                v_sig,
                20 /* JobCheckpointStatusCode.Set */,
                1 /* JobPayloadFormat.Json */,
                convert_to(json_build_object(
                    'childJobId', p_id,
                    'status', v_to_status)::text, 'UTF8'),
                now(),
                now(),
                0)
            ON CONFLICT (job_id, kind_code, name) DO UPDATE SET
                status_code = 20 /* JobCheckpointStatusCode.Set */,
                value_format_id = EXCLUDED.value_format_id,
                value = EXCLUDED.value,
                modified_at_utc = now(),
                version = acta.checkpoints.version + 1;

            IF v_paudit = 20 /* JobAuditLevelCode.Audit */ THEN
                INSERT INTO acta.events (
                    event_code,
                    created_at_utc,
                    namespace_id,
                    actor_code,
                    actor_key,
                    job_id,
                    job_ref,
                    execution_number,
                    lineage_root_id,
                    definition_id,
                    tenant_id,
                    worker_id,
                    from_status_code,
                    to_status_code,
                    execution_status_code,
                    duration_ms,
                    reason_code,
                    reason_message)
                VALUES (
                    80 /* EventCode.JobSignalRaised */,
                    now(),
                    v_pns,
                    10 /* ActorCode.Sys */,
                    NULL,
                    v_parent_id,
                    v_parent_ref,
                    v_pexec,
                    COALESCE(v_plineage, v_parent_id),
                    v_pdef,
                    v_ptenant,
                    NULL,
                    v_pstatus,
                    v_pstatus,
                    NULL,
                    NULL,
                    p_reason_code,
                    p_reason_message);
            END IF;

            IF v_pstatus = 20 /* JobStatusCode.Suspended */ THEN
                UPDATE acta.runtimes
                SET
                    status_code = 10 /* JobStatusCode.Ready */,
                    next_run_at_utc = now(),
                    modified_at_utc = now(),
                    version = version + 1
                WHERE job_id = v_parent_id;

                IF v_paudit = 20 /* JobAuditLevelCode.Audit */ THEN
                    INSERT INTO acta.events (
                        event_code,
                        created_at_utc,
                        namespace_id,
                        actor_code,
                        actor_key,
                        job_id,
                        job_ref,
                        execution_number,
                        lineage_root_id,
                        definition_id,
                        tenant_id,
                        worker_id,
                        from_status_code,
                        to_status_code,
                        execution_status_code,
                        duration_ms,
                        reason_code,
                        reason_message)
                    VALUES (
                        72 /* EventCode.JobResumed */,
                        now(),
                        v_pns,
                        10 /* ActorCode.Sys */,
                        NULL,
                        v_parent_id,
                        v_parent_ref,
                        v_pexec,
                        COALESCE(v_plineage, v_parent_id),
                        v_pdef,
                        v_ptenant,
                        NULL,
                        20 /* JobStatusCode.Suspended */,
                        10 /* JobStatusCode.Ready */,
                        NULL,
                        NULL,
                        60 /* JobEventReasonCode.JobSignalReleased */,
                        NULL);
                END IF;

                v_parent_released := 1;
            END IF;
        END IF;
    END IF;

    RETURN QUERY SELECT CAST(1 /* CompleteExecutionAction.Completed */ AS SMALLINT), v_to_status, v_next_run, now(), v_parent_released;
END;
$$;

CREATE OR REPLACE FUNCTION acta.complete_executions_batch(
    p_b_ordinal INT [],
    p_b_job_id BIGINT [],
    p_b_worker_id INT [],
    p_b_execution_number INT [],
    p_b_succeeded BOOLEAN [],
    p_b_duration_ms INT [],
    p_b_reason_code SMALLINT [],
    p_b_reason_message VARCHAR [],
    p_b_result_format_id SMALLINT [],
    p_b_result BYTEA [],
    p_b_failure_count SMALLINT [],
    p_b_retention_seconds INT []
)
RETURNS TABLE (ordinal INT, finalized SMALLINT)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    WITH batch AS (
        SELECT
            b.ordinal,
            b.job_id,
            b.worker_id,
            b.execution_number,
            b.succeeded,
            b.duration_ms,
            b.reason_code,
            b.reason_message,
            b.result_format_id,
            b.result,
            b.failure_count,
            b.retention_seconds
        FROM unnest(
            p_b_ordinal, p_b_job_id, p_b_worker_id, p_b_execution_number, p_b_succeeded, p_b_duration_ms,
            p_b_reason_code, p_b_reason_message, p_b_result_format_id, p_b_result, p_b_failure_count,
            p_b_retention_seconds
        ) AS b(ordinal, job_id, worker_id, execution_number, succeeded, duration_ms,
            reason_code, reason_message, result_format_id, result, failure_count, retention_seconds)
    ),
    updated AS (
        UPDATE acta.runtimes r
        SET
            status_code = CASE WHEN b.succeeded THEN 100 /* JobStatusCode.Succeeded */ ELSE 200 /* JobStatusCode.Failed */ END,
            failure_count = COALESCE(b.failure_count, r.failure_count),
            leased_by_worker_id = NULL,
            lease_expires_at_utc = NULL,
            retention_until_utc = CASE WHEN b.retention_seconds IS NOT NULL
                THEN now() + make_interval(secs => b.retention_seconds) ELSE r.retention_until_utc END,
            modified_at_utc = now(),
            version = r.version + 1
        FROM batch b
        JOIN acta.jobs j ON j.id = b.job_id
        WHERE
            r.job_id = b.job_id
            AND r.execution_number = b.execution_number
            AND r.status_code = 50 /* JobStatusCode.Executing */
            AND j.parent_id IS NULL
            AND r.leased_by_worker_id = b.worker_id
        RETURNING b.ordinal, b.job_id, b.worker_id, b.execution_number, b.succeeded, b.duration_ms,
            b.reason_code, b.reason_message, b.result_format_id, b.result,
            j.job_ref, j.namespace_id, j.lineage_root_id, j.definition_id, j.tenant_id, j.audit_level_code
    ),
    result_insert AS (
        INSERT INTO acta.results (job_id, execution_number, result_format_id, result, created_at_utc)
        SELECT u.job_id, u.execution_number, u.result_format_id, u.result, now()
        FROM updated u
        WHERE u.result_format_id <> 0 /* JobPayloadFormat.None */
        RETURNING 1
    ),
    event_insert AS (
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        SELECT
            41 /* EventCode.JobExecutionFinished */,
            now(),
            u.namespace_id,
            70 /* ActorCode.Worker */,
            NULL,
            u.job_id,
            u.job_ref,
            u.execution_number,
            COALESCE(u.lineage_root_id, u.job_id),
            u.definition_id,
            u.tenant_id,
            u.worker_id,
            50 /* JobStatusCode.Executing */,
            CASE WHEN u.succeeded THEN 100 /* JobStatusCode.Succeeded */ ELSE 200 /* JobStatusCode.Failed */ END,
            CASE WHEN u.succeeded THEN 100 /* ExecutionStatusCode.Succeeded */ ELSE 200 /* ExecutionStatusCode.Failed */ END,
            u.duration_ms,
            u.reason_code,
            u.reason_message
        FROM updated u
        WHERE
            u.audit_level_code = 20 /* JobAuditLevelCode.Audit */
            OR (u.audit_level_code = 10 /* JobAuditLevelCode.Failures */ AND NOT u.succeeded)
        RETURNING 1
    )
    SELECT b.ordinal, CAST(CASE WHEN u.ordinal IS NOT NULL THEN 1 ELSE 0 END AS SMALLINT)
    FROM batch b
    LEFT JOIN updated u ON u.ordinal = b.ordinal
    ORDER BY b.ordinal;
END;
$$;

CREATE OR REPLACE FUNCTION acta.complete_step(
    p_job_id BIGINT,
    p_name VARCHAR,
    p_succeeded BOOLEAN,
    p_result_format_id SMALLINT,
    p_result BYTEA,
    p_reason_code SMALLINT,
    p_reason_message VARCHAR,
    p_delay_seconds INT,
    p_max_attempts SMALLINT,
    p_retry_window_seconds INT,
    p_version INT
)
RETURNS TABLE (
    outcome_code SMALLINT,
    next_retry_at_utc TIMESTAMPTZ
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_now TIMESTAMPTZ := now();
    v_attempt SMALLINT;
    v_created TIMESTAMPTZ;
    v_next TIMESTAMPTZ;
    v_exhaust BOOLEAN;
    v_rows INT;
BEGIN

    SELECT a.attempt_number, a.created_at_utc INTO v_attempt, v_created
    FROM acta.steps a
    WHERE a.job_id = p_job_id AND a.name = p_name;

    IF p_succeeded THEN
        UPDATE acta.steps a
        SET
            status_code = 100 /* JobStepStatusCode.Succeeded */,
            result_format_id = p_result_format_id,
            result = p_result,
            next_retry_at_utc = NULL,
            modified_at_utc = v_now,
            version = a.version + 1
        WHERE a.job_id = p_job_id AND a.name = p_name AND a.version = p_version;
        GET DIAGNOSTICS v_rows = ROW_COUNT;

        RETURN QUERY SELECT CASE WHEN v_rows = 0
            THEN 4 /* CompleteStepOutcomeCode.StaleVersion */
            ELSE 1 /* CompleteStepOutcomeCode.Succeeded */ END::SMALLINT, NULL::TIMESTAMPTZ;
        RETURN;
    END IF;

    v_next := v_now + make_interval(secs => p_delay_seconds);
    v_exhaust := (v_attempt >= p_max_attempts)
        OR (p_retry_window_seconds IS NOT NULL
            AND v_next > v_created + make_interval(secs => p_retry_window_seconds));

    IF v_exhaust THEN
        UPDATE acta.steps a
        SET
            status_code = 200 /* JobStepStatusCode.Exhausted */,
            next_retry_at_utc = NULL,
            reason_code = p_reason_code,
            reason_message = p_reason_message,
            modified_at_utc = v_now,
            version = a.version + 1
        WHERE a.job_id = p_job_id AND a.name = p_name AND a.version = p_version;
        GET DIAGNOSTICS v_rows = ROW_COUNT;

        RETURN QUERY SELECT CASE WHEN v_rows = 0
            THEN 4 /* CompleteStepOutcomeCode.StaleVersion */
            ELSE 3 /* CompleteStepOutcomeCode.Exhausted */ END::SMALLINT, NULL::TIMESTAMPTZ;
    ELSE
        UPDATE acta.steps a
        SET
            next_retry_at_utc = v_next,
            reason_code = p_reason_code,
            reason_message = p_reason_message,
            modified_at_utc = v_now,
            version = a.version + 1
        WHERE a.job_id = p_job_id AND a.name = p_name AND a.version = p_version;
        GET DIAGNOSTICS v_rows = ROW_COUNT;

        RETURN QUERY SELECT CASE WHEN v_rows = 0
            THEN 4 /* CompleteStepOutcomeCode.StaleVersion */
            ELSE 2 /* CompleteStepOutcomeCode.RetryScheduled */ END::SMALLINT,
            CASE WHEN v_rows = 0 THEN NULL ELSE v_next END;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION acta.register_job_definitions(
    p_namespace_id SMALLINT,
    p_manifest_generation TIMESTAMPTZ,
    p_d_name VARCHAR [],
    p_d_priority_code SMALLINT [],
    p_d_max_attempts SMALLINT [],
    p_d_backoff VARCHAR [],
    p_d_execution_timeout INT [],
    p_d_deadline_seconds INT [],
    p_d_deadline_behavior SMALLINT [],
    p_d_job_retention INT [],
    p_d_input_type_name VARCHAR [],
    p_d_output_type_name VARCHAR [],
    p_d_input_format_id SMALLINT [],
    p_d_input_format_name VARCHAR [],
    p_d_output_format_id SMALLINT [],
    p_d_output_format_name VARCHAR [],
    p_d_audit_level_code SMALLINT [],
    p_d_alert_profile_code SMALLINT [],
    p_d_tenant_requirement SMALLINT [],
    p_d_alert_channel_name VARCHAR [],
    p_d_runbook_url VARCHAR [],
    p_d_display_name VARCHAR [],
    p_d_description VARCHAR [],
    p_d_definition_hash VARCHAR []
)

RETURNS TABLE (def_name VARCHAR, def_id INT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_retired_ids INT[];
BEGIN
    RETURN QUERY
    WITH batch AS (
        SELECT * FROM unnest(
            p_d_name, p_d_priority_code, p_d_max_attempts,
            p_d_backoff,
            p_d_execution_timeout, p_d_deadline_seconds, p_d_deadline_behavior, p_d_job_retention,
            p_d_input_type_name, p_d_output_type_name,
            p_d_input_format_id, p_d_input_format_name, p_d_output_format_id, p_d_output_format_name,
            p_d_audit_level_code, p_d_alert_profile_code, p_d_tenant_requirement,
            p_d_alert_channel_name, p_d_runbook_url, p_d_display_name, p_d_description, p_d_definition_hash
        ) AS b(name, priority_code, max_attempts,
            backoff,
            execution_timeout_seconds, deadline_seconds,
            deadline_behavior_code, retention_seconds,
            input_type_name, output_type_name,
            input_format_id, input_format_name, output_format_id, output_format_name,
            audit_level_code, alert_profile_code, tenant_requirement_code,
            alert_channel_name, runbook_url, display_name, description, definition_hash)
    ),
    upserted AS (
        INSERT INTO acta.definitions (
            namespace_id,
            name,
            status_code,
            input_type_name,
            output_type_name,
            input_format_id,
            input_format_name,
            output_format_id,
            output_format_name,
            priority_code,
            max_attempts,
            backoff,
            execution_timeout_seconds,
            deadline_seconds,
            deadline_behavior_code,
            retention_seconds,
            audit_level_code,
            alert_profile_code,
            tenant_requirement_code,
            alert_channel_name,
            runbook_url,
            display_name,
            description,
            definition_hash,
            manifest_generation_at_utc,
            created_at_utc,
            modified_at_utc,
            version)
        SELECT
            p_namespace_id,
            b.name,
            10 /* JobDefinitionStatusCode.Active */,
            b.input_type_name,
            b.output_type_name,
            b.input_format_id,
            b.input_format_name,
            b.output_format_id,
            b.output_format_name,
            b.priority_code,
            b.max_attempts,
            b.backoff,
            b.execution_timeout_seconds,
            b.deadline_seconds,
            b.deadline_behavior_code,
            b.retention_seconds,
            b.audit_level_code,
            b.alert_profile_code,
            b.tenant_requirement_code,
            b.alert_channel_name,
            b.runbook_url,
            b.display_name,
            b.description,
            b.definition_hash,
            p_manifest_generation,
            now(),
            now(),
            0
        FROM batch b
        ON CONFLICT (namespace_id, name) DO UPDATE SET
            status_code = 10 /* JobDefinitionStatusCode.Active */,
            input_type_name = EXCLUDED.input_type_name,
            output_type_name = EXCLUDED.output_type_name,
            input_format_id = EXCLUDED.input_format_id,
            input_format_name = EXCLUDED.input_format_name,
            output_format_id = EXCLUDED.output_format_id,
            output_format_name = EXCLUDED.output_format_name,
            priority_code = EXCLUDED.priority_code,
            max_attempts = EXCLUDED.max_attempts,
            backoff = EXCLUDED.backoff,
            execution_timeout_seconds = EXCLUDED.execution_timeout_seconds,
            deadline_seconds = EXCLUDED.deadline_seconds,
            deadline_behavior_code = EXCLUDED.deadline_behavior_code,
            retention_seconds = EXCLUDED.retention_seconds,
            audit_level_code = EXCLUDED.audit_level_code,
            alert_profile_code = EXCLUDED.alert_profile_code,
            tenant_requirement_code = EXCLUDED.tenant_requirement_code,
            alert_channel_name = EXCLUDED.alert_channel_name,
            runbook_url = EXCLUDED.runbook_url,
            display_name = EXCLUDED.display_name,
            description = EXCLUDED.description,
            definition_hash = EXCLUDED.definition_hash,
            manifest_generation_at_utc = EXCLUDED.manifest_generation_at_utc,
            modified_at_utc = now(),
            version = acta.definitions.version + 1
        WHERE
            EXCLUDED.manifest_generation_at_utc >= acta.definitions.manifest_generation_at_utc
            AND (
                acta.definitions.status_code <> 10 /* JobDefinitionStatusCode.Active */
                OR acta.definitions.definition_hash IS DISTINCT FROM EXCLUDED.definition_hash
            )
        RETURNING definitions.name, definitions.id
    )
    SELECT u.name, u.id FROM upserted u
    UNION ALL
    SELECT b.name, jd.id
    FROM batch b
    INNER JOIN acta.definitions jd
        ON jd.namespace_id = p_namespace_id AND jd.name = b.name
    WHERE NOT EXISTS (SELECT 1 FROM upserted u WHERE u.name = b.name);

    -- Retire definitions absent from the manifest and capture the ids this call actually flipped, so
    -- the cancel-sweep can be scoped to exactly that set.
    WITH retired AS (
        UPDATE acta.definitions
        SET
            status_code = 240 /* JobDefinitionStatusCode.Retired */,
            modified_at_utc = now(),
            version = version + 1
        WHERE
            namespace_id = p_namespace_id
            AND status_code = 10 /* JobDefinitionStatusCode.Active */
            AND manifest_generation_at_utc <= p_manifest_generation
            AND name <> ALL(COALESCE(p_d_name, ARRAY[]::VARCHAR[]))
        RETURNING id
    )
    SELECT COALESCE(array_agg(id), ARRAY[]::INT[]) INTO v_retired_ids FROM retired;

    -- Retirement cancel-sweep: parked rows of definitions this call transitioned to retired. Definitions
    -- retired by an earlier call keep their parked jobs (a re-arm after retirement stays as the operator
    -- left it). In-flight Dispatched/Executing rows finish their attempt untouched.
    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        tenant_id,
        worker_id,
        from_status_code,
        to_status_code,
        execution_status_code,
        duration_ms,
        reason_code,
        reason_message)
    SELECT
        70 /* EventCode.JobCancelled */,
        now(),
        j.namespace_id,
        10 /* ActorCode.Sys */,
        'sys:register-definitions',
        j.id,
        j.job_ref,
        r.execution_number,
        COALESCE(j.lineage_root_id, j.id),
        j.definition_id,
        j.tenant_id,
        NULL,
        r.status_code,
        220 /* JobStatusCode.Cancelled */,
        NULL,
        NULL,
        42 /* JobEventReasonCode.JobDefinitionRetired */,
        NULL
    FROM acta.jobs j
    JOIN acta.runtimes r ON r.job_id = j.id
    JOIN acta.definitions jd ON jd.id = j.definition_id
    WHERE
        jd.namespace_id = p_namespace_id
        AND jd.id = ANY(v_retired_ids)
        AND j.audit_level_code = 20 /* JobAuditLevelCode.Audit */
        AND r.status_code IN (10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */, 30 /* JobStatusCode.Paused */);

    UPDATE acta.runtimes r
    SET
        status_code = 220 /* JobStatusCode.Cancelled */,
        leased_by_worker_id = NULL,
        lease_expires_at_utc = NULL,
        retention_until_utc = now() + make_interval(secs => jd.retention_seconds_effective),
        modified_at_utc = now(),
        version = r.version + 1
    FROM acta.jobs j
    JOIN acta.definitions jd ON jd.id = j.definition_id
    WHERE
        j.id = r.job_id
        AND jd.namespace_id = p_namespace_id
        AND jd.id = ANY(v_retired_ids)
        AND r.status_code IN (10 /* JobStatusCode.Ready */, 20 /* JobStatusCode.Suspended */, 30 /* JobStatusCode.Paused */);
END;
$$;

-- CREATE OR REPLACE across arities creates an overload instead of replacing; drop the retired
-- signature (without tenant_requirement) so pre-existing installs cannot resolve the stale form.
DROP FUNCTION IF EXISTS acta.register_job_definitions(
    SMALLINT, TIMESTAMPTZ, VARCHAR [], SMALLINT [], SMALLINT [], VARCHAR [], INT [], INT [], SMALLINT [], INT [],
    VARCHAR [], VARCHAR [], SMALLINT [], VARCHAR [], SMALLINT [], VARCHAR [], SMALLINT [], SMALLINT [],
    VARCHAR [], VARCHAR [], VARCHAR [], VARCHAR [], VARCHAR []
);

CREATE OR REPLACE FUNCTION acta.set_job_definition_overrides(
    p_id INT,
    p_version INT,
    p_priority_code_override SMALLINT,
    p_max_attempts_override SMALLINT,
    p_backoff_override VARCHAR,
    p_execution_timeout_seconds_override INT,
    p_deadline_seconds_override INT,
    p_deadline_behavior_code_override SMALLINT,
    p_retention_seconds_override INT,
    p_audit_level_code_override SMALLINT,
    p_alert_profile_code_override SMALLINT,
    p_alert_channel_name_override VARCHAR,
    p_runbook_url_override VARCHAR,
    p_display_name_override VARCHAR,
    p_description_override VARCHAR,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_code SMALLINT,
    p_reason_message VARCHAR
)
RETURNS TABLE (action SMALLINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_ns SMALLINT;
    v_version INT;
BEGIN
    SELECT jd.namespace_id, jd.version INTO v_ns, v_version
    FROM acta.definitions jd WHERE jd.id = p_id;

    IF v_ns IS NULL THEN
        RETURN QUERY SELECT 2 /* DefinitionOverrideAction.NotFound */::SMALLINT;
        RETURN;
    END IF;

    IF v_version <> p_version THEN
        RETURN QUERY SELECT 3 /* DefinitionOverrideAction.VersionConflict */::SMALLINT;
        RETURN;
    END IF;

    UPDATE acta.definitions
    SET
        priority_code_override = p_priority_code_override,
        max_attempts_override = p_max_attempts_override,
        backoff_override = p_backoff_override,
        execution_timeout_seconds_override = p_execution_timeout_seconds_override,
        deadline_seconds_override = p_deadline_seconds_override,
        deadline_behavior_code_override = p_deadline_behavior_code_override,
        retention_seconds_override = p_retention_seconds_override,
        audit_level_code_override = p_audit_level_code_override,
        alert_profile_code_override = p_alert_profile_code_override,
        alert_channel_name_override = p_alert_channel_name_override,
        runbook_url_override = p_runbook_url_override,
        display_name_override = p_display_name_override,
        description_override = p_description_override,
        modified_at_utc = now(),
        version = version + 1
    WHERE id = p_id;

    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        worker_id,
        from_status_code,
        to_status_code,
        execution_status_code,
        duration_ms,
        reason_code,
        reason_message)
    VALUES (
        30 /* EventCode.JobDefinitionOverridesUpdated */,
        now(),
        v_ns,
        p_actor_code,
        p_actor_key,
        NULL,
        NULL,
        NULL,
        NULL,
        p_id,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        p_reason_code,
        p_reason_message);

    RETURN QUERY SELECT 1 /* DefinitionOverrideAction.Applied */::SMALLINT;
END;
$$;

CREATE OR REPLACE FUNCTION acta.cancel_job(
    p_id BIGINT,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_code SMALLINT,
    p_reason_message VARCHAR
)
RETURNS TABLE (action SMALLINT, status_code SMALLINT, parent_id BIGINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_from_status SMALLINT;
    v_namespace_id SMALLINT;
    v_lineage_root_id BIGINT;
    v_definition_id INT;
    v_tenant_id INT;
    v_execution_number INT;
    v_worker_id INT;
    v_audit_level SMALLINT;
    v_parent_id BIGINT;
    v_job_ref UUID;
    v_retention_seconds INT;
BEGIN
    SELECT
        r.status_code,
        j.namespace_id,
        j.lineage_root_id,
        j.definition_id,
        j.tenant_id,
        r.execution_number,
        r.leased_by_worker_id,
        j.audit_level_code,
        j.parent_id,
        j.job_ref
    INTO v_from_status, v_namespace_id, v_lineage_root_id, v_definition_id, v_tenant_id, v_execution_number, v_worker_id, v_audit_level, v_parent_id, v_job_ref
    FROM acta.jobs j
    JOIN acta.runtimes r ON r.job_id = j.id
    WHERE j.id = p_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::SMALLINT, NULL::BIGINT;
        RETURN;
    END IF;

    IF v_from_status NOT IN (
        30 /* JobStatusCode.Paused */,
        20 /* JobStatusCode.Suspended */,
        10 /* JobStatusCode.Ready */,
        40 /* JobStatusCode.Dispatched */,
        50 /* JobStatusCode.Executing */
    ) THEN
        RETURN QUERY SELECT 3 /* ControlAction.Rejected */::SMALLINT, v_from_status, v_parent_id;
        RETURN;
    END IF;

    SELECT jd.retention_seconds_effective
    INTO v_retention_seconds
    FROM acta.definitions jd
    WHERE jd.id = v_definition_id;

    UPDATE acta.runtimes
    SET
        status_code = 220 /* JobStatusCode.Cancelled */,
        leased_by_worker_id = NULL,
        lease_expires_at_utc = NULL,
        retention_until_utc = now() + make_interval(secs => v_retention_seconds),
        modified_at_utc = now(),
        version = version + 1
    WHERE job_id = p_id;

    IF v_audit_level = 20 /* JobAuditLevelCode.Audit */ THEN
        IF v_from_status = 50 /* JobStatusCode.Executing */ THEN
            INSERT INTO acta.events (
                event_code,
                created_at_utc,
                namespace_id,
                actor_code,
                actor_key,
                job_id,
                job_ref,
                execution_number,
                lineage_root_id,
                definition_id,
                tenant_id,
                worker_id,
                from_status_code,
                to_status_code,
                execution_status_code,
                duration_ms,
                reason_code,
                reason_message)
            VALUES (
                41 /* EventCode.JobExecutionFinished */,
                now(),
                v_namespace_id,
                p_actor_code,
                p_actor_key,
                p_id,
                v_job_ref,
                v_execution_number,
                COALESCE(v_lineage_root_id, p_id),
                v_definition_id,
                v_tenant_id,
                v_worker_id,
                50 /* JobStatusCode.Executing */,
                220 /* JobStatusCode.Cancelled */,
                220 /* ExecutionStatusCode.Cancelled */,
                NULL,
                p_reason_code,
                p_reason_message);
        END IF;

        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            70 /* EventCode.JobCancelled */,
            now(),
            v_namespace_id,
            p_actor_code,
            p_actor_key,
            p_id,
            v_job_ref,
            v_execution_number,
            COALESCE(v_lineage_root_id, p_id),
            v_definition_id,
            v_tenant_id,
            NULL,
            v_from_status,
            220 /* JobStatusCode.Cancelled */,
            NULL,
            NULL,
            p_reason_code,
            p_reason_message);
    END IF;

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, 220 /* JobStatusCode.Cancelled */::SMALLINT, v_parent_id;
END;
$$;

CREATE OR REPLACE FUNCTION acta.enqueue_batch(
    p_b_ordinal INT [],
    p_b_job_ref UUID [],
    p_b_namespace_name VARCHAR [],
    p_b_job_name VARCHAR [],
    p_b_deduplication_key VARCHAR [],
    p_b_correlation_key VARCHAR [],
    p_b_priority_override SMALLINT [],
    p_b_input_format_id SMALLINT [],
    p_b_input BYTEA [],
    p_b_exclusive_key VARCHAR [],
    p_b_next_run_at_utc TIMESTAMPTZ [],
    p_b_delay_seconds INT [],
    p_b_parent_id BIGINT [],
    p_b_tenant_key VARCHAR [],
    p_b_tenant_override BOOLEAN [],
    p_t_ordinal INT [],
    p_t_name VARCHAR [],
    p_t_value VARCHAR [],
    p_t_value_search VARCHAR []
)
RETURNS TABLE (ordinal INT, job_id BIGINT, job_ref UUID, action INT)
LANGUAGE plpgsql
AS $$
DECLARE
    batch_count INT;
    resolved_count INT;
    ns_active_count INT;
    parent_count INT;
    parent_live INT;
BEGIN

    batch_count := COALESCE(array_length(p_b_ordinal, 1), 0);

    SELECT COUNT(*)
    INTO resolved_count
    FROM unnest(p_b_namespace_name, p_b_job_name) AS b(namespace_name, job_name)
    INNER JOIN acta.namespaces ns ON ns.name = b.namespace_name
    INNER JOIN acta.definitions jd
        ON jd.namespace_id = ns.id
        AND jd.name = b.job_name;

    IF batch_count IS DISTINCT FROM resolved_count THEN
        RAISE EXCEPTION 'ACTA:ENQ_ROUTE_UNKNOWN:Enqueue rejected: one or more rows reference an unknown namespace or job. Has the owning worker run InitializeAsync yet?'
            USING ERRCODE = 'P0001';
    END IF;

    SELECT COUNT(*)
    INTO ns_active_count
    FROM unnest(p_b_namespace_name, p_b_job_name) AS b(namespace_name, job_name)
    INNER JOIN acta.namespaces ns ON ns.name = b.namespace_name AND ns.status_code = 10 /* NamespaceStatusCode.Active */
    INNER JOIN acta.definitions jd
        ON jd.namespace_id = ns.id
        AND jd.name = b.job_name;

    IF batch_count IS DISTINCT FROM ns_active_count THEN
        RAISE EXCEPTION 'ACTA:ENQ_NS_SUSPENDED:Enqueue rejected: one or more rows reference a suspended namespace.'
            USING ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM unnest(p_b_namespace_name, p_b_job_name) AS b(namespace_name, job_name)
        INNER JOIN acta.namespaces ns ON ns.name = b.namespace_name
        INNER JOIN acta.definitions jd ON jd.namespace_id = ns.id AND jd.name = b.job_name
        WHERE jd.status_code <> 10 /* JobDefinitionStatusCode.Active */
    ) THEN
        RAISE EXCEPTION 'ACTA:ENQ_DEF_RETIRED:Enqueue rejected: the job definition is retired.'
            USING ERRCODE = 'P0001';
    END IF;

    SELECT COUNT(*) INTO parent_count
    FROM unnest(p_b_parent_id) AS b(parent_id)
    WHERE b.parent_id IS NOT NULL;

    IF parent_count > 0 THEN
        PERFORM j.id
        FROM acta.jobs j
        WHERE j.id IN (SELECT DISTINCT b.parent_id FROM unnest(p_b_parent_id) AS b(parent_id) WHERE b.parent_id IS NOT NULL)
        ORDER BY j.id DESC
        FOR UPDATE;
    END IF;

    SELECT COUNT(*) INTO parent_live
    FROM unnest(p_b_parent_id) AS b(parent_id)
    INNER JOIN acta.jobs pj ON pj.id = b.parent_id
    INNER JOIN acta.runtimes pr ON pr.job_id = pj.id
    WHERE pr.status_code NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */);

    IF parent_count IS DISTINCT FROM parent_live THEN
        RAISE EXCEPTION 'Enqueue rejected: one or more child rows reference a missing or terminal parent job.'
            USING ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1 FROM unnest(p_b_tenant_key) AS b(tenant_key)
        WHERE
            b.tenant_key IS NOT NULL
            AND NOT EXISTS (SELECT 1 FROM acta.tenants t WHERE t.tenant_key = b.tenant_key)
    ) THEN
        RAISE EXCEPTION 'ACTA:ENQ_TENANT_UNKNOWN:Enqueue rejected: one or more rows reference an unknown tenant.'
            USING ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1 FROM unnest(p_b_tenant_key) AS b(tenant_key)
        JOIN acta.tenants t ON t.tenant_key = b.tenant_key
        WHERE
            b.tenant_key IS NOT NULL
            AND t.status_code <> 10 /* TenantStatusCode.Active */
    ) THEN
        RAISE EXCEPTION 'ACTA:ENQ_TENANT_SUSPENDED:Enqueue rejected: one or more rows reference a suspended tenant.'
            USING ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM unnest(p_b_namespace_name, p_b_job_name, p_b_tenant_key, p_b_parent_id)
            AS b(namespace_name, job_name, tenant_key, parent_id)
        INNER JOIN acta.namespaces ns ON ns.name = b.namespace_name
        INNER JOIN acta.definitions jd ON jd.namespace_id = ns.id AND jd.name = b.job_name
        LEFT JOIN acta.jobs pj ON pj.id = b.parent_id
        WHERE
            jd.tenant_requirement_code = 10 /* JobTenantRequirementCode.Required */
            AND b.tenant_key IS NULL
            AND pj.tenant_id IS NULL
    ) THEN
        RAISE EXCEPTION 'ACTA:ENQ_TENANT_REQUIRED:Enqueue rejected: one or more rows target a definition that requires a tenant and carry none.'
            USING ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM unnest(p_b_namespace_name, p_b_job_name, p_b_tenant_key) AS b(namespace_name, job_name, tenant_key)
        INNER JOIN acta.namespaces ns ON ns.name = b.namespace_name
        INNER JOIN acta.definitions jd ON jd.namespace_id = ns.id AND jd.name = b.job_name
        WHERE
            jd.tenant_requirement_code = 20 /* JobTenantRequirementCode.Forbidden */
            AND b.tenant_key IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'ACTA:ENQ_TENANT_FORBIDDEN:Enqueue rejected: one or more rows target a definition that forbids a tenant and name one.'
            USING ERRCODE = 'P0001';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM unnest(p_b_tenant_key, p_b_parent_id, p_b_tenant_override) AS b(tenant_key, parent_id, tenant_override)
        INNER JOIN acta.tenants t ON t.tenant_key = b.tenant_key
        INNER JOIN acta.jobs pj ON pj.id = b.parent_id
        WHERE
            NOT b.tenant_override
            AND pj.tenant_id IS NOT NULL
            AND pj.tenant_id <> t.id
    ) THEN
        RAISE EXCEPTION 'ACTA:ENQ_TENANT_MISMATCH:Enqueue rejected: one or more child rows name a TenantKey that differs from the parent tenant without an explicit override.'
            USING ERRCODE = 'P0001';
    END IF;

    -- Resolve catalog + pre-allocate the job id ONCE into a temp table keyed by that id, so the inserts
    -- below read a staged, ANALYZEd set instead of re-joining a catalog CTE the planner sizes at ~1 row
    -- (which forced batch-rescanning Nested Loops after runtime state split into its own table).
    CREATE TEMP TABLE IF NOT EXISTS _enq_batch (
        id BIGINT PRIMARY KEY,
        ordinal INT NOT NULL,
        job_ref UUID NOT NULL,
        parent_id BIGINT,
        lineage_root_id BIGINT,
        deduplication_key VARCHAR,
        correlation_key VARCHAR,
        namespace_id SMALLINT NOT NULL,
        definition_id INT NOT NULL,
        tenant_id INT,
        input_format_id SMALLINT NOT NULL,
        input BYTEA,
        exclusive_key VARCHAR,
        audit_level_code SMALLINT NOT NULL,
        priority_code SMALLINT NOT NULL,
        next_run_at_utc TIMESTAMPTZ NOT NULL,
        is_child BOOLEAN NOT NULL
    ) ON COMMIT DROP;
    TRUNCATE _enq_batch;

    INSERT INTO _enq_batch (
        id,
        ordinal,
        job_ref,
        parent_id,
        lineage_root_id,
        deduplication_key,
        correlation_key,
        namespace_id,
        definition_id,
        tenant_id,
        input_format_id,
        input,
        exclusive_key,
        audit_level_code,
        priority_code,
        next_run_at_utc,
        is_child)
    SELECT
        nextval(pg_get_serial_sequence('acta.jobs', 'id')),
        b.ordinal,
        b.job_ref,
        b.parent_id,
        CASE WHEN b.parent_id IS NOT NULL THEN COALESCE(pj.lineage_root_id, pj.id) END,
        b.deduplication_key,
        COALESCE(b.correlation_key, pj.correlation_key),
        ns.id,
        jd.id,
        CASE WHEN jd.tenant_requirement_code = 20 /* JobTenantRequirementCode.Forbidden */ THEN NULL
            ELSE COALESCE(t.id, pj.tenant_id) END,
        b.input_format_id,
        b.input,
        b.exclusive_key,
        jd.audit_level_code_effective,
        COALESCE(b.priority_override, jd.priority_code_effective),
        COALESCE(b.next_run_at_utc, now() + make_interval(secs => COALESCE(b.delay_seconds, 0))),
        (b.parent_id IS NOT NULL)
    FROM unnest(
        p_b_ordinal, p_b_job_ref, p_b_namespace_name, p_b_job_name,
        p_b_deduplication_key, p_b_correlation_key, p_b_priority_override,
        p_b_input_format_id, p_b_input, p_b_exclusive_key, p_b_next_run_at_utc,
        p_b_delay_seconds, p_b_parent_id, p_b_tenant_key
    ) AS b(ordinal, job_ref, namespace_name, job_name,
        deduplication_key, correlation_key, priority_override,
        input_format_id, input, exclusive_key, next_run_at_utc,
        delay_seconds, parent_id, tenant_key)
    INNER JOIN acta.namespaces ns ON ns.name = b.namespace_name AND ns.status_code = 10 /* NamespaceStatusCode.Active */
    INNER JOIN acta.definitions jd ON jd.namespace_id = ns.id AND jd.name = b.job_name
    LEFT JOIN acta.tenants t ON t.tenant_key = b.tenant_key AND t.status_code = 10 /* TenantStatusCode.Active */
    LEFT JOIN acta.jobs pj ON pj.id = b.parent_id;

    -- Give the planner real row counts for the staged set so the inserts below stay hash/index joins.
    ANALYZE _enq_batch;

    RETURN QUERY
    WITH inserted_root AS (
        INSERT INTO acta.jobs (
            id,
            job_ref,
            lineage_root_id,
            parent_id,
            deduplication_key,
            correlation_key,
            namespace_id,
            definition_id,
            tenant_id,
            input_format_id,
            input,
            exclusive_key,
            audit_level_code,
            created_at_utc)
        OVERRIDING SYSTEM VALUE
        SELECT
            e.id,
            e.job_ref,
            NULL,
            NULL,
            e.deduplication_key,
            e.correlation_key,
            e.namespace_id,
            e.definition_id,
            e.tenant_id,
            e.input_format_id,
            e.input,
            e.exclusive_key,
            e.audit_level_code,
            now()
        FROM _enq_batch e
        WHERE NOT e.is_child
        ON CONFLICT (namespace_id, deduplication_key)
            WHERE deduplication_key IS NOT NULL AND parent_id IS NULL
            DO NOTHING
        RETURNING id
    ),
    inserted_child AS (
        INSERT INTO acta.jobs (
            id,
            job_ref,
            lineage_root_id,
            parent_id,
            deduplication_key,
            correlation_key,
            namespace_id,
            definition_id,
            tenant_id,
            input_format_id,
            input,
            exclusive_key,
            audit_level_code,
            created_at_utc)
        OVERRIDING SYSTEM VALUE
        SELECT
            e.id,
            e.job_ref,
            e.lineage_root_id,
            e.parent_id,
            e.deduplication_key,
            e.correlation_key,
            e.namespace_id,
            e.definition_id,
            e.tenant_id,
            e.input_format_id,
            e.input,
            e.exclusive_key,
            e.audit_level_code,
            now()
        FROM _enq_batch e
        WHERE e.is_child
        ON CONFLICT (parent_id, deduplication_key)
            WHERE deduplication_key IS NOT NULL AND parent_id IS NOT NULL
            DO NOTHING
        RETURNING id
    ),
    inserted AS (
        SELECT id FROM inserted_root
        UNION ALL
        SELECT id FROM inserted_child
    ),
    runtime_insert AS (
        INSERT INTO acta.runtimes (
            job_id,
            namespace_id,
            status_code,
            priority_code,
            next_run_at_utc,
            execution_number,
            failure_count,
            retention_until_utc,
            modified_at_utc,
            version)
        SELECT
            e.id,
            e.namespace_id,
            10 /* JobStatusCode.Ready */,
            e.priority_code,
            e.next_run_at_utc,
            0,
            0,
            NULL,
            now(),
            0
        FROM inserted i
        INNER JOIN _enq_batch e ON e.id = i.id
        RETURNING 1
    ),
    tag_insert AS (
        INSERT INTO acta.tags (scope_code, scope_id, namespace_id, name, value, value_search)
        SELECT 50 /* TagScopeCode.Job */, e.id, e.namespace_id, t.name, t.value, t.value_search
        FROM unnest(p_t_ordinal, p_t_name, p_t_value, p_t_value_search) AS t(ordinal, name, value, value_search)
        INNER JOIN _enq_batch e ON e.ordinal = t.ordinal
        INNER JOIN inserted i ON i.id = e.id
        RETURNING 1
    ),
    existing AS (
        SELECT e.ordinal, j.id, j.job_ref
        FROM _enq_batch e
        INNER JOIN acta.jobs j
            ON (NOT e.is_child
                AND j.namespace_id = e.namespace_id
                AND j.deduplication_key = e.deduplication_key
                AND j.parent_id IS NULL)
            OR (e.is_child
                AND j.parent_id = e.parent_id
                AND j.deduplication_key = e.deduplication_key)
        WHERE
            e.deduplication_key IS NOT NULL
            AND NOT EXISTS (
                SELECT 1
                FROM inserted i
                WHERE i.id = e.id)
    )
    SELECT
        e.ordinal,
        COALESCE(i.id, ex.id) AS job_id,
        CASE WHEN i.id IS NOT NULL THEN e.job_ref ELSE ex.job_ref END AS job_ref,
        CASE WHEN i.id IS NOT NULL
            THEN 1 /* JobEnqueueAction.Inserted */
            ELSE 2 /* JobEnqueueAction.Deduplicated */ END AS action
    FROM _enq_batch e
    LEFT JOIN inserted i ON i.id = e.id
    LEFT JOIN existing ex ON ex.ordinal = e.ordinal
    ORDER BY e.ordinal;
END;
$$;

-- CREATE OR REPLACE across arities creates an overload instead of replacing; drop the retired
-- signature (without p_b_tenant_override) so pre-existing installs cannot resolve the stale form.
DROP FUNCTION IF EXISTS acta.enqueue_batch(
    INT [], UUID [], VARCHAR [], VARCHAR [], VARCHAR [], VARCHAR [], SMALLINT [], SMALLINT [], BYTEA [],
    VARCHAR [], TIMESTAMPTZ [], INT [], BIGINT [], VARCHAR [], INT [], VARCHAR [], VARCHAR [], VARCHAR []
);

-- Only p_namespace_name and p_job_name are required; other params default (p_job_ref is server-generated
-- when omitted; p_input_format_id defaults json/none by input presence). Parameter ORDER is fixed:
-- the provider store invokes this function positionally.
CREATE OR REPLACE FUNCTION acta.enqueue_one(
    p_job_ref UUID DEFAULT GEN_RANDOM_UUID(),
    p_namespace_name VARCHAR DEFAULT NULL,
    p_job_name VARCHAR DEFAULT NULL,
    p_deduplication_key VARCHAR DEFAULT NULL,
    p_correlation_key VARCHAR DEFAULT NULL,
    p_priority_override SMALLINT DEFAULT NULL,
    p_input_format_id SMALLINT DEFAULT NULL,
    p_input BYTEA DEFAULT NULL,
    p_exclusive_key VARCHAR DEFAULT NULL,
    p_next_run_at_utc TIMESTAMPTZ DEFAULT NULL,
    p_delay_seconds INT DEFAULT NULL,
    p_parent_id BIGINT DEFAULT NULL,
    p_tenant_key VARCHAR DEFAULT NULL,
    p_tenant_override BOOLEAN DEFAULT FALSE,
    p_t_name VARCHAR [] DEFAULT NULL,
    p_t_value VARCHAR [] DEFAULT NULL,
    p_t_value_search VARCHAR [] DEFAULT NULL
)
RETURNS TABLE (ordinal INT, job_id BIGINT, job_ref UUID, action INT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_ns_id SMALLINT;
    v_ns_status SMALLINT;
    v_def_id INT;
    v_def_priority SMALLINT;
    v_def_audit SMALLINT;
    v_def_status SMALLINT;
    v_def_tenant_req SMALLINT;
    v_tenant_id INT;
    v_tenant_status SMALLINT;
    v_lineage BIGINT;
    v_parent_corr VARCHAR;
    v_parent_tenant INT;
    v_job_id BIGINT;
BEGIN
    SELECT ns.id, ns.status_code, jd.id, jd.priority_code_effective, jd.audit_level_code_effective, jd.status_code, jd.tenant_requirement_code
    INTO v_ns_id, v_ns_status, v_def_id, v_def_priority, v_def_audit, v_def_status, v_def_tenant_req
    FROM acta.namespaces ns
    INNER JOIN acta.definitions jd ON jd.namespace_id = ns.id AND jd.name = p_job_name
    WHERE ns.name = p_namespace_name;

    IF v_def_id IS NULL THEN
        RAISE EXCEPTION 'ACTA:ENQ_ROUTE_UNKNOWN:Enqueue rejected: one or more rows reference an unknown namespace or job. Has the owning worker run InitializeAsync yet?'
            USING ERRCODE = 'P0001';
    END IF;

    IF v_ns_status <> 10 /* NamespaceStatusCode.Active */ THEN
        RAISE EXCEPTION 'ACTA:ENQ_NS_SUSPENDED:Enqueue rejected: one or more rows reference a suspended namespace.'
            USING ERRCODE = 'P0001';
    END IF;

    IF v_def_status <> 10 /* JobDefinitionStatusCode.Active */ THEN
        RAISE EXCEPTION 'ACTA:ENQ_DEF_RETIRED:Enqueue rejected: the job definition is retired.'
            USING ERRCODE = 'P0001';
    END IF;

    IF p_tenant_key IS NOT NULL THEN
        SELECT t.id, t.status_code INTO v_tenant_id, v_tenant_status
        FROM acta.tenants t
        WHERE t.tenant_key = p_tenant_key;

        IF v_tenant_id IS NULL THEN
            RAISE EXCEPTION 'ACTA:ENQ_TENANT_UNKNOWN:Enqueue rejected: one or more rows reference an unknown tenant.'
                USING ERRCODE = 'P0001';
        END IF;

        IF v_tenant_status <> 10 /* TenantStatusCode.Active */ THEN
            RAISE EXCEPTION 'ACTA:ENQ_TENANT_SUSPENDED:Enqueue rejected: one or more rows reference a suspended tenant.'
                USING ERRCODE = 'P0001';
        END IF;
    END IF;

    IF v_def_tenant_req = 20 /* JobTenantRequirementCode.Forbidden */ AND p_tenant_key IS NOT NULL THEN
        RAISE EXCEPTION 'ACTA:ENQ_TENANT_FORBIDDEN:Enqueue rejected: the job definition forbids a tenant and the row names one.'
            USING ERRCODE = 'P0001';
    END IF;

    IF p_parent_id IS NOT NULL THEN
        SELECT COALESCE(pj.lineage_root_id, pj.id), pj.correlation_key, pj.tenant_id
        INTO v_lineage, v_parent_corr, v_parent_tenant
        FROM acta.jobs pj
        INNER JOIN acta.runtimes pr ON pr.job_id = pj.id
        WHERE
            pj.id = p_parent_id
            AND pr.status_code NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
        FOR UPDATE OF pj;

        IF v_lineage IS NULL THEN
            RAISE EXCEPTION 'Enqueue rejected: one or more child rows reference a missing or terminal parent job.'
                USING ERRCODE = 'P0001';
        END IF;

        IF v_def_tenant_req = 10 /* JobTenantRequirementCode.Required */ AND v_tenant_id IS NULL AND v_parent_tenant IS NULL THEN
            RAISE EXCEPTION 'ACTA:ENQ_TENANT_REQUIRED:Enqueue rejected: the job definition requires a tenant and the row carries none.'
                USING ERRCODE = 'P0001';
        END IF;

        IF v_tenant_id IS NOT NULL AND v_parent_tenant IS NOT NULL AND v_tenant_id <> v_parent_tenant AND NOT p_tenant_override THEN
            RAISE EXCEPTION 'ACTA:ENQ_TENANT_MISMATCH:Enqueue rejected: a child TenantKey differs from the parent tenant without an explicit override.'
                USING ERRCODE = 'P0001';
        END IF;

        INSERT INTO acta.jobs (
            job_ref,
            lineage_root_id,
            parent_id,
            deduplication_key,
            correlation_key,
            namespace_id,
            definition_id,
            tenant_id,
            input_format_id,
            input,
            exclusive_key,
            audit_level_code,
            created_at_utc)
        VALUES (
            p_job_ref,
            v_lineage,
            p_parent_id,
            p_deduplication_key,
            COALESCE(p_correlation_key, v_parent_corr),
            v_ns_id,
            v_def_id,
            CASE WHEN v_def_tenant_req = 20 /* JobTenantRequirementCode.Forbidden */ THEN NULL
                ELSE COALESCE(v_tenant_id, v_parent_tenant) END,
            COALESCE(p_input_format_id, CASE WHEN p_input IS NULL THEN 0 /* JobPayloadFormat.None */ ELSE 1 /* JobPayloadFormat.Json */ END),
            p_input,
            p_exclusive_key,
            v_def_audit,
            now())
        ON CONFLICT (parent_id, deduplication_key)
            WHERE deduplication_key IS NOT NULL AND parent_id IS NOT NULL
            DO NOTHING
        RETURNING id INTO v_job_id;
    ELSE
        IF v_def_tenant_req = 10 /* JobTenantRequirementCode.Required */ AND v_tenant_id IS NULL THEN
            RAISE EXCEPTION 'ACTA:ENQ_TENANT_REQUIRED:Enqueue rejected: the job definition requires a tenant and the row carries none.'
                USING ERRCODE = 'P0001';
        END IF;

        INSERT INTO acta.jobs (
            job_ref,
            lineage_root_id,
            parent_id,
            deduplication_key,
            correlation_key,
            namespace_id,
            definition_id,
            tenant_id,
            input_format_id,
            input,
            exclusive_key,
            audit_level_code,
            created_at_utc)
        VALUES (
            p_job_ref,
            NULL,
            NULL,
            p_deduplication_key,
            p_correlation_key,
            v_ns_id,
            v_def_id,
            v_tenant_id,
            COALESCE(p_input_format_id, CASE WHEN p_input IS NULL THEN 0 /* JobPayloadFormat.None */ ELSE 1 /* JobPayloadFormat.Json */ END),
            p_input,
            p_exclusive_key,
            v_def_audit,
            now())
        ON CONFLICT (namespace_id, deduplication_key)
            WHERE deduplication_key IS NOT NULL AND parent_id IS NULL
            DO NOTHING
        RETURNING id INTO v_job_id;
    END IF;

    IF v_job_id IS NOT NULL THEN
        INSERT INTO acta.runtimes (
            job_id,
            namespace_id,
            status_code,
            priority_code,
            next_run_at_utc,
            execution_number,
            failure_count,
            retention_until_utc,
            modified_at_utc,
            version)
        VALUES (
            v_job_id,
            v_ns_id,
            10 /* JobStatusCode.Ready */,
            COALESCE(p_priority_override, v_def_priority),
            COALESCE(p_next_run_at_utc, now() + make_interval(secs => COALESCE(p_delay_seconds, 0))),
            0,
            0,
            NULL,
            now(),
            0);

        INSERT INTO acta.tags (scope_code, scope_id, namespace_id, name, value, value_search)
        SELECT 50 /* TagScopeCode.Job */, v_job_id, v_ns_id, t.name, t.value, t.value_search
        FROM unnest(p_t_name, p_t_value, p_t_value_search) AS t(name, value, value_search);

        RETURN QUERY SELECT 0, v_job_id, p_job_ref, 1 /* JobEnqueueAction.Inserted */;
    ELSE
        RETURN QUERY
        SELECT 0, j.id, j.job_ref, 2 /* JobEnqueueAction.Deduplicated */
        FROM acta.jobs j
        WHERE
            (p_parent_id IS NULL
                AND j.namespace_id = v_ns_id
                AND j.deduplication_key = p_deduplication_key
                AND j.parent_id IS NULL)
            OR (p_parent_id IS NOT NULL
                AND j.parent_id = p_parent_id
                AND j.deduplication_key = p_deduplication_key);
    END IF;
END;
$$;

-- CREATE OR REPLACE across arities creates an overload instead of replacing; drop the retired
-- signature (without p_tenant_override) so pre-existing installs cannot resolve the stale form.
DROP FUNCTION IF EXISTS acta.enqueue_one(
    UUID, VARCHAR, VARCHAR, VARCHAR, VARCHAR, SMALLINT, SMALLINT, BYTEA, VARCHAR, TIMESTAMPTZ, INT,
    BIGINT, VARCHAR, VARCHAR [], VARCHAR [], VARCHAR []
);

CREATE OR REPLACE FUNCTION acta.pause_job(
    p_id BIGINT,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_code SMALLINT,
    p_reason_message VARCHAR
)
RETURNS TABLE (action SMALLINT, status_code SMALLINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_from_status SMALLINT;
    v_namespace_id SMALLINT;
    v_lineage_root_id BIGINT;
    v_definition_id INT;
    v_tenant_id INT;
    v_execution_number INT;
    v_audit_level SMALLINT;
    v_job_ref UUID;
BEGIN
    SELECT r.status_code, j.namespace_id, j.lineage_root_id, j.definition_id, j.tenant_id, r.execution_number, j.audit_level_code, j.job_ref
    INTO v_from_status, v_namespace_id, v_lineage_root_id, v_definition_id, v_tenant_id, v_execution_number, v_audit_level, v_job_ref
    FROM acta.runtimes r
    JOIN acta.jobs j ON j.id = r.job_id
    WHERE r.job_id = p_id
    FOR UPDATE OF r;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::SMALLINT;
        RETURN;
    END IF;

    IF v_from_status NOT IN (
        30 /* JobStatusCode.Paused */,
        20 /* JobStatusCode.Suspended */,
        10 /* JobStatusCode.Ready */
    ) THEN
        RETURN QUERY SELECT 3 /* ControlAction.Rejected */::SMALLINT, v_from_status;
        RETURN;
    END IF;

    UPDATE acta.runtimes
    SET
        status_code = 30 /* JobStatusCode.Paused */,
        modified_at_utc = now(),
        version = version + 1
    WHERE job_id = p_id;

    IF v_audit_level = 20 /* JobAuditLevelCode.Audit */ THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            71 /* EventCode.JobPaused */,
            now(),
            v_namespace_id,
            p_actor_code,
            p_actor_key,
            p_id,
            v_job_ref,
            v_execution_number,
            COALESCE(v_lineage_root_id, p_id),
            v_definition_id,
            v_tenant_id,
            NULL,
            v_from_status,
            30 /* JobStatusCode.Paused */,
            NULL,
            NULL,
            p_reason_code,
            p_reason_message);
    END IF;

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, 30 /* JobStatusCode.Paused */::SMALLINT;
END;
$$;

CREATE OR REPLACE FUNCTION acta.purge_job(
    p_id BIGINT,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_code SMALLINT
)
RETURNS TABLE (action SMALLINT, status_code SMALLINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_from_status SMALLINT;
    v_namespace_id SMALLINT;
    v_definition INT;
    v_tenant INT;
    v_job_ref UUID;
    v_job_name VARCHAR;
BEGIN
    SELECT r.status_code, j.namespace_id, j.definition_id, j.tenant_id, j.job_ref, d.name
    INTO v_from_status, v_namespace_id, v_definition, v_tenant, v_job_ref, v_job_name
    FROM acta.jobs j
    JOIN acta.runtimes r ON r.job_id = j.id
    JOIN acta.definitions d ON d.id = j.definition_id
    WHERE j.id = p_id
    FOR UPDATE OF j, r;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::SMALLINT;
        RETURN;
    END IF;

    IF v_from_status NOT IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */) THEN
        RETURN QUERY SELECT 3 /* ControlAction.Rejected */::SMALLINT, v_from_status;
        RETURN;
    END IF;

    -- parent_id carries no DB FK/cascade; purging a job that has child jobs would orphan the child's
    -- lineage (parent_id / lineage_root_id would point at a row that no longer exists), so reject.
    IF EXISTS (SELECT 1 FROM acta.jobs c WHERE c.parent_id = p_id) THEN
        RETURN QUERY SELECT 3 /* ControlAction.Rejected */::SMALLINT, v_from_status;
        RETURN;
    END IF;

    -- Canonical deletion lock order: job (above), schedules, alerts, events, tags, then targets.
    PERFORM 1 FROM acta.schedules s WHERE s.job_id = p_id ORDER BY s.id FOR UPDATE;
    PERFORM 1 FROM acta.alerts a WHERE a.job_id = p_id ORDER BY a.id FOR UPDATE;
    PERFORM 1 FROM acta.events e WHERE e.job_id = p_id ORDER BY e.id FOR UPDATE;

    DELETE FROM acta.tags t
    WHERE
        (t.scope_code = 50 /* TagScopeCode.Job */ AND t.scope_id = p_id)
        OR (t.scope_code = 60 /* TagScopeCode.Schedule */ AND t.scope_id IN (
            SELECT s.id FROM acta.schedules s WHERE s.job_id = p_id))
        OR (t.scope_code = 80 /* TagScopeCode.Alert */ AND t.scope_id IN (
            SELECT a.id FROM acta.alerts a WHERE a.job_id = p_id))
        OR (t.scope_code = 90 /* TagScopeCode.Event */ AND t.scope_id IN (
            SELECT e.id FROM acta.events e WHERE e.job_id = p_id));

    DELETE FROM acta.events WHERE job_id = p_id;
    DELETE FROM acta.alerts WHERE job_id = p_id;
    DELETE FROM acta.jobs WHERE id = p_id;

    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        tenant_id,
        worker_id,
        from_status_code,
        to_status_code,
        execution_status_code,
        duration_ms,
        reason_code,
        reason_message)
    VALUES (
        75 /* EventCode.JobPurged */,
        now(),
        v_namespace_id,
        p_actor_code,
        p_actor_key,
        NULL,
        NULL,
        NULL,
        NULL,
        v_definition,
        v_tenant,
        NULL,
        v_from_status,
        NULL,
        NULL,
        NULL,
        p_reason_code,
        'purged ' || v_job_ref::text || ' (' || v_job_name || ')');

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, NULL::SMALLINT;
END;
$$;

CREATE OR REPLACE FUNCTION acta.reprioritize_job(
    p_id BIGINT,
    p_priority_code SMALLINT,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_code SMALLINT,
    p_reason_message VARCHAR
)
RETURNS TABLE (action SMALLINT, status_code SMALLINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_from_status SMALLINT;
    v_namespace_id SMALLINT;
    v_lineage BIGINT;
    v_definition INT;
    v_tenant INT;
    v_en INT;
    v_audit SMALLINT;
    v_job_ref UUID;
BEGIN
    SELECT r.status_code, j.namespace_id, j.lineage_root_id, j.definition_id, j.tenant_id, r.execution_number, j.audit_level_code, j.job_ref
    INTO v_from_status, v_namespace_id, v_lineage, v_definition, v_tenant, v_en, v_audit, v_job_ref
    FROM acta.jobs j
    JOIN acta.runtimes r ON r.job_id = j.id
    WHERE j.id = p_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::SMALLINT;
        RETURN;
    END IF;

    IF v_from_status IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */) THEN
        RETURN QUERY SELECT 3 /* ControlAction.Rejected */::SMALLINT, v_from_status;
        RETURN;
    END IF;

    UPDATE acta.runtimes
    SET
        priority_code = p_priority_code,
        modified_at_utc = now(),
        version = version + 1
    WHERE job_id = p_id;

    IF v_audit = 20 /* JobAuditLevelCode.Audit */ THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            74 /* EventCode.JobReprioritized */,
            now(),
            v_namespace_id,
            p_actor_code,
            p_actor_key,
            p_id,
            v_job_ref,
            v_en,
            COALESCE(v_lineage, p_id),
            v_definition,
            v_tenant,
            NULL,
            NULL,
            NULL,
            NULL,
            NULL,
            p_reason_code,
            p_reason_message);
    END IF;

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, v_from_status;
END;
$$;

CREATE OR REPLACE FUNCTION acta.reschedule_job(
    p_id BIGINT,
    p_next_run_at_utc TIMESTAMPTZ,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_code SMALLINT,
    p_reason_message VARCHAR
)
RETURNS TABLE (action SMALLINT, status_code SMALLINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_from_status SMALLINT;
    v_namespace_id SMALLINT;
    v_lineage BIGINT;
    v_definition INT;
    v_tenant INT;
    v_en INT;
    v_audit SMALLINT;
    v_job_ref UUID;
BEGIN
    SELECT r.status_code, j.namespace_id, j.lineage_root_id, j.definition_id, j.tenant_id, r.execution_number, j.audit_level_code, j.job_ref
    INTO v_from_status, v_namespace_id, v_lineage, v_definition, v_tenant, v_en, v_audit, v_job_ref
    FROM acta.jobs j
    JOIN acta.runtimes r ON r.job_id = j.id
    WHERE j.id = p_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::SMALLINT;
        RETURN;
    END IF;

    IF v_from_status NOT IN (30 /* JobStatusCode.Paused */, 20 /* JobStatusCode.Suspended */, 10 /* JobStatusCode.Ready */) THEN
        RETURN QUERY SELECT 3 /* ControlAction.Rejected */::SMALLINT, v_from_status;
        RETURN;
    END IF;

    UPDATE acta.runtimes
    SET
        next_run_at_utc = p_next_run_at_utc,
        status_code = 10 /* JobStatusCode.Ready */,
        modified_at_utc = now(),
        version = version + 1
    WHERE job_id = p_id;

    IF v_audit = 20 /* JobAuditLevelCode.Audit */ THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            61 /* EventCode.JobRescheduled */,
            now(),
            v_namespace_id,
            p_actor_code,
            p_actor_key,
            p_id,
            v_job_ref,
            v_en,
            COALESCE(v_lineage, p_id),
            v_definition,
            v_tenant,
            NULL,
            v_from_status,
            10 /* JobStatusCode.Ready */,
            NULL,
            NULL,
            p_reason_code,
            p_reason_message);
    END IF;

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, 10 /* JobStatusCode.Ready */::SMALLINT;
END;
$$;

CREATE OR REPLACE FUNCTION acta.reset_job_state(
    p_id BIGINT
)
RETURNS INT
LANGUAGE plpgsql
AS $$
DECLARE
    v_status SMALLINT;
    v_namespace_id SMALLINT;
    v_lineage_root_id BIGINT;
    v_definition_id INT;
    v_tenant_id INT;
    v_execution_number INT;
    v_audit_level SMALLINT;
    v_job_ref UUID;
BEGIN
    SELECT r.status_code, j.namespace_id, j.lineage_root_id, j.definition_id, j.tenant_id, r.execution_number, j.audit_level_code, j.job_ref
    INTO v_status, v_namespace_id, v_lineage_root_id, v_definition_id, v_tenant_id, v_execution_number, v_audit_level, v_job_ref
    FROM acta.runtimes r
    JOIN acta.jobs j ON j.id = r.job_id
    WHERE r.job_id = p_id
    FOR UPDATE OF r;

    IF NOT FOUND THEN
        RETURN 1;
    END IF;

    DELETE FROM acta.checkpoints WHERE job_id = p_id;
    DELETE FROM acta.steps WHERE job_id = p_id;
    DELETE FROM acta.results WHERE job_id = p_id;

    IF v_audit_level = 20 /* JobAuditLevelCode.Audit */ THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            81 /* EventCode.JobStateReset */,
            now(),
            v_namespace_id,
            50 /* ActorCode.Job */,
            p_id::varchar,
            p_id,
            v_job_ref,
            v_execution_number,
            COALESCE(v_lineage_root_id, p_id),
            v_definition_id,
            v_tenant_id,
            NULL,
            v_status,
            v_status,
            NULL,
            NULL,
            NULL,
            NULL);
    END IF;

    RETURN 1;
END;
$$;

CREATE OR REPLACE FUNCTION acta.restart_job(
    p_id BIGINT,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_code SMALLINT,
    p_reason_message VARCHAR,
    p_next_run_at_utc TIMESTAMPTZ DEFAULT NULL
)
RETURNS TABLE (action SMALLINT, status_code SMALLINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_from_status SMALLINT;
    v_namespace_id SMALLINT;
    v_lineage_root_id BIGINT;
    v_definition_id INT;
    v_tenant_id INT;
    v_execution_number INT;
    v_audit_level SMALLINT;
    v_job_ref UUID;
BEGIN
    SELECT r.status_code, j.namespace_id, j.lineage_root_id, j.definition_id, j.tenant_id, r.execution_number, j.audit_level_code, j.job_ref
    INTO v_from_status, v_namespace_id, v_lineage_root_id, v_definition_id, v_tenant_id, v_execution_number, v_audit_level, v_job_ref
    FROM acta.runtimes r
    JOIN acta.jobs j ON j.id = r.job_id
    WHERE r.job_id = p_id
    FOR UPDATE OF r;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::SMALLINT;
        RETURN;
    END IF;

    IF v_from_status = 50 /* JobStatusCode.Executing */ THEN
        RETURN QUERY SELECT 3 /* ControlAction.Rejected */::SMALLINT, v_from_status;
        RETURN;
    END IF;

    UPDATE acta.runtimes
    SET
        status_code = 10 /* JobStatusCode.Ready */,
        failure_count = 0,
        next_run_at_utc = COALESCE(p_next_run_at_utc, now()),
        leased_by_worker_id = NULL,
        lease_expires_at_utc = NULL,
        retention_until_utc = NULL,
        modified_at_utc = now(),
        version = version + 1
    WHERE job_id = p_id;

    IF v_audit_level = 20 /* JobAuditLevelCode.Audit */ THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            73 /* EventCode.JobRestarted */,
            now(),
            v_namespace_id,
            p_actor_code,
            p_actor_key,
            p_id,
            v_job_ref,
            v_execution_number,
            COALESCE(v_lineage_root_id, p_id),
            v_definition_id,
            v_tenant_id,
            NULL,
            v_from_status,
            10 /* JobStatusCode.Ready */,
            NULL,
            NULL,
            p_reason_code,
            p_reason_message);
    END IF;

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, 10 /* JobStatusCode.Ready */::SMALLINT;
END;
$$;

CREATE OR REPLACE FUNCTION acta.resume_job(
    p_id BIGINT,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_code SMALLINT,
    p_reason_message VARCHAR,
    p_next_run_at_utc TIMESTAMPTZ DEFAULT NULL
)
RETURNS TABLE (action SMALLINT, status_code SMALLINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_from_status SMALLINT;
    v_namespace_id SMALLINT;
    v_lineage_root_id BIGINT;
    v_definition_id INT;
    v_tenant_id INT;
    v_execution_number INT;
    v_audit_level SMALLINT;
    v_job_ref UUID;
BEGIN
    SELECT r.status_code, j.namespace_id, j.lineage_root_id, j.definition_id, j.tenant_id, r.execution_number, j.audit_level_code, j.job_ref
    INTO v_from_status, v_namespace_id, v_lineage_root_id, v_definition_id, v_tenant_id, v_execution_number, v_audit_level, v_job_ref
    FROM acta.runtimes r
    JOIN acta.jobs j ON j.id = r.job_id
    WHERE r.job_id = p_id
    FOR UPDATE OF r;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::SMALLINT;
        RETURN;
    END IF;

    IF v_from_status <> 30 /* JobStatusCode.Paused */ THEN
        RETURN QUERY SELECT 3 /* ControlAction.Rejected */::SMALLINT, v_from_status;
        RETURN;
    END IF;

    UPDATE acta.runtimes
    SET
        status_code = 10 /* JobStatusCode.Ready */,
        next_run_at_utc = COALESCE(p_next_run_at_utc, now()),
        modified_at_utc = now(),
        version = version + 1
    WHERE job_id = p_id;

    IF v_audit_level = 20 /* JobAuditLevelCode.Audit */ THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            72 /* EventCode.JobResumed */,
            now(),
            v_namespace_id,
            p_actor_code,
            p_actor_key,
            p_id,
            v_job_ref,
            v_execution_number,
            COALESCE(v_lineage_root_id, p_id),
            v_definition_id,
            v_tenant_id,
            NULL,
            30 /* JobStatusCode.Paused */,
            10 /* JobStatusCode.Ready */,
            NULL,
            NULL,
            p_reason_code,
            p_reason_message);
    END IF;

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, 10 /* JobStatusCode.Ready */::SMALLINT;
