BEGIN
    SELECT n.id, n.status_code, n.version INTO v_id, v_status, v_version
    FROM acta.namespaces n
    WHERE n.name = p_namespace_name
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* AdminControlAction.NotFound */::SMALLINT, NULL::INT;
        RETURN;
    END IF;

    IF v_status = 20 /* NamespaceStatusCode.Suspended */ THEN
        RETURN QUERY SELECT 3 /* AdminControlAction.AlreadyInState */::SMALLINT, v_version;
        RETURN;
    END IF;

    UPDATE acta.namespaces AS n
    SET
        status_code = 20 /* NamespaceStatusCode.Suspended */,
        modified_at_utc = now(),
        version = n.version + 1
    WHERE n.id = v_id
    RETURNING n.version INTO v_version;

    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        tenant_id,
        worker_id,
        from_status_code,
        to_status_code,
        execution_status_code,
        duration_ms,
        reason_code,
        reason_message)
    VALUES (
        20 /* EventCode.NamespaceSuspended */,
        now(),
        v_id,
        p_actor_code,
        p_actor_key,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        p_reason_message);

    RETURN QUERY SELECT 1 /* AdminControlAction.Applied */::SMALLINT, v_version;
END;
$$;

CREATE OR REPLACE FUNCTION acta.update_namespace(
    p_namespace_name VARCHAR,
    p_owner_team VARCHAR,
    p_description VARCHAR,
    p_expected_version INT,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_message VARCHAR
)
RETURNS TABLE (action SMALLINT, version INT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_id SMALLINT;
    v_version INT;
BEGIN
    SELECT n.id, n.version INTO v_id, v_version
    FROM acta.namespaces n
    WHERE n.name = p_namespace_name
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* AdminControlAction.NotFound */::SMALLINT, NULL::INT;
        RETURN;
    END IF;

    IF v_version <> p_expected_version THEN
        RETURN QUERY SELECT 4 /* AdminControlAction.VersionConflict */::SMALLINT, v_version;
        RETURN;
    END IF;

    UPDATE acta.namespaces AS n
    SET
        owner_team = p_owner_team,
        description = p_description,
        modified_at_utc = now(),
        version = n.version + 1
    WHERE n.id = v_id
    RETURNING n.version INTO v_version;

    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        tenant_id,
        worker_id,
        from_status_code,
        to_status_code,
        execution_status_code,
        duration_ms,
        reason_code,
        reason_message)
    VALUES (
        22 /* EventCode.NamespaceUpdated */,
        now(),
        v_id,
        p_actor_code,
        p_actor_key,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        p_reason_message);

    RETURN QUERY SELECT 1 /* AdminControlAction.Applied */::SMALLINT, v_version;
END;
$$;

-- Appends one application-authored job.note-recorded event; see IExecutionStore.RecordJobNoteAsync.
-- Denormalized columns are read from the job, so a note cannot disagree with the row it is about.
CREATE OR REPLACE FUNCTION acta.record_job_note(
    p_job_id BIGINT,
    p_reason_message VARCHAR,
    p_detail_format_id SMALLINT,
    p_detail BYTEA
)
RETURNS VOID
LANGUAGE plpgsql
AS $$
DECLARE
    v_rows INT;
BEGIN
    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        tenant_id,
        detail_format_id,
        detail,
        reason_message)
    SELECT
        90 /* EventCode.JobNoteRecorded */,
        now(),
        j.namespace_id,
        50 /* ActorCode.Job */,
        j.id,
        j.job_ref,
        r.execution_number,
        COALESCE(j.lineage_root_id, j.id),
        j.definition_id,
        j.tenant_id,
        p_detail_format_id,
        p_detail,
        p_reason_message
    FROM acta.jobs j
    JOIN acta.runtimes r ON r.job_id = j.id
    WHERE j.id = p_job_id;

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        RAISE EXCEPTION 'ACTA:NOTE_UNKNOWN_JOB:record_job_note: unknown job id'
            USING ERRCODE = 'P0001';
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION acta.reclaim_stuck_jobs(
    p_namespace_id SMALLINT
)
RETURNS TABLE (job_id BIGINT, to_status SMALLINT, parent_id BIGINT)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    WITH stuck AS (
        SELECT
            r.job_id AS id,
            r.status_code AS from_status,
            r.execution_number,
            j.lineage_root_id,
            j.definition_id,
            j.tenant_id,
            j.audit_level_code,
            (r.failure_count + 1) AS new_failure_count,
            jd.max_attempts_effective AS max_attempts,
            jd.retention_seconds_effective AS retention_seconds
        FROM acta.runtimes r
        INNER JOIN acta.jobs j ON j.id = r.job_id
        INNER JOIN acta.definitions jd ON jd.id = j.definition_id
        WHERE
            r.status_code IN (40 /* JobStatusCode.Dispatched */, 50 /* JobStatusCode.Executing */)
            AND r.lease_expires_at_utc < now()
            AND r.namespace_id = p_namespace_id
        FOR UPDATE OF r SKIP LOCKED
    ),
    reclaimed AS (
        UPDATE acta.runtimes r
        SET
            status_code = CASE WHEN s.new_failure_count >= s.max_attempts
                THEN 200 /* JobStatusCode.Failed */
                ELSE 10 /* JobStatusCode.Ready */ END,
            failure_count = s.new_failure_count,
            next_run_at_utc = CASE WHEN s.new_failure_count >= s.max_attempts
                THEN r.next_run_at_utc
                ELSE now() END,
            leased_by_worker_id = NULL,
            lease_expires_at_utc = NULL,
            retention_until_utc = CASE WHEN s.new_failure_count >= s.max_attempts
                THEN now() + make_interval(secs => s.retention_seconds)
                ELSE r.retention_until_utc END,
            modified_at_utc = now(),
            version = r.version + 1
        FROM stuck s
        JOIN acta.jobs j ON j.id = s.id
        WHERE r.job_id = s.id
        RETURNING
            r.job_id AS id, j.namespace_id, r.execution_number, j.lineage_root_id,
            j.definition_id, j.tenant_id, s.from_status, r.status_code AS new_status, s.audit_level_code,
            j.parent_id AS job_parent_id, j.job_ref
    ),
    event_insert AS (
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        SELECT
            41 /* EventCode.JobExecutionFinished */,
            now(),
            r.namespace_id,
            10 /* ActorCode.Sys */,
            NULL,
            r.id,
            r.job_ref,
            r.execution_number,
            COALESCE(r.lineage_root_id, r.id),
            r.definition_id,
            r.tenant_id,
            NULL,
            r.from_status,
            r.new_status,
            230 /* ExecutionStatusCode.Orphaned */,
            NULL,
            21 /* JobEventReasonCode.JobLeaseExpired */,
            'Worker lease expired; reclaimed by the sys.recovery system job.'
        FROM reclaimed r
        WHERE r.audit_level_code IN (10 /* JobAuditLevelCode.Failures */, 20 /* JobAuditLevelCode.Audit */)
    )
    SELECT r.id, r.new_status, r.job_parent_id
    FROM reclaimed r;
END;
$$;

CREATE OR REPLACE FUNCTION acta.pause_schedule(
    p_job_id BIGINT,
    p_name VARCHAR,
    p_paused_until_utc TIMESTAMPTZ,
    p_job_next_run_at_utc TIMESTAMPTZ,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_message VARCHAR
)
RETURNS TABLE (
    out_action SMALLINT, out_status_code SMALLINT, out_paused_until_utc TIMESTAMPTZ, out_next_run_at_utc TIMESTAMPTZ, out_version INT
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_schedule_id BIGINT;
    v_status SMALLINT;
    v_paused TIMESTAMPTZ;
    v_next TIMESTAMPTZ;
    v_version INT;
    v_ns SMALLINT;
    v_def INT;
    v_lineage BIGINT;
    v_en INT;
    v_audit SMALLINT;
    v_job_ref UUID;
BEGIN
    /* Lock the slot's runtimes row before the schedules row: register_scheduled_jobs writes
       runtimes then schedules, so every writer of both must take runtimes first. */
    SELECT r.execution_number
    INTO v_en
    FROM acta.runtimes r
    WHERE r.job_id = p_job_id
    FOR UPDATE;

    SELECT js.id
    INTO v_schedule_id
    FROM acta.schedules js
    WHERE
        js.job_id = p_job_id
        AND js.name = p_name
        AND js.status_code <> 230 /* ScheduleStatusCode.Orphaned */
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::SMALLINT, NULL::TIMESTAMPTZ, NULL::TIMESTAMPTZ, NULL::INT;
        RETURN;
    END IF;

    SELECT j.namespace_id, j.definition_id, j.lineage_root_id, j.audit_level_code, j.job_ref
    INTO v_ns, v_def, v_lineage, v_audit, v_job_ref
    FROM acta.jobs j
    WHERE j.id = p_job_id;

    UPDATE acta.schedules
    SET
        status_code = 30 /* ScheduleStatusCode.Paused */,
        paused_until_utc = p_paused_until_utc,
        reason_message = p_reason_message,
        modified_at_utc = now(),
        version = version + 1
    WHERE id = v_schedule_id
    RETURNING status_code, paused_until_utc, next_run_at_utc, version
    INTO v_status, v_paused, v_next, v_version;

    UPDATE acta.runtimes
    SET
        next_run_at_utc = p_job_next_run_at_utc,
        status_code = CASE WHEN p_job_next_run_at_utc IS NULL
            THEN 30 /* JobStatusCode.Paused */
            ELSE 10 /* JobStatusCode.Ready */ END,
        modified_at_utc = now(),
        version = version + 1
    WHERE
        job_id = p_job_id
        AND status_code IN (30 /* JobStatusCode.Paused */, 10 /* JobStatusCode.Ready */);

    IF v_audit = 20 /* JobAuditLevelCode.Audit */ THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            100 /* EventCode.SchedulePaused */,
            now(),
            v_ns,
            p_actor_code,
            p_actor_key,
            p_job_id,
            v_job_ref,
            v_en,
            COALESCE(v_lineage, p_job_id),
            v_def,
            NULL,
            NULL,
            NULL,
            NULL,
            NULL,
            NULL,
            p_name);
    END IF;

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, v_status, v_paused, v_next, v_version;
END;
$$;

CREATE OR REPLACE FUNCTION acta.register_scheduled_jobs(
    p_namespace_id SMALLINT,
    p_d_job_ref UUID [],
    p_d_definition_id INT [],
    p_d_deduplication_key VARCHAR [],
    p_d_input_format_id SMALLINT [],
    p_d_input BYTEA [],
    p_d_audit_level SMALLINT [],
    p_d_slot_status SMALLINT [],
    p_d_slot_next_run_at_utc TIMESTAMPTZ [],
    p_s_definition_id INT [],
    p_s_name VARCHAR [],
    p_s_expression VARCHAR [],
    p_s_time_zone VARCHAR [],
    p_s_expression_kind SMALLINT [],
    p_s_misfire SMALLINT [],
    p_s_next_run_at_utc TIMESTAMPTZ [],
    p_s_description VARCHAR []
)
RETURNS TABLE (out_definition_id INT, out_slot_id BIGINT)
LANGUAGE plpgsql
AS $$
BEGIN
    CREATE TEMP TABLE _reg_slots (definition_id INT PRIMARY KEY, slot_id BIGINT NOT NULL) ON COMMIT DROP;

    WITH defs AS (
        SELECT *
        FROM unnest(
            p_d_job_ref, p_d_definition_id, p_d_deduplication_key, p_d_input_format_id, p_d_input,
            p_d_audit_level, p_d_slot_status, p_d_slot_next_run_at_utc)
        AS d(job_ref, definition_id, deduplication_key, input_format_id, input, audit_level, slot_status, slot_next_run)
    ),
    upserted AS (
        INSERT INTO acta.jobs (
            job_ref,
            lineage_root_id,
            parent_id,
            deduplication_key,
            correlation_key,
            namespace_id,
            definition_id,
            input_format_id,
            input,
            exclusive_key,
            audit_level_code,
            created_at_utc)
        SELECT
            d.job_ref,
            NULL,
            NULL,
            d.deduplication_key,
            NULL,
            p_namespace_id,
            d.definition_id,
            d.input_format_id,
            d.input,
            NULL,
            d.audit_level,
            now()
        FROM defs AS d
        ORDER BY d.deduplication_key
        ON CONFLICT (namespace_id, deduplication_key) WHERE deduplication_key IS NOT NULL AND parent_id IS NULL
        DO UPDATE SET
            input_format_id = EXCLUDED.input_format_id,
            input = EXCLUDED.input,
            audit_level_code = EXCLUDED.audit_level_code
        RETURNING acta.jobs.definition_id, acta.jobs.id
    )
    INSERT INTO _reg_slots (definition_id, slot_id)
    SELECT definition_id, id FROM upserted;

    INSERT INTO acta.runtimes (
        job_id,
        namespace_id,
        status_code,
        priority_code,
        next_run_at_utc,
        execution_number,
        failure_count,
        retention_until_utc,
        modified_at_utc,
        version)
    SELECT
        sl.slot_id,
        p_namespace_id,
        d.slot_status,
        jd.priority_code_effective,
        d.slot_next_run,
        0,
        0,
        NULL,
        now(),
        0
    FROM unnest(
        p_d_definition_id, p_d_slot_status, p_d_slot_next_run_at_utc)
    AS d(definition_id, slot_status, slot_next_run)
    INNER JOIN _reg_slots AS sl ON sl.definition_id = d.definition_id
    INNER JOIN acta.definitions AS jd ON jd.id = d.definition_id
    -- Re-registration re-asserts the definition's declared priority onto the slot, overwriting any operator reprioritize.
    ON CONFLICT (job_id) DO UPDATE SET
        status_code = EXCLUDED.status_code,
        priority_code = EXCLUDED.priority_code,
        next_run_at_utc = EXCLUDED.next_run_at_utc,
        modified_at_utc = now(),
        version = acta.runtimes.version + 1;

    INSERT INTO acta.schedules (
        namespace_id,
        job_id,
        definition_id,
        name,
        origin_code,
        expression,
        time_zone_id,
        expression_kind_code,
        misfire_strategy_code,
        next_run_at_utc,
        expression_override,
        time_zone_id_override,
        status_code,
        paused_until_utc,
        description,
        created_at_utc,
        modified_at_utc,
        version)
    SELECT
        p_namespace_id,
        sl.slot_id,
        s.definition_id,
        s.name,
        40 /* ScheduleOriginCode.Definition */,
        s.expression,
        s.time_zone,
        s.expression_kind,
        s.misfire,
        s.next_run,
        NULL,
        NULL,
        10 /* ScheduleStatusCode.Active */,
        NULL,
        s.description,
        now(),
        now(),
        0
    FROM unnest(
        p_s_definition_id, p_s_name, p_s_expression, p_s_time_zone,
        p_s_expression_kind, p_s_misfire, p_s_next_run_at_utc, p_s_description)
    AS s(definition_id, name, expression, time_zone, expression_kind, misfire, next_run, description)
    INNER JOIN _reg_slots AS sl ON sl.definition_id = s.definition_id
    ON CONFLICT (job_id, name) DO UPDATE SET
        expression = EXCLUDED.expression,
        time_zone_id = EXCLUDED.time_zone_id,
        expression_kind_code = EXCLUDED.expression_kind_code,
        misfire_strategy_code = EXCLUDED.misfire_strategy_code,
        next_run_at_utc = EXCLUDED.next_run_at_utc,
        definition_id = EXCLUDED.definition_id,
        status_code = CASE WHEN acta.schedules.status_code = 230 /* ScheduleStatusCode.Orphaned */
            THEN 10 /* ScheduleStatusCode.Active */ ELSE acta.schedules.status_code END,
        description = EXCLUDED.description,
        modified_at_utc = now(),
        version = acta.schedules.version + 1;

    UPDATE acta.schedules AS js
    SET
        status_code = 230 /* ScheduleStatusCode.Orphaned */,
        paused_until_utc = NULL,
        modified_at_utc = now(),
        version = js.version + 1
    FROM _reg_slots AS sl
    WHERE
        js.job_id = sl.slot_id
        AND js.status_code <> 230 /* ScheduleStatusCode.Orphaned */
        AND js.origin_code = 40 /* ScheduleOriginCode.Definition */
        AND NOT EXISTS (
            SELECT 1
            FROM unnest(p_s_definition_id, p_s_name) AS s(definition_id, name)
            WHERE
                s.definition_id = sl.definition_id
                AND s.name = js.name
        );

    RETURN QUERY SELECT r.definition_id, r.slot_id FROM _reg_slots AS r;
END;
$$;

CREATE OR REPLACE FUNCTION acta.resume_schedule(
    p_job_id BIGINT,
    p_name VARCHAR,
    p_next_run_at_utc TIMESTAMPTZ,
    p_job_next_run_at_utc TIMESTAMPTZ,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_message VARCHAR
)
RETURNS TABLE (
    out_action SMALLINT, out_status_code SMALLINT, out_paused_until_utc TIMESTAMPTZ, out_next_run_at_utc TIMESTAMPTZ, out_version INT
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_schedule_id BIGINT;
    v_status SMALLINT;
    v_paused TIMESTAMPTZ;
    v_next TIMESTAMPTZ;
    v_version INT;
    v_ns SMALLINT;
    v_def INT;
    v_lineage BIGINT;
    v_en INT;
    v_audit SMALLINT;
    v_job_ref UUID;
BEGIN
    /* Lock the slot's runtimes row before the schedules row: register_scheduled_jobs writes
       runtimes then schedules, so every writer of both must take runtimes first. */
    SELECT r.execution_number
    INTO v_en
    FROM acta.runtimes r
    WHERE r.job_id = p_job_id
    FOR UPDATE;

    SELECT js.id
    INTO v_schedule_id
    FROM acta.schedules js
    WHERE
        js.job_id = p_job_id
        AND js.name = p_name
        AND js.status_code <> 230 /* ScheduleStatusCode.Orphaned */
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::SMALLINT, NULL::TIMESTAMPTZ, NULL::TIMESTAMPTZ, NULL::INT;
        RETURN;
    END IF;

    SELECT j.namespace_id, j.definition_id, j.lineage_root_id, j.audit_level_code, j.job_ref
    INTO v_ns, v_def, v_lineage, v_audit, v_job_ref
    FROM acta.jobs j
    WHERE j.id = p_job_id;

    UPDATE acta.schedules
    SET
        status_code = 10 /* ScheduleStatusCode.Active */,
        paused_until_utc = NULL,
        next_run_at_utc = p_next_run_at_utc,
        reason_message = p_reason_message,
        modified_at_utc = now(),
        version = version + 1
    WHERE id = v_schedule_id
    RETURNING status_code, paused_until_utc, next_run_at_utc, version
    INTO v_status, v_paused, v_next, v_version;

    UPDATE acta.runtimes
    SET
        next_run_at_utc = p_job_next_run_at_utc,
        status_code = CASE WHEN p_job_next_run_at_utc IS NULL
            THEN 30 /* JobStatusCode.Paused */
            ELSE 10 /* JobStatusCode.Ready */ END,
        modified_at_utc = now(),
        version = version + 1
    WHERE
        job_id = p_job_id
        AND status_code IN (30 /* JobStatusCode.Paused */, 10 /* JobStatusCode.Ready */);

    IF v_audit = 20 /* JobAuditLevelCode.Audit */ THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            101 /* EventCode.ScheduleResumed */,
            now(),
            v_ns,
            p_actor_code,
            p_actor_key,
            p_job_id,
            v_job_ref,
            v_en,
            COALESCE(v_lineage, p_job_id),
            v_def,
            NULL,
            NULL,
            NULL,
            NULL,
            NULL,
            NULL,
            p_name);
    END IF;

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, v_status, v_paused, v_next, v_version;
END;
$$;

CREATE OR REPLACE FUNCTION acta.set_schedule_overrides(
    p_job_id BIGINT,
    p_name VARCHAR,
    p_expected_version INT,
    p_expression VARCHAR,
    p_time_zone_id VARCHAR,
    p_reason_message VARCHAR,
    p_job_next_run_at_utc TIMESTAMPTZ,
    p_schedule_next_run_at_utc TIMESTAMPTZ,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_change_summary VARCHAR
)
RETURNS TABLE (
    out_action SMALLINT, out_status_code SMALLINT, out_paused_until_utc TIMESTAMPTZ, out_next_run_at_utc TIMESTAMPTZ, out_version INT
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_schedule_id BIGINT;
    v_status SMALLINT;
    v_paused TIMESTAMPTZ;
    v_next TIMESTAMPTZ;
    v_version INT;
    v_ns SMALLINT;
    v_def INT;
    v_lineage BIGINT;
    v_en INT;
    v_audit SMALLINT;
    v_job_ref UUID;
BEGIN
    /* Lock the slot's runtimes row before the schedules row: register_scheduled_jobs writes
       runtimes then schedules, so every writer of both must take runtimes first. */
    SELECT r.execution_number
    INTO v_en
    FROM acta.runtimes r
    WHERE r.job_id = p_job_id
    FOR UPDATE;

    SELECT js.id, js.status_code, js.paused_until_utc, js.next_run_at_utc, js.version
    INTO v_schedule_id, v_status, v_paused, v_next, v_version
    FROM acta.schedules js
    WHERE
        js.job_id = p_job_id
        AND js.name = p_name
        AND js.status_code <> 230 /* ScheduleStatusCode.Orphaned */
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::SMALLINT, NULL::TIMESTAMPTZ, NULL::TIMESTAMPTZ, NULL::INT;
        RETURN;
    END IF;

    IF v_version <> p_expected_version THEN
        RETURN QUERY SELECT 3 /* ControlAction.Rejected */::SMALLINT, v_status, v_paused, v_next, v_version;
        RETURN;
    END IF;

    SELECT j.namespace_id, j.definition_id, j.lineage_root_id, j.audit_level_code, j.job_ref
    INTO v_ns, v_def, v_lineage, v_audit, v_job_ref
    FROM acta.jobs j
    WHERE j.id = p_job_id;

    UPDATE acta.schedules
    SET
        expression_override = p_expression,
        time_zone_id_override = p_time_zone_id,
        next_run_at_utc = p_schedule_next_run_at_utc,
        reason_message = p_reason_message,
        modified_at_utc = now(),
        version = version + 1
    WHERE id = v_schedule_id
    RETURNING status_code, paused_until_utc, next_run_at_utc, version
    INTO v_status, v_paused, v_next, v_version;

    UPDATE acta.runtimes
    SET
        next_run_at_utc = p_job_next_run_at_utc,
        status_code = CASE WHEN p_job_next_run_at_utc IS NULL
            THEN 30 /* JobStatusCode.Paused */ ELSE 10 /* JobStatusCode.Ready */ END,
        modified_at_utc = now(),
        version = version + 1
    WHERE
        job_id = p_job_id
        AND status_code IN (30 /* JobStatusCode.Paused */, 10 /* JobStatusCode.Ready */);

    IF v_audit = 20 /* JobAuditLevelCode.Audit */ THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            103 /* EventCode.ScheduleOverridesUpdated */,
            now(),
            v_ns,
            p_actor_code,
            p_actor_key,
            p_job_id,
            v_job_ref,
            v_en,
            COALESCE(v_lineage, p_job_id),
            v_def,
            NULL,
            NULL,
            NULL,
            NULL,
            NULL,
            NULL,
            p_change_summary);
    END IF;

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, v_status, v_paused, v_next, v_version;
END;
$$;

CREATE OR REPLACE FUNCTION acta.trigger_schedule_now(
    p_job_id BIGINT,
    p_name VARCHAR,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_message VARCHAR
)
RETURNS TABLE (
    out_action SMALLINT, out_status_code SMALLINT, out_paused_until_utc TIMESTAMPTZ, out_next_run_at_utc TIMESTAMPTZ, out_version INT
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_schedule_id BIGINT;
    v_status SMALLINT;
    v_paused TIMESTAMPTZ;
    v_next TIMESTAMPTZ;
    v_version INT;
    v_slot_status SMALLINT;
    v_ns SMALLINT;
    v_def INT;
    v_lineage BIGINT;
    v_en INT;
    v_audit SMALLINT;
    v_job_ref UUID;
BEGIN
    /* Lock the slot's runtimes row before the schedules row: register_scheduled_jobs writes
       runtimes then schedules, so every writer of both must take runtimes first. The schedules row
       is guard-only here (never updated): a manual trigger moves only the slot's cursor. */
    SELECT r.status_code, r.execution_number
    INTO v_slot_status, v_en
    FROM acta.runtimes r
    WHERE r.job_id = p_job_id
    FOR UPDATE;

    SELECT js.id, js.status_code, js.paused_until_utc, js.next_run_at_utc, js.version
    INTO v_schedule_id, v_status, v_paused, v_next, v_version
    FROM acta.schedules js
    WHERE
        js.job_id = p_job_id
        AND js.name = p_name
        AND js.status_code <> 230 /* ScheduleStatusCode.Orphaned */
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::SMALLINT, NULL::TIMESTAMPTZ, NULL::TIMESTAMPTZ, NULL::INT;
        RETURN;
    END IF;

    IF v_status = 30 /* ScheduleStatusCode.Paused */ THEN
        RETURN QUERY SELECT 3 /* ControlAction.Rejected */::SMALLINT, v_status, v_paused, v_next, v_version;
        RETURN;
    END IF;

    IF v_slot_status IN (40 /* JobStatusCode.Dispatched */, 50 /* JobStatusCode.Executing */) THEN
        RETURN QUERY SELECT 3 /* ControlAction.Rejected */::SMALLINT, v_status, v_paused, v_next, v_version;
        RETURN;
    END IF;

    IF v_slot_status IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */) THEN
        RETURN QUERY SELECT 3 /* ControlAction.Rejected */::SMALLINT, v_status, v_paused, v_next, v_version;
        RETURN;
    END IF;

    SELECT j.namespace_id, j.definition_id, j.lineage_root_id, j.audit_level_code, j.job_ref
    INTO v_ns, v_def, v_lineage, v_audit, v_job_ref
    FROM acta.jobs j
    WHERE j.id = p_job_id;

    UPDATE acta.runtimes
    SET
        next_run_at_utc = now(),
        status_code = 10 /* JobStatusCode.Ready */,
        modified_at_utc = now(),
        version = version + 1
    WHERE
        job_id = p_job_id
        AND status_code IN (30 /* JobStatusCode.Paused */, 20 /* JobStatusCode.Suspended */, 10 /* JobStatusCode.Ready */);

    IF v_audit = 20 /* JobAuditLevelCode.Audit */ THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            104 /* EventCode.ScheduleTriggered */,
            now(),
            v_ns,
            p_actor_code,
            p_actor_key,
            p_job_id,
            v_job_ref,
            v_en,
            COALESCE(v_lineage, p_job_id),
            v_def,
            NULL,
            NULL,
            NULL,
            NULL,
            NULL,
            NULL,
            p_reason_message);
    END IF;

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, v_status, v_paused, v_next, v_version;
END;
$$;

-- Scoped upsert, last write wins: targets resolve the scope (none = Global, namespace alone =
-- Namespace, namespace + job name = Definition); unregistered targets are NotFound. Parameter ORDER
-- is fixed (positional invocation); the name is validated upstream so the detail JSON stays literal.
CREATE OR REPLACE FUNCTION acta.set_setting(
    p_name VARCHAR,
    p_value_format_id SMALLINT,
    p_value BYTEA,
    p_description VARCHAR,
    p_namespace_name VARCHAR,
    p_job_name VARCHAR,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_message VARCHAR,
    p_expected_version INT
)
RETURNS TABLE (action SMALLINT, version INT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_scope_code SMALLINT := 10 /* SettingScopeCode.Global */;
    v_namespace_id SMALLINT;
    v_definition_id INT;
    v_scope_id INT;
    v_version INT;
BEGIN
    IF p_namespace_name IS NOT NULL THEN
        SELECT n.id INTO v_namespace_id FROM acta.namespaces n WHERE n.name = p_namespace_name;
        IF NOT FOUND THEN
            RETURN QUERY SELECT 2 /* AdminControlAction.NotFound */::SMALLINT, NULL::INT;
            RETURN;
        END IF;
        IF p_job_name IS NULL THEN
            v_scope_code := 30 /* SettingScopeCode.Namespace */;
            v_scope_id := v_namespace_id;
        ELSE
            SELECT d.id INTO v_definition_id
            FROM acta.definitions d
            WHERE
                d.namespace_id = v_namespace_id
                AND d.name = p_job_name;
            IF NOT FOUND THEN
                RETURN QUERY SELECT 2 /* AdminControlAction.NotFound */::SMALLINT, NULL::INT;
                RETURN;
            END IF;
            v_scope_code := 40 /* SettingScopeCode.Definition */;
            v_scope_id := v_definition_id;
        END IF;
    END IF;

    UPDATE acta.settings s
    SET
        value_format_id = p_value_format_id,
        value = p_value,
        description = p_description,
        modified_at_utc = now(),
        version = s.version + 1
    WHERE
        s.scope_code = v_scope_code
        AND s.scope_id IS NOT DISTINCT FROM v_scope_id
        AND s.name = p_name
        AND (p_expected_version IS NULL OR s.version = p_expected_version)
    RETURNING s.version INTO v_version;

    IF NOT FOUND THEN
        -- CAS misses never create and never write the event: report the row as it stands.
        IF p_expected_version IS NOT NULL THEN
            SELECT s.version INTO v_version
            FROM acta.settings s
            WHERE
                s.scope_code = v_scope_code
                AND s.scope_id IS NOT DISTINCT FROM v_scope_id
                AND s.name = p_name;
            IF FOUND THEN
                RETURN QUERY SELECT 4 /* AdminControlAction.VersionConflict */::SMALLINT, v_version;
            ELSE
                RETURN QUERY SELECT 2 /* AdminControlAction.NotFound */::SMALLINT, NULL::INT;
            END IF;
            RETURN;
        END IF;
        IF v_scope_id IS NULL THEN
            INSERT INTO acta.settings AS s (
                scope_code,
                scope_id,
                name,
                value_format_id,
                value,
                description,
                created_at_utc,
                modified_at_utc,
                version)
            VALUES (
                v_scope_code,
                NULL,
                p_name,
                p_value_format_id,
                p_value,
                p_description,
                now(),
                now(),
                0)
            ON CONFLICT (scope_code, name) WHERE scope_id IS NULL DO UPDATE SET
                value_format_id = EXCLUDED.value_format_id,
                value = EXCLUDED.value,
                description = EXCLUDED.description,
                modified_at_utc = now(),
                version = s.version + 1
            RETURNING s.version INTO v_version;
        ELSE
            INSERT INTO acta.settings AS s (
                scope_code,
                scope_id,
                name,
                value_format_id,
                value,
                description,
                created_at_utc,
                modified_at_utc,
                version)
            VALUES (
                v_scope_code,
                v_scope_id,
                p_name,
                p_value_format_id,
                p_value,
                p_description,
                now(),
                now(),
                0)
            ON CONFLICT (scope_code, scope_id, name) WHERE scope_id IS NOT NULL DO UPDATE SET
                value_format_id = EXCLUDED.value_format_id,
                value = EXCLUDED.value,
                description = EXCLUDED.description,
                modified_at_utc = now(),
                version = s.version + 1
            RETURNING s.version INTO v_version;
        END IF;
    END IF;

    -- namespace_id 1 is the seeded sys namespace (M001); detail identifies the setting by name.
    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        tenant_id,
        worker_id,
        from_status_code,
        to_status_code,
        execution_status_code,
        duration_ms,
        reason_code,
        reason_message,
        detail_format_id,
        detail)
    VALUES (
        160 /* EventCode.SettingUpdated */,
        now(),
        COALESCE(v_namespace_id, 1),
        p_actor_code,
        p_actor_key,
        NULL,
        NULL,
        NULL,
        NULL,
        v_definition_id,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        p_reason_message,
        1 /* JobPayloadFormat.Json */,
        convert_to('{"name":"' || p_name || '"}', 'UTF8'));

    RETURN QUERY SELECT 1 /* AdminControlAction.Applied */::SMALLINT, v_version;
END;
$$;

-- Version-CAS consume of an applied operator command: a miss means a newer command superseded the row
-- mid-apply and survives for the next tick. See IOutboxSignalStore.ConsumeAsync.
CREATE OR REPLACE FUNCTION acta.consume_outbox_signal(p_job_id BIGINT, p_name VARCHAR, p_expected_version INT)
RETURNS TABLE (out_consumed BIGINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_count BIGINT;
BEGIN
    DELETE FROM acta.checkpoints c
    WHERE
        c.job_id = p_job_id
        AND c.kind_code = 20 /* JobCheckpointKindCode.Signal */
        AND c.name = p_name
        AND c.version = p_expected_version;

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN QUERY SELECT v_count;
END;
$$;

-- The applying tick's read of one pending operator command; empty when the inbox slot is free.
CREATE OR REPLACE FUNCTION acta.get_outbox_signal(p_job_id BIGINT, p_name VARCHAR)
RETURNS TABLE (out_value_format_id SMALLINT, out_value BYTEA, out_version INT)
LANGUAGE plpgsql
AS $$
BEGIN
    RETURN QUERY
    SELECT c.value_format_id::SMALLINT, c.value, c.version
    FROM acta.checkpoints c
    WHERE
        c.job_id = p_job_id
        AND c.kind_code = 20 /* JobCheckpointKindCode.Signal */
        AND c.name = p_name
        AND c.status_code = 20 /* JobCheckpointStatusCode.Set */;
END;
$$;

-- Park admission for the sys.outbox operator inbox: insert when the slot is free, supersede when the
-- pending command has outlived the worker-dead window, reject otherwise. See IOutboxSignalStore.ParkAsync.
CREATE OR REPLACE FUNCTION acta.park_outbox_signal(
    p_job_id BIGINT,
    p_name VARCHAR,
    p_value_format_id SMALLINT,
    p_value BYTEA,
    p_stale_before_utc TIMESTAMPTZ
)
RETURNS TABLE (out_action SMALLINT, out_pending_since_utc TIMESTAMPTZ)
LANGUAGE plpgsql
AS $$
BEGIN
    INSERT INTO acta.checkpoints (job_id, kind_code, name, status_code, value_format_id, value, modified_at_utc, version)
    VALUES (
        p_job_id,
        20 /* JobCheckpointKindCode.Signal */,
        p_name,
        20 /* JobCheckpointStatusCode.Set */,
        p_value_format_id,
        p_value,
        now(),
        0
    )
    ON CONFLICT (job_id, kind_code, name) DO UPDATE SET
        value_format_id = EXCLUDED.value_format_id,
        value = EXCLUDED.value,
        status_code = 20 /* JobCheckpointStatusCode.Set */,
        modified_at_utc = now(),
        version = checkpoints.version + 1
    WHERE checkpoints.modified_at_utc <= p_stale_before_utc;

    /* The minted command id inside p_value makes the payload unique, so value equality is the
       "my write landed" test; a losing park reads the incumbent's park instant as the rejection age. */
    RETURN QUERY
    SELECT
        (CASE WHEN c.value = p_value THEN 1 /* ControlAction.Applied */ ELSE 3 /* ControlAction.Rejected */ END)::SMALLINT,
        c.modified_at_utc
    FROM acta.checkpoints c
    WHERE c.job_id = p_job_id AND c.kind_code = 20 /* JobCheckpointKindCode.Signal */ AND c.name = p_name;
END;
$$;

CREATE OR REPLACE FUNCTION acta.raise_signal(
    p_job_id BIGINT,
    p_kind_code SMALLINT,
    p_name VARCHAR,
    p_value_format_id SMALLINT,
    p_value BYTEA,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_code SMALLINT,
    p_reason_message VARCHAR
)
RETURNS TABLE (action SMALLINT, status_code SMALLINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_now TIMESTAMPTZ := now();
    v_existing SMALLINT;
    v_from_status SMALLINT;
    v_namespace_id SMALLINT;
    v_lineage_root_id BIGINT;
    v_definition_id INT;
    v_tenant_id INT;
    v_execution_number INT;
    v_audit_level SMALLINT;
    v_job_ref UUID;
BEGIN

    SELECT js.status_code INTO v_existing
    FROM acta.checkpoints js
    WHERE
        js.job_id = p_job_id
        AND js.kind_code = p_kind_code
        AND js.name = p_name
    FOR UPDATE;

    SELECT
        r.status_code,
        j.namespace_id,
        j.lineage_root_id,
        j.definition_id,
        j.tenant_id,
        r.execution_number,
        j.audit_level_code,
        j.job_ref
    INTO v_from_status, v_namespace_id, v_lineage_root_id, v_definition_id, v_tenant_id, v_execution_number, v_audit_level, v_job_ref
    FROM acta.runtimes r
    JOIN acta.jobs j ON j.id = r.job_id
    WHERE r.job_id = p_job_id
    FOR UPDATE OF r;

    IF v_from_status IS NULL THEN
        RETURN QUERY SELECT 2 /* ControlAction.NotFound */::SMALLINT, NULL::SMALLINT;
        RETURN;
    END IF;

    IF v_from_status IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */) THEN
        RETURN QUERY SELECT 3 /* ControlAction.Rejected */::SMALLINT, v_from_status;
        RETURN;
    END IF;

    INSERT INTO acta.checkpoints (
        job_id,
        kind_code,
        name,
        status_code,
        value_format_id,
        value,
        created_at_utc,
        modified_at_utc,
        version)
    VALUES (
        p_job_id,
        p_kind_code,
        p_name,
        20 /* JobCheckpointStatusCode.Set */,
        p_value_format_id,
        p_value,
        v_now,
        v_now,
        0)
    ON CONFLICT (job_id, kind_code, name) DO UPDATE SET
        status_code = 20 /* JobCheckpointStatusCode.Set */,
        value_format_id = EXCLUDED.value_format_id,
        value = EXCLUDED.value,
        modified_at_utc = v_now,
        version = acta.checkpoints.version + 1;

    IF v_audit_level = 20 /* JobAuditLevelCode.Audit */ THEN
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        VALUES (
            80 /* EventCode.JobSignalRaised */,
            v_now,
            v_namespace_id,
            p_actor_code,
            p_actor_key,
            p_job_id,
            v_job_ref,
            v_execution_number,
            COALESCE(v_lineage_root_id, p_job_id),
            v_definition_id,
            v_tenant_id,
            NULL,
            v_from_status,
            v_from_status,
            NULL,
            NULL,
            p_reason_code,
            p_reason_message);
    END IF;

    IF v_from_status = 20 /* JobStatusCode.Suspended */ THEN
        UPDATE acta.runtimes
        SET
            status_code = 10 /* JobStatusCode.Ready */,
            next_run_at_utc = v_now,
            modified_at_utc = v_now,
            version = version + 1
        WHERE job_id = p_job_id;

        IF v_audit_level = 20 /* JobAuditLevelCode.Audit */ THEN
            INSERT INTO acta.events (
                event_code,
                created_at_utc,
                namespace_id,
                actor_code,
                actor_key,
                job_id,
                job_ref,
                execution_number,
                lineage_root_id,
                definition_id,
                tenant_id,
                worker_id,
                from_status_code,
                to_status_code,
                execution_status_code,
                duration_ms,
                reason_code,
                reason_message)
            VALUES (
                72 /* EventCode.JobResumed */,
                v_now,
                v_namespace_id,
                p_actor_code,
                p_actor_key,
                p_job_id,
                v_job_ref,
                v_execution_number,
                COALESCE(v_lineage_root_id, p_job_id),
                v_definition_id,
                v_tenant_id,
                NULL,
                20 /* JobStatusCode.Suspended */,
                10 /* JobStatusCode.Ready */,
                NULL,
                NULL,
                p_reason_code,
                p_reason_message);
        END IF;

        RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, 10 /* JobStatusCode.Ready */::SMALLINT;
        RETURN;
    END IF;

    RETURN QUERY SELECT 1 /* ControlAction.Applied */::SMALLINT, v_from_status;
END;
$$;

-- Appends the applied-command evidence event against the sys.outbox slot job. Always emitted (no
-- audit-level gate): this is the trail for actions whose subject rows live in the producer's database.
CREATE OR REPLACE FUNCTION acta.record_outbox_event(
    p_job_id BIGINT,
    p_event_code SMALLINT,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_message VARCHAR
)
RETURNS VOID
LANGUAGE plpgsql
AS $$
BEGIN
    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        tenant_id,
        reason_message)
    SELECT
        p_event_code,
        now(),
        j.namespace_id,
        p_actor_code,
        p_actor_key,
        j.id,
        j.job_ref,
        r.execution_number,
        COALESCE(j.lineage_root_id, j.id),
        j.definition_id,
        j.tenant_id,
        p_reason_message
    FROM acta.jobs j
    JOIN acta.runtimes r ON r.job_id = j.id
    WHERE j.id = p_job_id;
END;
$$;

CREATE OR REPLACE FUNCTION acta.wait_signal(
    p_job_id BIGINT,
    p_kind_code SMALLINT,
    p_name VARCHAR
)
RETURNS TABLE (
    outcome_code SMALLINT,
    value_format_id SMALLINT,
    value BYTEA
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_now TIMESTAMPTZ := now();
    v_state SMALLINT;
    v_fmt SMALLINT;
    v_val BYTEA;
BEGIN
    SELECT js.status_code, js.value_format_id, js.value
    INTO v_state, v_fmt, v_val
    FROM acta.checkpoints js
    WHERE js.job_id = p_job_id AND js.kind_code = p_kind_code AND js.name = p_name
    FOR UPDATE;

    IF v_state = 20 /* JobCheckpointStatusCode.Set */ THEN
        RETURN QUERY SELECT
            2 /* SignalWaitOutcomeCode.ContinueSet */::SMALLINT,
            v_fmt,
            v_val;
    ELSE
        INSERT INTO acta.checkpoints (
            job_id,
            kind_code,
            name,
            status_code,
            value_format_id,
            value,
            created_at_utc,
            modified_at_utc,
            version)
        VALUES (
            p_job_id,
            p_kind_code,
            p_name,
            10 /* JobCheckpointStatusCode.Pending */,
            0 /* JobPayloadFormat.None */,
            NULL,
            v_now,
            v_now,
            0)
        ON CONFLICT (job_id, kind_code, name) DO NOTHING;

        RETURN QUERY SELECT
            1 /* SignalWaitOutcomeCode.SuspendPending */::SMALLINT,
            0 /* JobPayloadFormat.None */::SMALLINT,
            NULL::BYTEA;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION acta.start_execution(
    p_id BIGINT,
    p_leased_by_worker_id INT,
    p_execution_number INT,
    p_version INT,
    p_lease_ttl_seconds INT
)
RETURNS SMALLINT
LANGUAGE sql
AS $$
    WITH updated AS (
        UPDATE acta.runtimes r
        SET
            status_code = 50 /* JobStatusCode.Executing */,
            lease_expires_at_utc = now() + (p_lease_ttl_seconds * INTERVAL '1 second'),
            modified_at_utc = now(),
            version = r.version + 1
        FROM acta.jobs j
        WHERE
            r.job_id = p_id
            AND j.id = p_id
            AND r.execution_number = p_execution_number
            AND r.version = p_version
            AND r.status_code = 40 /* JobStatusCode.Dispatched */
            AND r.leased_by_worker_id = p_leased_by_worker_id
            AND r.lease_expires_at_utc > now()
        RETURNING r.job_id AS id, j.namespace_id, j.lineage_root_id, j.definition_id, j.tenant_id, r.execution_number, j.audit_level_code, j.job_ref
    ),

    event_insert AS (
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            job_ref,
            execution_number,
            lineage_root_id,
            definition_id,
            tenant_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        SELECT
            40 /* EventCode.JobExecutionStarted */,
            now(),
            u.namespace_id,
            70 /* ActorCode.Worker */,
            NULL,
            u.id,
            u.job_ref,
            u.execution_number,
            COALESCE(u.lineage_root_id, u.id),
            u.definition_id,
            u.tenant_id,
            p_leased_by_worker_id,
            40 /* JobStatusCode.Dispatched */,
            50 /* JobStatusCode.Executing */,
            50 /* ExecutionStatusCode.Executing */,
            NULL,
            NULL,
            NULL
        FROM updated u
        WHERE u.audit_level_code = 20 /* JobAuditLevelCode.Audit */
        RETURNING 1
    ),
    current AS (
        SELECT r.status_code, r.leased_by_worker_id, r.execution_number, r.version, r.lease_expires_at_utc
        FROM acta.runtimes r
        WHERE r.job_id = p_id
    )
    SELECT
        CASE
            WHEN EXISTS (SELECT 1 FROM updated) THEN 1 /* StartExecutionAction.Started */
            WHEN NOT EXISTS (SELECT 1 FROM current) THEN 4 /* StartExecutionAction.AlreadyTerminal */
            WHEN (SELECT status_code FROM current) IN (
                100 /* JobStatusCode.Succeeded */,
                200 /* JobStatusCode.Failed */,
                220 /* JobStatusCode.Cancelled */
            ) THEN 4 /* StartExecutionAction.AlreadyTerminal */
            WHEN (SELECT leased_by_worker_id FROM current) <> p_leased_by_worker_id
              OR (SELECT leased_by_worker_id FROM current) IS NULL THEN 2 /* StartExecutionAction.NotOwner */
            WHEN (SELECT execution_number FROM current) <> p_execution_number THEN 3 /* StartExecutionAction.LostClaim */
            WHEN (SELECT version FROM current) <> p_version THEN 3 /* StartExecutionAction.LostClaim */
            WHEN (SELECT status_code FROM current) = 40 /* JobStatusCode.Dispatched */
             AND (SELECT lease_expires_at_utc FROM current) <= now() THEN 5 /* StartExecutionAction.LeaseExpired */
            ELSE 4 /* StartExecutionAction.AlreadyTerminal */
        END::SMALLINT AS action;
$$;

CREATE OR REPLACE FUNCTION acta.start_step(
    p_job_id BIGINT,
    p_name VARCHAR,
    p_at_most_once BOOLEAN
)
RETURNS TABLE (
    outcome_code SMALLINT,
    attempt_number SMALLINT,
    version INT,
    next_retry_at_utc TIMESTAMPTZ,
    result_format_id SMALLINT,
    result BYTEA,
    reason_code SMALLINT,
    reason_message VARCHAR
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_now TIMESTAMPTZ := now();
    v_state SMALLINT;
    v_attempt SMALLINT;
    v_version INT;
    v_next TIMESTAMPTZ;
    v_rfid SMALLINT;
    v_result BYTEA;
    v_rcode SMALLINT;
    v_rmsg VARCHAR;
BEGIN

    SELECT
        a.status_code,
        a.attempt_number,
        a.version,
        a.next_retry_at_utc,
        a.result_format_id,
        a.result,
        a.reason_code,
        a.reason_message
    INTO v_state, v_attempt, v_version, v_next, v_rfid, v_result, v_rcode, v_rmsg
    FROM acta.steps a
    WHERE
        a.job_id = p_job_id
        AND a.name = p_name
    FOR UPDATE;

    IF NOT FOUND THEN
        INSERT INTO acta.steps (
            job_id,
            name,
            status_code,
            attempt_number,
            result_format_id,
            created_at_utc,
            modified_at_utc,
            version)
        VALUES (
            p_job_id,
            p_name,
            10 /* JobStepStatusCode.Pending */,
            1,
            0 /* JobPayloadFormat.None */,
            v_now,
            v_now,
            0)
        RETURNING steps.attempt_number, steps.version
        INTO v_attempt, v_version;

        RETURN QUERY SELECT 1 /* StartStepOutcomeCode.Invoke */::SMALLINT, v_attempt, v_version,
            NULL::TIMESTAMPTZ, 0 /* JobPayloadFormat.None */::SMALLINT, NULL::BYTEA, NULL::SMALLINT, NULL::VARCHAR;
    ELSIF v_state = 100 /* JobStepStatusCode.Succeeded */ THEN

        RETURN QUERY SELECT 3 /* StartStepOutcomeCode.ReplaySuccess */::SMALLINT, v_attempt, v_version,
            NULL::TIMESTAMPTZ, v_rfid, v_result, NULL::SMALLINT, NULL::VARCHAR;
    ELSIF v_state = 200 /* JobStepStatusCode.Exhausted */ THEN

        RETURN QUERY SELECT 4 /* StartStepOutcomeCode.Exhausted */::SMALLINT, v_attempt, v_version,
            NULL::TIMESTAMPTZ, 0 /* JobPayloadFormat.None */::SMALLINT, NULL::BYTEA, v_rcode, v_rmsg;
    ELSIF v_state = 230 /* JobStepStatusCode.Interrupted */ THEN
        -- Terminal at-most-once ambiguity from an earlier replay; re-throw consistently, no mutation.
        RETURN QUERY SELECT 5 /* StartStepOutcomeCode.Interrupted */::SMALLINT, v_attempt, v_version,
            NULL::TIMESTAMPTZ, 0 /* JobPayloadFormat.None */::SMALLINT, NULL::BYTEA, NULL::SMALLINT, NULL::VARCHAR;
    ELSIF v_next IS NOT NULL AND v_next > v_now THEN

        RETURN QUERY SELECT 2 /* StartStepOutcomeCode.Suspend */::SMALLINT, v_attempt, v_version,
            v_next, 0 /* JobPayloadFormat.None */::SMALLINT, NULL::BYTEA, NULL::SMALLINT, NULL::VARCHAR;
    ELSIF p_at_most_once THEN
        -- Pending slot re-entered on replay under AtMostOnce: the worker died after start_step recorded
        -- the pending row but before complete_step. Do not re-invoke; terminalize the row Interrupted
        -- (one transition, one version bump) and let the orchestration throw StepInterruptedException.
        UPDATE acta.steps a
        SET
            status_code = 230 /* JobStepStatusCode.Interrupted */,
            reason_code = 63 /* JobEventReasonCode.JobStepInterrupted */,
            reason_message = 'At-most-once step re-entered before completion; outcome unknown.',
            modified_at_utc = v_now,
            version = a.version + 1
        WHERE
            a.job_id = p_job_id
            AND a.name = p_name
        RETURNING a.version INTO v_version;

        RETURN QUERY SELECT 5 /* StartStepOutcomeCode.Interrupted */::SMALLINT, v_attempt, v_version,
            NULL::TIMESTAMPTZ, 0 /* JobPayloadFormat.None */::SMALLINT, NULL::BYTEA, NULL::SMALLINT, NULL::VARCHAR;
    ELSE
        UPDATE acta.steps a
        SET
            attempt_number = a.attempt_number + 1,
            modified_at_utc = v_now,
            version = a.version + 1
        WHERE
            a.job_id = p_job_id
            AND a.name = p_name
        RETURNING a.attempt_number, a.version INTO v_attempt, v_version;

        RETURN QUERY SELECT 1 /* StartStepOutcomeCode.Invoke */::SMALLINT, v_attempt, v_version,
            NULL::TIMESTAMPTZ, 0 /* JobPayloadFormat.None */::SMALLINT, NULL::BYTEA, NULL::SMALLINT, NULL::VARCHAR;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION acta.register_tenant(
    p_tenant_key VARCHAR,
    p_display_name VARCHAR,
    p_description VARCHAR
)
RETURNS TABLE (tenant_id INT)
LANGUAGE plpgsql
AS $$
BEGIN
    -- Two statements on purpose: each statement in a VOLATILE plpgsql body takes a fresh snapshot,
    -- so the SELECT sees the concurrently committed same-key winner that made ON CONFLICT skip (a
    -- single-statement sql body shares one snapshot across both arms and returns no row then).
    INSERT INTO acta.tenants
        (tenant_key, display_name, description, status_code, created_at_utc, modified_at_utc, version)
    VALUES (p_tenant_key, p_display_name, p_description, 10 /* TenantStatusCode.Active */, now(), now(), 0)
    ON CONFLICT (tenant_key) DO NOTHING;

    RETURN QUERY SELECT t.id FROM acta.tenants t WHERE t.tenant_key = p_tenant_key;
END;
$$;

-- CREATE OR REPLACE across arities creates an overload instead of replacing; drop the retired
-- four-parameter signature so pre-existing installs cannot resolve the stale upsert form.
DROP FUNCTION IF EXISTS acta.register_tenant(VARCHAR, VARCHAR, VARCHAR, SMALLINT);

CREATE OR REPLACE FUNCTION acta.resume_tenant(
    p_tenant_key VARCHAR,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_message VARCHAR
)
RETURNS TABLE (action SMALLINT, version INT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_id INT;
    v_status SMALLINT;
    v_version INT;
BEGIN
    SELECT t.id, t.status_code, t.version
    INTO v_id, v_status, v_version
    FROM acta.tenants t
    WHERE t.tenant_key = p_tenant_key
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* AdminControlAction.NotFound */::SMALLINT, NULL::INT;
        RETURN;
    END IF;

    IF v_status = 10 /* TenantStatusCode.Active */ THEN
        RETURN QUERY SELECT 3 /* AdminControlAction.AlreadyInState */::SMALLINT, v_version;
        RETURN;
    END IF;

    UPDATE acta.tenants AS t
    SET
        status_code = 10 /* TenantStatusCode.Active */,
        modified_at_utc = now(),
        version = t.version + 1
    WHERE t.id = v_id
    RETURNING t.version INTO v_version;

    -- namespace_id 1 is the seeded sys namespace (M001).
    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        tenant_id,
        worker_id,
        from_status_code,
        to_status_code,
        execution_status_code,
        duration_ms,
        reason_code,
        reason_message)
    VALUES (
        11 /* EventCode.TenantResumed */,
        now(),
        1,
        p_actor_code,
        p_actor_key,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        v_id,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        p_reason_message);

    RETURN QUERY SELECT 1 /* AdminControlAction.Applied */::SMALLINT, v_version;
END;
$$;

CREATE OR REPLACE FUNCTION acta.suspend_tenant(
    p_tenant_key VARCHAR,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_message VARCHAR
)
RETURNS TABLE (action SMALLINT, version INT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_id INT;
    v_status SMALLINT;
    v_version INT;
BEGIN
    SELECT t.id, t.status_code, t.version
    INTO v_id, v_status, v_version
    FROM acta.tenants t
    WHERE t.tenant_key = p_tenant_key
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* AdminControlAction.NotFound */::SMALLINT, NULL::INT;
        RETURN;
    END IF;

    IF v_status = 20 /* TenantStatusCode.Suspended */ THEN
        RETURN QUERY SELECT 3 /* AdminControlAction.AlreadyInState */::SMALLINT, v_version;
        RETURN;
    END IF;

    UPDATE acta.tenants AS t
    SET
        status_code = 20 /* TenantStatusCode.Suspended */,
        modified_at_utc = now(),
        version = t.version + 1
    WHERE t.id = v_id
    RETURNING t.version INTO v_version;

    -- namespace_id 1 is the seeded sys namespace (M001).
    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        tenant_id,
        worker_id,
        from_status_code,
        to_status_code,
        execution_status_code,
        duration_ms,
        reason_code,
        reason_message)
    VALUES (
        10 /* EventCode.TenantSuspended */,
        now(),
        1,
        p_actor_code,
        p_actor_key,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        v_id,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        p_reason_message);

    RETURN QUERY SELECT 1 /* AdminControlAction.Applied */::SMALLINT, v_version;
END;
$$;

CREATE OR REPLACE FUNCTION acta.update_tenant(
    p_tenant_key VARCHAR,
    p_display_name VARCHAR,
    p_description VARCHAR,
    p_expected_version INT,
    p_actor_code SMALLINT,
    p_actor_key VARCHAR,
    p_reason_message VARCHAR
)
RETURNS TABLE (action SMALLINT, version INT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_id INT;
    v_version INT;
BEGIN
    SELECT t.id, t.version INTO v_id, v_version
    FROM acta.tenants t
    WHERE t.tenant_key = p_tenant_key
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN QUERY SELECT 2 /* AdminControlAction.NotFound */::SMALLINT, NULL::INT;
        RETURN;
    END IF;

    IF v_version <> p_expected_version THEN
        RETURN QUERY SELECT 4 /* AdminControlAction.VersionConflict */::SMALLINT, v_version;
        RETURN;
    END IF;

    UPDATE acta.tenants AS t
    SET
        display_name = p_display_name,
        description = p_description,
        modified_at_utc = now(),
        version = t.version + 1
    WHERE t.id = v_id
    RETURNING t.version INTO v_version;

    -- namespace_id 1 is the seeded sys namespace (M001).
    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        job_ref,
        execution_number,
        lineage_root_id,
        definition_id,
        tenant_id,
        worker_id,
        from_status_code,
        to_status_code,
        execution_status_code,
        duration_ms,
        reason_code,
        reason_message)
    VALUES (
        12 /* EventCode.TenantUpdated */,
        now(),
        1,
        p_actor_code,
        p_actor_key,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        v_id,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        NULL,
        p_reason_message);

    RETURN QUERY SELECT 1 /* AdminControlAction.Applied */::SMALLINT, v_version;
END;
$$;

CREATE OR REPLACE FUNCTION acta.arm_or_consume_sleep_timer(
    p_job_id BIGINT,
    p_name VARCHAR,
    p_delay_seconds INT DEFAULT NULL,
    p_resume_at_utc TIMESTAMPTZ DEFAULT NULL
)
RETURNS TABLE (
    outcome_code SMALLINT,
    due_at_utc TIMESTAMPTZ
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_now TIMESTAMPTZ := now();
    v_due TIMESTAMPTZ := COALESCE(p_resume_at_utc, now() + make_interval(secs => p_delay_seconds));
    v_state SMALLINT;
    v_existing_due TIMESTAMPTZ;
BEGIN

    PERFORM 1 FROM acta.runtimes r0 WHERE r0.job_id = p_job_id FOR UPDATE;

    SELECT jt.status_code, jt.due_at_utc INTO v_state, v_existing_due
    FROM acta.checkpoints jt
    WHERE
        jt.job_id = p_job_id
        AND jt.kind_code = 30 /* JobCheckpointKindCode.Timer */
        AND jt.name = p_name;

    IF v_state = 10 /* JobCheckpointStatusCode.Pending */ AND v_existing_due > v_now THEN

        RETURN QUERY SELECT 1 /* SleepOutcome.Suspend */::SMALLINT, v_existing_due;
    ELSIF v_state = 10 /* JobCheckpointStatusCode.Pending */ THEN

        UPDATE acta.checkpoints jt
        SET
            status_code = 100 /* JobCheckpointStatusCode.Consumed */,
            modified_at_utc = now(),
            version = jt.version + 1
        WHERE
            jt.job_id = p_job_id
            AND jt.kind_code = 30 /* JobCheckpointKindCode.Timer */
            AND jt.name = p_name;
        UPDATE acta.runtimes r2
        SET
            next_run_at_utc = NULL,
            modified_at_utc = now(),
            version = r2.version + 1
        WHERE r2.job_id = p_job_id;
        RETURN QUERY SELECT 2 /* SleepOutcome.Continue */::SMALLINT, NULL::TIMESTAMPTZ;
    ELSIF v_state IS NOT NULL THEN

        RETURN QUERY SELECT 2 /* SleepOutcome.Continue */::SMALLINT, NULL::TIMESTAMPTZ;
    ELSIF v_due <= v_now THEN

        RETURN QUERY SELECT 2 /* SleepOutcome.Continue */::SMALLINT, NULL::TIMESTAMPTZ;
    ELSIF EXISTS (SELECT 1 FROM acta.checkpoints jt WHERE jt.job_id = p_job_id AND jt.kind_code = 30 /* JobCheckpointKindCode.Timer */ AND jt.status_code = 10 /* JobCheckpointStatusCode.Pending */) THEN
        RETURN QUERY SELECT 3 /* SleepOutcome.Reject */::SMALLINT, NULL::TIMESTAMPTZ;
    ELSE
        INSERT INTO acta.checkpoints (
            job_id,
            kind_code,
            name,
            status_code,
            due_at_utc,
            created_at_utc,
            modified_at_utc,
            version)
        VALUES (
            p_job_id,
            30 /* JobCheckpointKindCode.Timer */,
            p_name,
            10 /* JobCheckpointStatusCode.Pending */,
            v_due,
            now(),
            now(),
            0);
        RETURN QUERY SELECT 1 /* SleepOutcome.Suspend */::SMALLINT, v_due;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION acta.extend_worker_leases(
    p_leased_by_worker_id INT,
    p_lease_ttl_seconds INT,
    p_draining BOOLEAN
)
RETURNS TABLE (job_id BIGINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_new_expiry TIMESTAMPTZ := now() + (p_lease_ttl_seconds * INTERVAL '1 second');
BEGIN
    UPDATE acta.workers
    SET
        last_seen_at_utc = now(),
        status_code = CASE WHEN p_draining AND status_code = 10 /* WorkerStatusCode.Active */
            THEN 80 /* WorkerStatusCode.Draining */ ELSE status_code END,
        modified_at_utc = now(),
        version = version + 1
    WHERE id = p_leased_by_worker_id;

    /* Push every in-flight execution lease forward. Deliberately no version bump: a lease refresh
       is not a claim-generation change, so a buffered claim still passes the start CAS. */
    RETURN QUERY
    UPDATE acta.runtimes r
    SET lease_expires_at_utc = v_new_expiry
    WHERE
        r.leased_by_worker_id = p_leased_by_worker_id
        AND r.status_code IN (40 /* JobStatusCode.Dispatched */, 50 /* JobStatusCode.Executing */)
    RETURNING r.job_id;
END;
$$;

CREATE OR REPLACE FUNCTION acta.mark_dead_workers(
    p_dead_after_seconds INT
)
RETURNS INT
LANGUAGE plpgsql
AS $$
DECLARE
    v_marked INT;
BEGIN
    WITH doomed AS (
        SELECT id
        FROM acta.workers
        WHERE
            status_code = 10 /* WorkerStatusCode.Active */
            AND last_seen_at_utc < now() - (p_dead_after_seconds * INTERVAL '1 second')
        FOR UPDATE SKIP LOCKED
    ),

    dead AS (
        UPDATE acta.workers w
        SET
            status_code = 200 /* WorkerStatusCode.Dead */,
            modified_at_utc = now(),
            version = version + 1
        FROM doomed d
        WHERE w.id = d.id
        RETURNING w.id, w.namespace_id, w.worker_ref
    ),

    evt AS (
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            execution_number,
            lineage_root_id,
            definition_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        SELECT
            122 /* EventCode.WorkerDied */,
            now(),
            d.namespace_id,
            70 /* ActorCode.Worker */,
            d.worker_ref::TEXT,
            NULL,
            NULL,
            NULL,
            NULL,
            d.id,
            NULL,
            NULL,
            NULL,
            NULL,
            101 /* JobEventReasonCode.WorkerHeartbeatStale */,
            NULL
        FROM dead d
        RETURNING 1
    )

    SELECT count(*) INTO v_marked FROM dead;
    RETURN v_marked;
END;
$$;

CREATE OR REPLACE FUNCTION acta.start_worker(
    p_name VARCHAR,
    p_owner_team VARCHAR,
    p_description VARCHAR,
    p_catalog_hash VARCHAR,
    p_status_code SMALLINT,
    p_deployment_version VARCHAR,
    p_host VARCHAR,
    p_engine_version VARCHAR,
    p_dotnet_version VARCHAR,
    p_process_id INT,
    p_max_concurrency INT,
    p_worker_ref UUID
)
RETURNS TABLE (namespace_id SMALLINT, worker_id INT)
LANGUAGE sql
AS $$
    WITH ns_upsert AS (
        INSERT INTO acta.namespaces (
            name,
            owner_team,
            description,
            catalog_hash,
            status_code,
            created_at_utc,
            modified_at_utc,
            version)
        VALUES (
            p_name,
            p_owner_team,
            p_description,
            p_catalog_hash,
            p_status_code,
            now(),
            now(),
            0)
        ON CONFLICT (name) DO UPDATE SET
            owner_team = EXCLUDED.owner_team,
            description = EXCLUDED.description,
            catalog_hash = EXCLUDED.catalog_hash,
            modified_at_utc = now(),
            version = acta.namespaces.version + 1
        WHERE acta.namespaces.catalog_hash IS DISTINCT FROM EXCLUDED.catalog_hash
        RETURNING id
    ),
    ns AS (
        SELECT id FROM ns_upsert
        UNION ALL
        SELECT id FROM acta.namespaces
        WHERE
            name = p_name
            AND NOT EXISTS (SELECT 1 FROM ns_upsert)
    ),
    w AS (
        INSERT INTO acta.workers (
            namespace_id,
            worker_ref,
            status_code,
            deployment_version,
            host,
            engine_version,
            dotnet_version,
            process_id,
            max_concurrency,
            last_seen_at_utc,
            created_at_utc,
            modified_at_utc,
            version)
        SELECT
            ns.id,
            p_worker_ref,
            10 /* WorkerStatusCode.Active */,
            p_deployment_version,
            p_host,
            p_engine_version,
            p_dotnet_version,
            p_process_id,
            p_max_concurrency,
            now(),
            now(),
            now(),
            0
        FROM ns
        RETURNING id, namespace_id, worker_ref
    ),
    evt AS (
        INSERT INTO acta.events (
            event_code,
            created_at_utc,
            namespace_id,
            actor_code,
            actor_key,
            job_id,
            execution_number,
            lineage_root_id,
            definition_id,
            worker_id,
            from_status_code,
            to_status_code,
            execution_status_code,
            duration_ms,
            reason_code,
            reason_message)
        SELECT
            120 /* EventCode.WorkerStarted */,
            now(),
            w.namespace_id,
            70 /* ActorCode.Worker */,
            w.worker_ref::TEXT,
            NULL,
            NULL,
            NULL,
            NULL,
            w.id,
            NULL,
            NULL,
            NULL,
            NULL,
            NULL,
            NULL
        FROM w
        RETURNING 1
    )
    SELECT w.namespace_id AS namespace_id, w.id AS worker_id FROM w;
$$;

CREATE OR REPLACE FUNCTION acta.stop_worker(
    p_namespace_id SMALLINT,
    p_worker_id INT
)
RETURNS VOID
LANGUAGE sql
AS $$
    WITH stopped AS (
        UPDATE acta.workers
        SET
            status_code = 100 /* WorkerStatusCode.Stopped */,
            modified_at_utc = now(),
            version = version + 1
        WHERE
            id = p_worker_id
            AND status_code IN (10 /* WorkerStatusCode.Active */, 80 /* WorkerStatusCode.Draining */)
        RETURNING id, worker_ref
    )
    INSERT INTO acta.events (
        event_code,
        created_at_utc,
        namespace_id,
        actor_code,
        actor_key,
        job_id,
        execution_number,
        lineage_root_id,
        definition_id,
        worker_id,
        from_status_code,
        to_status_code,
        execution_status_code,
        duration_ms,
        reason_code,
        reason_message)
    SELECT
        121 /* EventCode.WorkerStopped */,
        now(),
        p_namespace_id,
        70 /* ActorCode.Worker */,
        s.worker_ref::TEXT,
        NULL,
        NULL,
        NULL,
        NULL,
        s.id,
        NULL,
        NULL,
        NULL,
        NULL,
        100 /* JobEventReasonCode.WorkerCleanShutdown */,
        NULL
    FROM stopped s;
$$;

CREATE OR REPLACE FUNCTION acta.purge_expired_data(
    p_namespace_id SMALLINT,
    p_events_retention_days INT,
    p_alert_retention_days INT,
    p_worker_retention_seconds INT,
    p_batch_size INT,
    p_max_iterations INT
)
RETURNS TABLE (jobs_deleted INT, events_deleted INT, alerts_deleted INT, workers_deleted INT, locks_deleted INT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_now TIMESTAMPTZ := now();
    v_jobs INT := 0;
    v_events INT := 0;
    v_alerts INT := 0;
    v_workers INT := 0;
    v_locks INT := 0;
    v_rows INT;
    v_iter INT;
    v_events_cutoff TIMESTAMPTZ := now() - make_interval(days => p_events_retention_days);
    v_alerts_cutoff TIMESTAMPTZ := now() - make_interval(days => p_alert_retention_days);
    v_worker_cutoff TIMESTAMPTZ := now() - make_interval(secs => p_worker_retention_seconds);
    v_ids BIGINT[];
    v_lock_keys TEXT[];
BEGIN
    v_rows := 1;
    v_iter := 0;
    WHILE v_rows > 0 AND v_iter < p_max_iterations LOOP
        SELECT array_agg(q.id) INTO v_ids FROM (
            SELECT j.id FROM acta.jobs j
            JOIN acta.runtimes r ON r.job_id = j.id
            WHERE
                r.namespace_id = p_namespace_id
                AND r.status_code IN (100 /* JobStatusCode.Succeeded */, 200 /* JobStatusCode.Failed */, 220 /* JobStatusCode.Cancelled */)
                AND r.retention_until_utc IS NOT NULL
                AND r.retention_until_utc <= v_now
                -- Lineage guard: parent_id carries no FK, so purging a parent whose children still
                -- exist would orphan their lineage (same rule as the manual purge_job). Only leaves
                -- delete; a fully-expired subtree drains bottom-up across iterations.
                AND NOT EXISTS (SELECT 1 FROM acta.jobs c WHERE c.parent_id = j.id)
            ORDER BY r.retention_until_utc, r.job_id
            LIMIT p_batch_size
            FOR UPDATE OF j, r SKIP LOCKED) q;
        v_rows := COALESCE(cardinality(v_ids), 0);
        IF v_rows > 0 THEN
            PERFORM 1 FROM acta.schedules s WHERE s.job_id = ANY(v_ids) ORDER BY s.id FOR UPDATE;
            DELETE FROM acta.tags t
            WHERE
                (t.scope_code = 50 /* TagScopeCode.Job */ AND t.scope_id = ANY(v_ids))
                OR (t.scope_code = 60 /* TagScopeCode.Schedule */ AND t.scope_id IN (
                    SELECT s.id FROM acta.schedules s WHERE s.job_id = ANY(v_ids)));
            DELETE FROM acta.jobs j WHERE j.id = ANY(v_ids);
        END IF;
        v_jobs := v_jobs + v_rows;
        v_iter := v_iter + 1;
    END LOOP;

    v_rows := 1;
    v_iter := 0;
    WHILE v_rows > 0 AND v_iter < p_max_iterations LOOP
        SELECT array_agg(q.id) INTO v_ids FROM (
            SELECT id FROM acta.events
            WHERE
                namespace_id = p_namespace_id
                AND created_at_utc <= v_events_cutoff
            ORDER BY created_at_utc, id
            LIMIT p_batch_size
            FOR UPDATE SKIP LOCKED) q;
        v_rows := COALESCE(cardinality(v_ids), 0);
        IF v_rows > 0 THEN
            DELETE FROM acta.tags
            WHERE
                scope_code = 90 /* TagScopeCode.Event */
                AND scope_id = ANY(v_ids);
            DELETE FROM acta.events WHERE id = ANY(v_ids);
        END IF;
        v_events := v_events + v_rows;
        v_iter := v_iter + 1;
    END LOOP;

    v_rows := 1;
    v_iter := 0;
    WHILE v_rows > 0 AND v_iter < p_max_iterations LOOP
        SELECT array_agg(q.id) INTO v_ids FROM (
            SELECT id FROM acta.alerts
            WHERE
                namespace_id = p_namespace_id
                AND created_at_utc <= v_alerts_cutoff
                AND delivery_status_code IN (30 /* AlertDeliveryStatusCode.Suppressed */, 100 /* AlertDeliveryStatusCode.Delivered */, 200 /* AlertDeliveryStatusCode.Failed */)
            ORDER BY created_at_utc, id
            LIMIT p_batch_size
            FOR UPDATE SKIP LOCKED) q;
        v_rows := COALESCE(cardinality(v_ids), 0);
        IF v_rows > 0 THEN
            DELETE FROM acta.tags
            WHERE
                scope_code = 80 /* TagScopeCode.Alert */
                AND scope_id = ANY(v_ids);
            DELETE FROM acta.alerts WHERE id = ANY(v_ids);
        END IF;
        v_alerts := v_alerts + v_rows;
        v_iter := v_iter + 1;
    END LOOP;

    v_rows := 1;
    v_iter := 0;
    WHILE v_rows > 0 AND v_iter < p_max_iterations LOOP
        SELECT array_agg(q.id) INTO v_ids FROM (
            SELECT id FROM acta.workers
            WHERE
                namespace_id = p_namespace_id
                AND status_code IN (100 /* WorkerStatusCode.Stopped */, 200 /* WorkerStatusCode.Dead */)
                AND last_seen_at_utc <= v_worker_cutoff
            ORDER BY last_seen_at_utc, id
            LIMIT p_batch_size
            FOR UPDATE SKIP LOCKED) q;
        v_rows := COALESCE(cardinality(v_ids), 0);
        IF v_rows > 0 THEN
            DELETE FROM acta.tags
            WHERE
                scope_code = 70 /* TagScopeCode.Worker */
                AND scope_id = ANY(v_ids);
            DELETE FROM acta.workers WHERE id = ANY(v_ids);
        END IF;
        v_workers := v_workers + v_rows;
        v_iter := v_iter + 1;
    END LOOP;

    v_rows := 1;
    v_iter := 0;
    WHILE v_rows > 0 AND v_iter < p_max_iterations LOOP
        -- Stage the batch into a variable first (same shape as the sections above): a SKIP LOCKED
        -- subquery inlined into the DELETE may be re-evaluated per outer row, locking a different
        -- row each probe and deleting past the batch size.
        SELECT array_agg(q.lock_key) INTO v_lock_keys FROM (
            SELECT lock_key FROM acta.locks
            WHERE
                expires_at_utc <= v_now
            ORDER BY expires_at_utc
            LIMIT p_batch_size
            FOR UPDATE SKIP LOCKED) q;
        DELETE FROM acta.locks WHERE lock_key = ANY(v_lock_keys);
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        v_locks := v_locks + v_rows;
        v_iter := v_iter + 1;
    END LOOP;

    RETURN QUERY SELECT v_jobs, v_events, v_alerts, v_workers, v_locks;
END;
$$;

CREATE OR REPLACE FUNCTION acta.apply_tags(
    p_scope_code SMALLINT,
    p_lookup_id BIGINT,
    p_lookup_name VARCHAR,
    p_mutation SMALLINT,
    p_items_json VARCHAR
)
RETURNS TABLE (action SMALLINT)
LANGUAGE plpgsql
AS $$
DECLARE
    v_scope_id BIGINT;
    v_namespace_id SMALLINT;
BEGIN
    CASE p_scope_code
        WHEN 20 /* TagScopeCode.Tenant */ THEN
            SELECT t.id::BIGINT, NULL::SMALLINT INTO v_scope_id, v_namespace_id
            FROM acta.tenants t
            WHERE t.tenant_key = p_lookup_name
            FOR UPDATE;
        WHEN 30 /* TagScopeCode.Namespace */ THEN
            SELECT n.id::BIGINT, n.id INTO v_scope_id, v_namespace_id
            FROM acta.namespaces n
            WHERE n.name = p_lookup_name
            FOR UPDATE;
        WHEN 40 /* TagScopeCode.Definition */ THEN
            SELECT d.id::BIGINT, d.namespace_id INTO v_scope_id, v_namespace_id
            FROM acta.definitions d
            WHERE d.id = p_lookup_id
            FOR UPDATE;
        WHEN 50 /* TagScopeCode.Job */ THEN
            SELECT j.id, j.namespace_id INTO v_scope_id, v_namespace_id
            FROM acta.jobs j
            WHERE j.id = p_lookup_id
            FOR UPDATE;
        WHEN 60 /* TagScopeCode.Schedule */ THEN
            SELECT s.id, s.namespace_id INTO v_scope_id, v_namespace_id
            FROM acta.schedules s
            WHERE
                s.job_id = p_lookup_id
                AND s.name = p_lookup_name
            FOR UPDATE;
        WHEN 70 /* TagScopeCode.Worker */ THEN
            SELECT w.id::BIGINT, w.namespace_id INTO v_scope_id, v_namespace_id
            FROM acta.workers w
            WHERE w.id = p_lookup_id
            FOR UPDATE;
        WHEN 80 /* TagScopeCode.Alert */ THEN
            SELECT a.id, a.namespace_id INTO v_scope_id, v_namespace_id
            FROM acta.alerts a
            WHERE a.id = p_lookup_id
            FOR UPDATE;
        WHEN 90 /* TagScopeCode.Event */ THEN
            SELECT e.id, e.namespace_id INTO v_scope_id, v_namespace_id
            FROM acta.events e
            WHERE e.id = p_lookup_id
            FOR UPDATE;
        ELSE
            RAISE EXCEPTION 'Unsupported tag scope code %.', p_scope_code;
    END CASE;

    IF v_scope_id IS NULL THEN
        RETURN QUERY SELECT 2 /* TagMutationAction.NotFound */::SMALLINT;
        RETURN;
    END IF;

    IF p_mutation = 1 /* TagMutationKind.Replace */ THEN
        DELETE FROM acta.tags
        WHERE
            scope_code = p_scope_code
            AND scope_id = v_scope_id;

        INSERT INTO acta.tags(scope_code, scope_id, namespace_id, name, value, value_search)
        SELECT
            p_scope_code,
            v_scope_id,
            v_namespace_id,
            item->>'name',
            item->>'value',
            item->>'value_search'
        FROM jsonb_array_elements(p_items_json::JSONB) item;
    ELSIF p_mutation = 2 /* TagMutationKind.Upsert */ THEN
        IF EXISTS (
            SELECT 1
            FROM jsonb_array_elements(p_items_json::JSONB) item
            WHERE NOT EXISTS (
                SELECT 1 FROM acta.tags t
                WHERE
                    t.scope_code = p_scope_code
                    AND t.scope_id = v_scope_id
                    AND t.name = item->>'name'))
            AND (SELECT COUNT(*) FROM acta.tags t
                WHERE t.scope_code = p_scope_code AND t.scope_id = v_scope_id) >= 32 THEN
            RAISE EXCEPTION 'A target may carry at most 32 tags.';
        END IF;

        INSERT INTO acta.tags(scope_code, scope_id, namespace_id, name, value, value_search)
        SELECT
            p_scope_code,
            v_scope_id,
            v_namespace_id,
            item->>'name',
            item->>'value',
            item->>'value_search'
        FROM jsonb_array_elements(p_items_json::JSONB) item
        ON CONFLICT (scope_code, scope_id, name) DO UPDATE SET
            namespace_id = EXCLUDED.namespace_id,
            value = EXCLUDED.value,
            value_search = EXCLUDED.value_search;
    ELSIF p_mutation = 3 /* TagMutationKind.Remove */ THEN
        DELETE FROM acta.tags t
        USING jsonb_array_elements(p_items_json::JSONB) item
        WHERE
            t.scope_code = p_scope_code
            AND t.scope_id = v_scope_id
            AND t.name = item->>'name';
    ELSE
        RAISE EXCEPTION 'Unsupported tag mutation code %.', p_mutation;
    END IF;

    RETURN QUERY SELECT 1 /* TagMutationAction.Applied */::SMALLINT;
END;
$$;

CREATE OR REPLACE FUNCTION acta.acquire_lock(
    p_lock_key VARCHAR,
    p_job_id BIGINT,
    p_lease_ttl_seconds INT,
    p_hold_token UUID
)
RETURNS TABLE (hold_token UUID)
LANGUAGE sql
AS $$
    INSERT INTO acta.locks (lock_key, job_id, expires_at_utc, hold_token)
    VALUES (p_lock_key, p_job_id, now() + (p_lease_ttl_seconds * INTERVAL '1 second'), p_hold_token)
    ON CONFLICT (lock_key) DO UPDATE SET
        job_id = EXCLUDED.job_id,
        expires_at_utc = EXCLUDED.expires_at_utc,
        hold_token = EXCLUDED.hold_token
    WHERE locks.expires_at_utc <= now()
    RETURNING hold_token;
$$;

CREATE OR REPLACE FUNCTION acta.extend_lock(
    p_lock_key VARCHAR,
    p_hold_token UUID,
    p_lease_ttl_seconds INT
)
RETURNS TABLE (hold_token UUID)
LANGUAGE sql
AS $$
    UPDATE acta.locks
    SET expires_at_utc = now() + (p_lease_ttl_seconds * INTERVAL '1 second')
    WHERE lock_key = p_lock_key AND hold_token = p_hold_token
    RETURNING hold_token;
$$;

CREATE OR REPLACE FUNCTION acta.release_lock(
    p_lock_key VARCHAR,
    p_hold_token UUID
)
RETURNS TABLE (hold_token UUID)
LANGUAGE sql
AS $$
    DELETE FROM acta.locks
    WHERE lock_key = p_lock_key AND hold_token = p_hold_token
    RETURNING hold_token;
$$;

COMMIT;

